SELECT 'moj-all-verified-judgments-review-002-chunk-076' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c2eeb27f-c91a-58a2-86db-b2a5b84c2827","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -تستر على مصدر الكمية -مصادرة اجلوال املستخدم يف اجلرمية -صرف النظر عن مصادرة املبلغ- التعزير بالسجن واجللد والغرامة.","document_number":"34279956","case_number":"34328810","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/ 7 /25","year":"1434","subject":"مخدرات -ترويج -قات -تستر على مصدر الكمية -مصادرة اجلوال املستخدم يف اجلرمية -صرف النظر عن مصادرة املبلغ- التعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34279956 :‬تاريخه‪1434/ 7 /25 :‬هـ‬\n                            ‫رقم الدعوى‪34328810:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34342437‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬تســتر علــى مصــدر الكميــة ‪ -‬مصــادرة‬\n       ‫اجلــوال املســتخدم يف اجلرميــة ‪ -‬صــرف النظــر عــن مصــادرة املبلــغ‪-‬‬\n                                        ‫التعزيــر بالســجن واجللــد والغرامــة‪.‬‬\n\n\n\n\n                                      ‫قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليهــا ببيــع قــات بقصــد الترويــج‬\n       ‫واالجتــار وتســترها علــى املصــدر وطلــب إثبــات إدانتهــا مبــا أســند إليهــا‬\n       ‫ومعاقبتهــا بعقوبــة تعزيريــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n       ‫وإلغــاء الشــريحة وتعزيرهــا لقــاء التســتر ‪،‬مت القبــض علــى املدعــى‬\n       ‫عليهــا وتفتيشــها ومت العثــور علــى املبلــغ املرقــم بحوزتهــا وبتفتيــش املنــزل‬\n       ‫مت العثــور علــى قــات بالثالجــة وأثبــت التقريــر الكيميائــي الشــرعي‬\n       ‫إيجابيــة العينــة لنبــات القــات احملظــور وصادقــت املدعــى عليهــا علــى‬\n       ‫الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيرهــا بالســجن‬\n       ‫مــدة ســنتني وجلدهــا مائــة وخمســن جلــدة مفرقــة علــى دفعــات مقــدار‬\n       ‫كل دفعــة خمســون جلــدة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n       ‫وصــرف النظــر عــن مصــادرة املبلــغ املضبــوط وقنعــت املدعــى عليهــا‬\n\n‫‪449‬‬\n\f‫‪،‬وصــدق احلكــم مــن‬\n                 ‫واعتــرض املدعــي العــام بــدون الئحــة اعتراضيــة ُ‬\n                                              ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34328810‬وتاريــخ ‪ 1434/07/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341715750‬وتاريــخ ‪ 1434/07/16‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/07/25‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا قــدم املدعــي العــام ‪..... /‬الئحــة دعــوى عامــة ضــد ‪ ،..... /‬البالغــة‬\n‫مــن العمــر (‪ )54‬عام ـ ًا ‪ ،‬صوماليــة اجلنســية مبوجــب رخصــة اقامــة‬\n‫رقــم (‪ ،).....‬متزوجــة ‪ ،‬متعلمــة ‪ ،‬عاملــه منزليــة ‪ ،‬تقيــم يف الريــاض‬\n‫‪ ،‬أودعــت بســجن النســاء مبوجــب مذكــرة إحالــة ومتديــد توقيــف رقــم‬\n‫(‪ ).....‬وتاريخ ‪1434/5/ 18‬هـ اســتنادا للقرار الوزاري رقم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة واحلاضــرة برفقــه الســجانة ‪..... /‬والعســكري ‪......‬حيــث إنــه‬\n‫بتاريــخ ‪1434/5/7‬ه ـ قبــض علــى املذكــورة مــن قبــل إحــدى فــرق ادارة‬\n‫العمليــات مبكافحــة املخــدرات مبنطقــة الريــاض بعــد ورود معلومــات‬\n‫مــن أحــد املصــادر الســرية عــن وجودها يف حــي ‪ .....‬وقيامها بترويج نبات‬\n‫القــات احملظــور وتتواجــد علــى الهاتــف رقــم (‪ ).....‬فتــم االيعــاز للمصــدر‬\n‫باالتصــال بهــا وطلــب حزمــة مــن القــات مببلــغ (‪ )150‬مائــة وخمســن‬\n‫ريــال فوافقــت وطلبــت مــن املصــدر احلضــور إلــى منزلهــا وكان ذلــك‬\n‫علــى مســمع مــن أحــد أفــراد الفرقــة القابضــة عليــه مت انتقــال الفرقــة‬\n\n                                                                                      ‫‪450‬‬\n\f      ‫إلــى املوقــع احملــدد وعنــد الوصــول طلــب مــن املصــدر الترجــل مــن‬\n      ‫ســيارة الفرقــة بعــد أن مت تفتيشــه وتزويــده باملبلــغ املرقــم ثــم توجــه إلــى‬\n      ‫شــقتها وقابلهــا أمــام شــقتها وســلمها املبلــغ احلكومــي املرقــم وســلمت‬\n      ‫املذكــورة للمصــدر حزمــة يشــتبه أن تكــون مــن نبــات القــات احملظــور‬\n      ‫بلــغ وزنهــا (‪ )158‬مائــة وثمــان وخمســن جرامـ ًا وكان ذلــك علــى مــرأى‬\n      ‫مــن رقيــب الفرقــة فتــم ضبطهــا مــن قبــل املفتشــة النســائية و بتفتيشــها‬\n      ‫شــخصي ًا مــن قبــل املفتشــة النســائية لــم يعثــر معهــا علــى ممنوعــات و‬\n      ‫عثــر علــى جــوال نــوع يحمــل الرقــم املصنعــي (‪ ).....‬وهــو اجلــوال الــذي متــت‬\n      ‫عليــه عمليــة التفــاوض(مت طلــب حجــزه متهيــد ًا لطلــب مصادرتــه مبوجــب‬\n      ‫اخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1434/ 5/ 14‬هــ) وعثــر معهــا علــى املبلــغ‬\n      ‫املرقــم (جــرى مطابقتــه) كمــا عثــر علــى مبلــغ مالــي قــدرة(‪ )1850‬ألــف‬\n      ‫وثمــان مائــة وخمســن ريــال (مت طلــب حجــزه متهيــد ًا لطلــب مصادرتــه‬\n      ‫مبوجــب اخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1434/5 / 14‬هــ) وبعــد (اخــذ‬\n      ‫االذن الــازم) مت دخــول شــقتها و بتفتيشــها عثــر بالثالجــة علــى (‪)6‬‬\n      ‫ســت حــزم يشــتبه أن تكــون مــن نبــات القــات احملظــور بلــغ وزنهــا جميعــا‬\n                                      ‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرام ـاً‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم ( ‪ ).....‬لعــام‬\n      ‫‪1434‬ه ـ ايجابيــة مســتخلص عينــة األوراق النباتيــة املبيعــة واملضبوطــة‬\n      ‫لنبــات القــات وهــو مــن املــواد املدرجــة يف اجلــدول رقــم (‪ )4‬امللحــق بنظــام‬\n                                             ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالهــا األوليــة واســتجوابها اعترفــت بترويــج حزمــة مــن نبــات‬\n      ‫القــات وحيــازة مــا ضبــط منــه بقصــد ترويجــه وترويجهــا لنبــات القــات‬\n\n\n‫‪451‬‬\n\f‫يف الســابق واســتخدامها جلوالهــا يف عمليــة الترويــج ‪ .‬وقــد أســفرت‬\n‫إجــراءات التحقيــق عــن توجيــه االتهــام للمــرأة ‪...../‬ببيــع حزمــه مــن‬\n‫نبــات القــات احملظــور تــزن (‪ )158‬مائــة وثمــان وخمســن جرامـ ًا بقصــد‬\n‫االجتــار والترويــج وحيــازة (‪ )6‬ســت حــزم مــن نفــس النــوع تــزن جميعهــا‬\n‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرامـ ًا بقصــد االجتــار والترويــج‬\n‫وترويــج نبــات القــات يف الســابق املعاقــب عليــه وفــق قــرار مجلــس الوزراء‬\n‫رقــم (‪ )11‬لعــام ‪1373‬ه ـ وتســترها علــى مصــدر مــا باعتــه ومــا ضبــط‬\n                ‫املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ - 1‬مــا تضمنــه اعترافهــا حتقيقــا املنــوه عنــه املــدون علــى الصفحــات‬\n                  ‫رقــم (‪ )2-1‬و مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ‪.)22‬‬\n‫‪ -2‬مــا تضمنــه اعترافهــا يف محضــر ســماع اقوالهــا املنــوه عنــه املرفــق‬\n                                                               ‫لفــه رقــم (‪.)17-16‬‬\n‫‪ -3‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون علــى الصفحــة‬\n‫رقــم(‪ )11‬ومحضــر مطابقــة املبلــغ املرقــم علــى الصفحــة رقــم(‪ )4‬مــن‬\n                 ‫ملــف ضبــط اجــراءات االســتدالل املرفــق لفــة رقــم (‪.)1‬‬\n‫‪ - 4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                        ‫رقــم (‪. )23‬‬\n   ‫وببحث سوابقها اتضح عدم وجود سوابق مسجلة عليها حتى تاريخه‪.‬‬\n‫وحيــث إن مــا أقدمــت عليــه املذكــورة فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا لــذا أطلــب إثبــات إدانتهــا مبــا أســند إليهــا واحلكــم عليهــا‬\n                                                                              ‫باآلتــي‪:‬‬\n‫وفقــا للقــرار الــوزاري املشــار إليــه لقــاء مــا‬\n                                                  ‫‪ -1‬بعقوبــة تعزيريــة بحقهــا ً‬\n                                                                      ‫أســند إليهــا ‪.‬‬\n\n\n                                                                                          ‫‪452‬‬\n\f      ‫‪ -2‬مصــادرة اجلــوال املســتخدم يف اجلرميــة مــن نــوع ‪ ...‬ذو الرقــم املصنعــي‬\n                                                            ‫(‪ ).....‬الســتخدامه يف اجلرميــة‪.‬‬\n      ‫‪ -3‬إلغــاء الشــريحة الهاتفيــة املســتخدمة يف اجلرميــة ذات الرقــم (‪).....‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور حكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميم ســمو وزيــر الداخلية‬\n                                            ‫رقــم (‪ )9798‬وتاريــخ ‪1428/2/10- 9‬هــ‪.‬‬\n      ‫‪ -4‬بعقوبــة تعزيريــة لقــاء تســترها علــى مصــدر مــا باعتــه ومــا ضبــط‪.‬‬\n      ‫وبــاهلل التوفيــق وبســؤال املدعــى عليهــا عــن دعــوى املدعــي العــام اجابــت‬\n      ‫املدعــى عليهــا بلغــة عربيــة مفهومــة قائلــة مــا ذكــره املدعــي العــام يف‬\n      ‫ا فقــد قمــت ببيــع حزمــة مــن نبــات‬     ‫دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n      ‫القــات احملظــور تــزن (‪ )158‬مائــة وثمان خمســن جرامـ ًا بقصد االجتار‬\n      ‫والترويــح وحــزت (‪)6‬ســت حــزم مــن القــات احملظــور تــزن جميعهــا‬\n      ‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرام ـ ًا بقصــد الترويــج وروجــت‬\n      ‫نبــات القــات احملظــور يف الســابق وتســترت علــى مصــدر مــا بعتــه ومــا‬\n      ‫ضبــط واملبلــغ املضبــوط معــي وقــدره الــف وثمامنائــة وخمســن ريــا ًال هــو‬\n      ‫خــاص فينــي وليــس لــه عالقــة بترويــج القــات وليــس علــي ســوابق هكذا‬\n      ‫اجابــت وبطلــب البينــة مــن املدعــي العــام علــى ان املبلــغ املالــي وقــدره الف‬\n      ‫وثمامنائــة وخمســن ريــا ًال انــه من مصدر غير مشــروع فقــال املدعي العام‬\n      ‫ليــس لــدي ســوى مــا يف أوراق املعاملــة وباالطــاع علــى اوراق املعاملــة‬\n      ‫وجــدت تقريــر كيميائــي شــرعي رقــم ( ‪ ).....‬لعــام ‪1434‬ه ـ واملتضمــن‬\n      ‫ـاء علــى مــا‬‫ايجابيــة العينتــن املرســلتني للمــواد الفعالــة لنبــات القــات فبنـ ً‬\n      ‫تقــدم مــن الدعــوى واالجابــة وحيــث اقــرت املدعــى عليهــا بصحــة دعــوى‬\n      ‫املدعــي العــام وحيــث ان مــا أقدمــت عليــه فعــل محــرم تســتحق عليــه‬\n\n\n‫‪453‬‬\n\f‫ـاء علــى قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪ 1374‬ه ـ وحيــث‬        ‫اجلــزاء وبنـ ً‬\n‫قــررت املدعــى عليهــا ان املبلــغ املضبــوط املطلــوب مصادرتــه هــو خــاص‬\n‫بهــا وحيــث لــم يســتطع املدعــي العــام اثبــات عــدم مشــروعيته لهــذا كلــه‬\n‫‪ /‬أو ًال ـ ثبــت لــدي ادانــة املدعــى عليهــا ببيــع حزمــه مــن نبــات القــات‬\n‫احملظــور تــزن (‪)158‬مائــه وثمــان وخمســن جرام ـ ًا بقصــد االجتــار‬\n‫والترويــج وحيازتهــا (‪)6‬ســت حــزم مــن نفــس النــوع تــزن جميعهــا (‪)2124‬‬\n‫ألفــان ومائــة وأربــع وعشــرين جرامـ ًا بقصــد الترويج وترويــج نبات القات‬\n‫يف الســابق وتســترها علــى مصــدر مــا باعتــه ومــا ضبــط وقــررت تعزيرها‬\n‫بســجنها ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفهــا وجلدهــا مائة وخمســن‬\n‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة علــى ان يكــون‬\n‫بــن فتــرات اجللــد مــدة ال تقــل عــن عشــرة ايــام وتغرميهــا خمســمائة ريــال‬\n‫ومصــادرة اجلــوال املســتخدم يف اجلرميــة املذكــور يف الدعــوى والغــاء‬\n‫الشــريحة املســتخدمة يف اجلرميــة املذكــورة يف الدعــوى وعــدم صرفهــا‬\n‫لنفــس املشــتركة وابــاغ الشــركة مصــدرة الشــريحة بذلــك وامــا مــا‬\n‫يتعلــق بتعزيــره لقــاء التســتر فهــو داخــل يف العقوبــة التعزيريــة املذكــورة‬\n‫‪ .‬ثانيـ ًا ـ صــرف النظــر عــن مطالبــة املدعــي العــام مبصــادرة املبلــغ املالــي‬\n‫املضبــوط املذكــور يف الدعــوى ومبــا ذكــر حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام االعتــراض علــى‬\n‫ا اننــي‬ ‫احلكــم وطلــب التمييــز فأجبتــه لطلبــه ثــم قــرر املدعــي العــام قائـ ً‬\n‫اكتفــي بالئحــة الدعــوى العامــة فهــي الالئحــة االعتراضيــة هكــذا‬\n‫قــرر وقــررت املدعــى عليهــا القناعــة باحلكــم وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n\n\n                                                                                             ‫‪454‬‬\n\f      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقم ‪ 341715750‬وتاريخ ‪1434/9/6‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪/‬‬\n      ‫‪.....‬املســجل برقــم ‪ 34279956‬وتاريــخ ‪1434/7/25‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعــي العــام ضــد املــرأة‪(..... /‬صوماليــة اجلنســية) (‪ ).....‬التهامهــا‬\n      ‫بقضيــة قــات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أنــه لــم يتــم‬\n      ‫تصديــق صــورة الضبــط فيالحــظ هــذا مســتقبالً‪ 0‬واهلل املوفــق وصلــى‬\n                                      ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪455‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":449,"source_page_end":455,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"94743c1637cd20b8e798b199b423f7bed7208b08ea0f064fbee19695d5c63331","normalized_text_hash":"5a2a90916e58fae3b5fd26d90dd1a459eea90038bd91bf90e14b9d0094fdcf09","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p449-34279956"},{"id":"9ce5011b-ae0c-53d1-aeac-b3a7011c0c28","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة حشيش بقصد التعاطي -حد املسكر -محاكمته على اجلرمية ذات العقوبة األشد إذا ارتكب عدة جرائم معاقب عليها مبوجب نظام مكافحة املخدرات -التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال -تغليظ العقوبة خلطورة اجلرمية ولوجود سابقة من جنس اجلرمية املنظورة.","document_number":"34351504","case_number":"34337433","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالنماص","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/05","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة حشيش بقصد التعاطي -حد املسكر -محاكمته على اجلرمية ذات العقوبة األشد إذا ارتكب عدة جرائم معاقب عليها مبوجب نظام مكافحة املخدرات -التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال -تغليظ العقوبة خلطورة اجلرمية ولوجود سابقة من جنس اجلرمية املنظورة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34351504:‬تاريخه‪1434/11/05 :‬هـ‬\n                    ‫رقم الدعوى‪34337433 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35114763‬تاريخه‪1435/1/14 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة حشــيش بقصــد‬\n ‫التعاطــي ‪ -‬حــد املســكر ‪ -‬محاكمتــه علــى اجلرميــة ذات العقوبــة‬\n ‫األشــد إذا ارتكــب عــدة جرائــم معاقــب عليهــا مبوجــب نظــام مكافحــة‬\n ‫املخــدرات‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ومصــادرة‬\n ‫اجلــوال ‪ -‬تغليــظ العقوبــة خلطــورة اجلرميــة ولوجــود ســابقة مــن‬\n                                            ‫جنــس اجلرميــة املنظــورة‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -2‬الفقــرة األولــى مــن املــادة ‪ 62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                        ‫العقليــة ‪.‬‬\n             ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -4‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                        ‫العقليــة ‪.‬‬\n                    ‫‪ -5‬قرار مجلس الوزراء رقم ‪ 47‬تاريخ ‪1434/2/18‬هـ ‪.‬‬\n              ‫‪ -6‬برقية وزير الداخلية رقم ‪ 65980‬تاريخ ‪1428/10/22‬هـ ‪.‬‬\n\n\n\n\n                                                                                      ‫‪456‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وترويــج حبــوب‬\n      ‫اإلمفيتامــن وحيــازة حشــيش بقصــد التعاطــي وتعاطيــه لــه ‪ ،‬طلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وعقوبــة تعزيريــة‬\n      ‫وتشــديدها لتعدد ســوابقه ومنعه من الســفر ومصادرة اجلوال املســتخدم‬\n      ‫يف اجلرميــة وإلغــاء الشــريحة ورد املبلــغ املرقــم وفــق األنظمــة والتعليمــات‪،‬‬\n      ‫حيــث مت االتصــال مــن قبــل املصــدر باملدعــى عليــه وطلــب منــه حبوب ـ ًا‬\n      ‫محظــورة مببلــغ مالــي فوافــق املدعــى عليــه وكان ذلــك مبســمع أفــراد‬\n      ‫فرقــة املكافحــة وبنــاء عليــه مت ترقيــم املبلــغ وجتنيــد أحــد األفــراد‬\n      ‫ملرافقــة املصــدر إلــى منــزل املدعــى عليــه ومبقابلــة املدعــى عليــه قــام‬\n      ‫املصــدر بتســليم املدعــى عليــه املبلــغ املتفــق عليــه واســتلم منــه حبتــن‬\n      ‫يشــتبه أنهــا مــن احلبــوب احملظــورة ولــم يتــم القبــض عليــه يف حينــه خشــية‬\n      ‫انكشــاف املصــدر ويف مســاء يــوم آخــر وأثنــاء قيــام الفرقــة بعملهــا مت‬\n      ‫االشــتباه بشــخص يســير علــى قدميــه يف أحــد األماكــن املظلمــة وعنــد‬\n      ‫التوقــف عنــده حــاول الهــرب وقــام برمــي كيــس يف يــده فتــم القبــض‬\n      ‫عليــه ومبعاينــة مــا قــام برميــه ضبطــت قطعــة يشــتبه أن تكــون مــن‬\n      ‫احلشــيش كمــا ضبــط معــه جــوال ‪ .....‬فاتضــح أنــه املدعــى عليــه ‪،‬‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينتــن ملادتــي احلشــيش‬\n      ‫املخــدر واإلمفيتامــن صــادق املدعــى عليــه علــى الدعــوى ماعــدا ترويــج‬\n      ‫احلبــوب احملظــورة بينــة املدعــي العــام شــهود مــن الفرقــة القابضــة‬\n      ‫شــهدت بترويــج املدعــى عليــه للحبــوب احملظــورة ومبــا أن املدعــى عليــه‬\n      ‫صــادق علــى حيــازة احلشــيش بقصــد التعاطــي وتعاطــي احلشــيش ‪ ،‬وبنــاء‬\n\n‫‪457‬‬\n\f‫علــى شــهادة الشــاهدين ‪ ،‬ولكــون مــا صــدر مــن املدعــى عليــه يعــد مــن‬\n‫اإلفســاد يف األرض ‪ ،‬ولوجــود ســوابق علــى املدعــى عليــه ممــا يســتدعي‬\n‫تعزيــره تعزيــرا بالغـ ًا ‪ ،‬احلكــم علــى املدعــى عليــه بحــد املســكر بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة لقــاء تعاطــي احلشــيش ‪ ،‬تعزيــره بالســجن‬\n‫خمــس ســنوات وجلــده مائتــن وخمســن جلــدة مفرقــة علــى دفعــات‬\n‫كل دفعــة خمســن ‪ ،‬تغرميــه ألــف ريــال ‪ ،‬منــع املدعــى عليــه مــن الســفر‬\n‫إلــى اخلــارج بعــد تنفيــذ العقوبــة مــدة مماثلــة لســجنه‪ ،‬ومصــادرة هاتفــه‬\n‫اجلــوال املســتخدم يف الترويــج وإيــداع قيمتــه يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات وإلغــاء الشــريحة وفــق األنظمــة والتعليمــات ‪،‬‬\n‫إلزامــه بــرد املبلــغ احلكومــي املرقــم وقــدره مائــة ريــال ‪ ،‬قنــع املدعــي‬\n‫العــام واعتــرض املدعــى عليــه بالئحــة ‪ُ ،‬صــدق احلكــم مــن الدائــرة‬\n                                    ‫اجلزائيــة الرابعــة مبحكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة العامــة‬\n‫بالنمــاص وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالنمــاص برقــم ‪ 34337433‬وتاريــخ ‪ 1434/07/22‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341759169‬وتاريــخ ‪ 1434/07/22‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/08/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام ‪.....‬مبوجــب‬\n‫خطــاب التعميــد رقــم‪.....‬يف ‪1434/2/26‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫يف مجلــس احلكــم ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ـاء‬\n‫‪.....‬قائــا يف حتريــر دعــواه أنــه عنــد الســاعة الثامنــة والنصــف مسـ ً‬\n\n                                                                                    ‫‪458‬‬\n\f      ‫ـاء علــى ما توفر مــن معلومات لدى مكافحة‬            ‫بتاريــخ ‪1434/2/14‬ه ـ وبنـ ً‬\n      ‫املخــدرات مبحافظــة النمــاص عــن أن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n      ‫احملظــورة يف محافظــة ‪ ،‬فقــد مت إعــداد اخلطــة الالزمــة وبالتنســيق مــع‬\n      ‫املصــدر مت االتصــال مــن قبــل املصــدر باملدعــى عليــه علــى جوالــه رقــم‬\n      ‫(‪ ).....‬وطلــب منــه حبوب ـ ًا محظــورة مببلــغ (‪ )100‬مائــة ريــال فوافــق‬\n      ‫ـاء عليــه مت ترقيــم‬ ‫املدعــى عليــه وكان ذلــك مبســمع أفــراد الفرقــة وبنـ ً‬\n      ‫املبلــغ احلكومــي وجتنيــد أحــد األفــراد ملرافقــة املصــدر إلــى منــزل‬\n      ‫املدعــى عليــه ‪ ،‬ومبقابلــة املدعــى عليــه قــام املصــدر بتســليم املدعــى‬\n      ‫عليــه املبلــغ املتفــق عليــه واســتلم منــه (‪ )2‬حبتــن يشــتبه أنهــا مــن احلبــوب‬\n      ‫احملظــورة وكان ذلــك أمــام نظــر الفــرد املرافــق للمصــدر ولــم يتــم‬\n      ‫القبض عليه يف حينه خشية انكشاف املصدر وبتاريخ ‪1434/5/24‬هـ‬\n      ‫ـاء وأثنــاء قيــام الفرقــة امليدانيــة ملكافحــة‬ ‫وعنــد الســاعة التاســعة مسـ ً‬\n      ‫املخــدرات مبحافظــة النمــاص بعملهــا يف مركــز ثلــوث املنظــر مت‬\n      ‫االشــتباه يف شــخص يســير علــى قدميــه يف أحــد األماكــن املظلمــة‬\n      ‫وعنــد التوقــف عنــده الحــظ أفــراد الدوريــة فحــاول الهــرب وقــام برمــي‬\n      ‫كيــس يف يــده فتمــت الســيطرة والقبــض عليــه ومبعاينــة مــا قــام برميــه‬\n      ‫ضبطــت قطعــة ســمراء اللــون وزنهــا (‪)9‬جــم تســعة جرامــات يشــتبه أن‬\n      ‫تكــون مــن احلشــيش املخــدر كمــا ضبــط معــه جــوال نــوع ‪...‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ ).....‬واتضــح بأنــه املدعــى عليــه أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي رقــم (‪ ).....‬لعــام ‪1434‬ه ـ احتــواء احلبتــن‬\n      ‫املضبوطتــن اللتــن قــام املدعــى عليــه بترويجهــا بتاريــخ ‪1434/2/14‬ه ـ‬\n      ‫علــى اإلمفيتامــن كمــا أثبــت التقريــر الكيمائــي الشــرعي رقــم (‪).....‬‬\n      ‫لعــام ‪1434‬ه ـ أن عينــة املــادة املضبوطــة بتاريــخ ‪1433/5/24‬ه ـ حشــيش‬\n\n\n‫‪459‬‬\n\f‫مخــدر وحتتــوي علــى املــادة الفعالــة لــه ‪ .‬ومادتــا اإلمفيتامــن واحلشــيش‬\n‫املخــدر مــن املــواد املدرجــة بجــداول املــواد املخــدرة واملؤثــرات العقليــة‬\n‫باجلــدول (‪ )2‬الثانــي الفئــة (ب) واجلــدول (‪ )1‬األول الفئــة (أ) املرفقــة‬\n‫بتعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء‬\n‫وزيــر الداخليــة رقــم (‪ )74831‬وتاريــخ ‪1431/7/9‬ه ـ وبإســتجواب‬\n‫املدعــى عليــه ‪ /‬أقــر بحيــازة قطعــة احلشــيش املخــدر البالــغ وزنهــا (‪)9‬جــم‬\n‫تســعة جرامــات املضبوطــة معــه بتاريــخ ‪1434/5/24‬ه ـ بقصــد التعاطــي‬\n‫وأنــه حصــل عليهــا مببلــغ (‪ )100‬مائــة ريــال مــن شــخص مجهــول الهويــة‬\n‫يســكن يف أحــد اجلبــال وأنــه قبــل القبــض عليــه حــاول الهــرب مــن أفــراد‬\n‫الدوريــة وقــام برمــي قطعــة احلشــيش املضبوطــة وأقــر بأنــه يتعاطــى‬\n‫احلشــيش املخــدر منــذ ثالثــة أشــهر تقريب ـ ًا وأن آخــر مــرة تعاطــى فيهــا‬\n‫احلشــيش املخــدر كان قبــل القبــض عليــه بثالثــة أيــام تقريبـ ًا وأن عليــه‬\n‫ســابقة ترويــج مخــدرات قبــل أربــع ســنوات تقريبـ ًا وصــدق إقــراره بذلــك‬\n‫شــرع ًا كمــا أقــر حتقيقـ ًا بــأن رقــم اجلــوال (‪ ).....‬يخصــه دون غيــره وأنــه‬\n‫مســجل باســمه لــدى االتصــاالت الســعودية وأقــر حتقيق ـ ًا بتعاطيــه‬\n‫الشــراب املســكر وأن آخــر مــرة تعاطــاه كان قبــل ســنة تقريبـ ًا وبعرض‬\n‫املدعــى عليــه علــى الفــرد املرافــق للمصــدر الشــاهد علــى عمليــة بيــع‬\n‫املدعــى عليــه احلبــوب احملظــورة بتاريــخ ‪1434/2/14‬ه ـ اســتطاع‬\n‫التعــرف عليــه وأنــه هــو مــن قــام بتســليم املصــدر احلبــوب املتفــق عليهــا‬\n‫واســتالم املبلــغ احلكومــي وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫للمدعــى عليــه ‪ /‬بشــرب املســكر ‪ ،‬وبترويــج (‪ )2‬حبتــن حتتويــان علــى‬\n‫مــادة االمفيتامــن املنبهــة واحملظــورة عــن طريــق البيــع ‪ ،‬وبحيــازة قطعــة‬\n‫حشــيش مخــدر وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد التعاطــي ‪،‬‬\n\n\n                                                                                       ‫‪460‬‬\n\f      ‫وبتعاطيــه احلشــيش املخــدر لألدلــة والقرائــن التاليــة ‪-1 :‬مــا ورد يف‬\n      ‫إقــراره املصــدق شــرع ًا بحيازتــه قطعــة احلشــيش املخــدر بقصــد التعاطي‬\n      ‫وتعاطيــه لــه ‪ ،‬املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )4‬مــن فباالطالع‬\n      ‫علــى محضــري الشــراء والقبــض والتفتيــش تبــن ملــف التحقيــق املرفــق‬\n      ‫حتقيقــا بعائديــة رقــم اجلــوال املنــوه عنــه‬\n                                                 ‫ً‬      ‫برقــم (‪-2 )14‬مــا ورد يف إقــراره‬\n      ‫إليــه شــخصي ًا وبتعاطيــه للمســكر ‪ ،‬املنــوه عنهمــا واملدونــان علــى‬\n      ‫الصفحتــن رقــم (‪ )5‬ورقــم (‪ )8‬مــن ملــف التحقيــق املرفــق برقــم (‪)14‬‬\n      ‫‪-3‬مــا تضمنــاه محضــرا الشــراء والقبــض والتفتيــش املنــوه عنهمــا‬\n      ‫واملدونــان علــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل املرفــق برقــم‬\n      ‫(‪ )1‬وعلــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل املرفــق برقــم (‪)7‬‬\n      ‫‪-4‬مــا تضمنــه محضــر التعــرف علــى املدعــى عليــه املنــوه عنــه واملرفــق‬\n      ‫برقــم (‪-5 )32‬مــا تضمنــاه التقريــران الكيميائيــان الشــرعيان املنــوه‬\n      ‫عنهمــا واملرفقــان برقــم (‪ )5‬ورقــم (‪ )27‬وحيــث إن مــا أقــدم عليــه املدعى‬\n      ‫عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ونظامـ ًا ومجــرم مبوجــب الفقــرة (‪ )2‬الثانيــة مــن املــادة (‪ )3‬الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬واســتناد ًا للفقــرة (‪)1‬‬\n      ‫األولــى مــن املــادة (‪ )62‬الثانيــة والســتني مــن ذات النظــام لــذا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪-1 :‬جلــده ثمانــون جلــدة‬\n      ‫حــد املســكر ‪-2‬عقوبــة تعزيريــة بحقــه وفق ـ ًا ملــا تضمنتــه الفقــرة (‪)1‬‬\n      ‫األولــى مــن املــادة (‪ )38‬الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه بحدهــا األعلــى ‪ ،‬وتشــديدها بحقــه لتعــدد ســوابقه وعــدم‬\n      ‫ارتداعــه بعقوباتهــا ‪-3‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n\n\n‫‪461‬‬\n\f‫العقوبــة املقــررة بحقــه اســتناد ًا للفقــرة (‪ )1‬األولــى مــن املــادة (‪)56‬‬\n‫السادســة واخلمســن مــن ذات النظــام ‪-4‬مصــادرة جهــازه اجلــوال نــوع ‪.....‬‬\n‫يحمــل الرقــم التسلســلي (‪ ).....‬املســتخدم يف عمليــة الترويــج وفقا للفقرة‬\n‫(‪ )1‬األولــى مــن املــادة (‪ )53‬الثالثــة واخلمســن مــن النظــام املشــار إليــه‬\n‫وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وفق ـ ًا‬\n‫لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1431/2/18‬ه ـ وإلغــاء شــريحة‬\n‫االتصــال للرقــم (‪ ).....‬املســتخدمة يف اجلرميــة وعــدم صرفهــا لــه مــرة‬\n‫أخــرى وفقــا لتعميــم صاحــب الســمو امللكــي النائــب لرئيــس مجلــس‬\n‫الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ‬\n‫‪-5‬إلزامــه بدفــع مبلــغ (‪ )100‬مائــة ريــال املبلــغ احلكومــي املرقــم وفقـ ًا ملــا‬\n‫تضمنتــه برقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه عمــا جــاء يف دعــوى املدعــي العــام أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام مــن أنــه قبــض علــي يف املــكان والتاريــخ وأننــي قمــت‬\n‫بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪ )9‬تســعة جرامــات بقصــد‬\n‫التعاطــي وبتعاطــي احلشــيش املخــدر فهــذا صحيــح أمــا مــا ذكــره مــن‬\n‫أننــي قمــت بترويــج حبتــن مــن مــادة األمفيتامــن املنبهــة عــن طريــق البيع‬\n‫فغيــر صحيــح وبســؤال املدعــي العــام عــن البينــة التــي تثبــت صحــة دعــواه‬\n‫بــأن املدعــى عليــه قــام بترويــج حبتــن مــن احلبــوب احملظــورة قــال أطلــب‬\n‫مهلــة إلحضــار الفرقــة القابضــة وعليــه رفعــت اجللســة وتأجلــت إلــى يــوم‬\n‫الثالثــاء املوافــق ‪1434/8/23‬ه ـ الســاعة التاســعة والنصــف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/08/21‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضي‬\n\n\n                                                                                         ‫‪462‬‬\n\f      ‫باحملكمــة العامــة بالنمــاص وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بالنمــاص برقــم ‪ 34337433‬وتاريــخ‬\n      ‫‪ 1434/07/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341759169‬وتاريــخ‬\n      ‫‪ 1434/07/22‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/11/05‬هـ افتتحت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وجــرى ســؤال املدعــي العــام عــن البينــة التــي وعــد بإحضارهــا قــال‬\n      ‫أحضــرت للشــهادة وأدائهــا كال مــن ‪ ..........‬ســعودي اجلنســية بالســجل‬\n      ‫املدنــي رقــم ‪.....‬وبســؤاله عــن عمــره ومحــل إقامتــه وصلتــه بالطرفــن‬\n      ‫أجــاب مــن مواليــد عــام ‪1394‬ه ـ ومحــل إقامتــي ‪ ......‬وليــس لــي صلــة‬\n      ‫بالطرفــن ‪..... .‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫وبســؤاله عــن عمــره ومحــل إقامتــه وصلتــه باملدعــى عليــه أجــاب مــن‬\n      ‫مواليــد عــام ‪1392‬ه ـ ومحــل إقامتــي ‪ .......‬وليــس لــي صلة قرابــة باملدعى‬\n      ‫عليــه وباستشــهادهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫مبفــرده قائــا واهلل العظيــم أنــه يف يــوم اخلميــس املوافــق ‪1434/2/14‬هـ‬\n      ‫وأثنــاء قيامنــا بالعمــل امليدانــي توفــرت لدينــا معلومــة مــن أحــد مصادرنــا‬\n      ‫الســرية عــن شــخص يقــوم بترويــج احلبــوب احملظــورة يســكن يف‬\n      ‫محافظــة ‪ .........‬طريــق ‪.....‬يدعــى ‪.......... /‬وعندهــا مت إعــداد اخلطــة‬\n      ‫الالزمــة وعندهــا مت االتصــال عليــه مــن جــوال املصــدر علــى جــوال املروج‬\n      ‫رقــم (‪ ).....‬وطلــب منــه حبــوب محظــورة مببلــغ مائــة ريــال فوافــق املــروج‬\n      ‫علــى ذلــك وكان علــى مســمع مــن أفــراد الفرقــة فتــم ترقيــم املبلــغ‬\n      ‫احلكومــي كمــا يتضــح مــن صفحــة رقــم (‪ )4‬وجتنيــد أحــد أراد الفرقــة‬\n      ‫املرافقــة املصــدر إلــى منــزل املــروج فتــم االنتقــال إلــى املوقــع املتفــق عليــه‬\n      ‫ـاءا وعنــد الوصــول‬   ‫وكان ذلــك يف متــام الســاعة الثامنــة والنصــف مسـ ً‬\n\n‫‪463‬‬\n\f‫إلــى املوقــع خــرج املــروج مــن منزلــه وقــام املصــدر بالنــزول مــن الســيارة‬\n‫ومقابلــة املــروج وعندهــا قــام املصــدر بتســليمه املبلــغ املتفــق عليــه‬\n‫واســتالم احلبــوب احملظــورة وكان ذلــك أمــام نظــر الفــرد املرافــق‬\n‫وعندهــا حظــر املصــدر إلــى الفــرد املرافــق وســلمه عــدد حبتــن حتمــل‬\n‫العالمــة املميــزة لعقــار الكبتاجــون فتــم االنتقــال مــن املوقــع وأرجــيء‬\n‫القبــض علــى املــروج خشــية انكشــاف املصــدر وحرصــه الشــديد‬\n‫وعندهــا مت التحفــظ علــى املضبوطــات وتســليمها لضابــط خفــر املنــاوب‬\n‫يف الشــعبة طرفنــا هكــذا شــهدا وبعــرض الشــاهدين ومــا جــاء يف‬\n‫شــهادتهما علــى املدعــى عليــه أجــاب قائــا أمــا الشــاهدين فــا أعرفهمــا‬\n‫وال أقــول فيهمــا إال خيــرا أمــا مــا جــاء يف شــهادتهما فغيــر صحيــح وقــد‬\n‫جــرى تعديــل الشــاهدين مــن قبــل كال مــن ‪.....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪.....‬و‪.....‬ســعودي بالســجل املدنــي رقــم ‪.....‬حيــث‬\n‫شــهدا بعدالــة وثقــة الشــاهدين هــذا وجــرى االطــاع علــى محضــر‬\n‫القبــض والتفتيــش وصحيفــة الســوابق والتقارير الكيميائية والشــرعية‬\n‫وإقــرار املدعــى عليــه املصــدق شــرعا فوجــدت أنهــا جميعــا مطابقــة ملــا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n                                            ‫جــاء يف دعــوى املدعــي العــام فبنـ ً‬\n‫املتضمنــة مصادقــة املدعــى عليــه علــى مــا ورد يف دعــوى املدعــي العــام‬\n‫مــن قيامــه بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪ )9‬جــم تســعة‬\n‫ـاء علــى شــهادة‬\n                ‫جرامــات بقصــد التعاطــي وبتعاطيــه احلشــيش املخــدر وبنـ ً‬\n‫الشــاهدين وفــق األصــول الشــرعية ولكــون مــا صــدر مــن املدعــى عليــه‬\n‫يعــد مــن اإلفســاد يف األرض نظـ ًـرا النتشــار تعاطــي املخــدرات بــن‬\n‫أوســاط الشــباب ونظـ ًـرا ملــا يترتــب عليهــا مــن آثــار ســيئة صحيــة ونفســية‬\n‫واجتماعيــة ونظـ ًـرا لوجــود ســبع ســوابق علــى املدعــى عليــه مــن نفــس‬\n\n\n                                                                                      ‫‪464‬‬\n\f      ‫النــوع ولــم تردعــه عقوبتهــا ممــا يســتوجب تعزيــره تعزيـ ًـرا بال ًغــا يردعــه‬\n      ‫ويزجــر غيــره لذلــك كلــه فقــد قــررت مــا يلــي أوالً‪ /‬إقامة حد املســكر‬\n      ‫علــى املدعــى عليــه وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة لقــاء إقــراره‬\n      ‫ثانيــا‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بترويــج‬\n                                                         ‫بتعاطــي احلشــيش املخــدر ً‬\n      ‫(‪ )2‬حبتــن مــن مــادة االمفيتامــن املنبهــة واحملظــورة وحيــازة قطعــة‬\n      ‫حشــيش مخــدر بلــغ وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد التعاطــي‬\n      ‫وقــررت تعزيــر املدعــى عليــه بالســجن ملــدة خمــس ســنوات تبــدأ مــن‬\n      ‫تاريــخ توقيفــه وجلــده مائتــي وخمســن جلــدة مفرقــة علــى دفعــات كل‬\n      ‫دفعــة خمســن جلــدة بــن الدفعــة والتــي تليهــا مــدة ال تقــل عــن عشــرة‬\n      ‫أيــام علــى أن يكــون اجللــد يف مــكان عــام وتغرميــه ألــف ريــال وذلــك‬\n      ‫اســتنا ًدا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات مــع مالحظــة أن‬\n      ‫تكــون هــذه العقوبــة شــاملة ملــا صــدر مــن املدعــى عليــه مــن قيامــه‬\n      ‫بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد‬\n      ‫التعاطــي وذلــك اســتنا ًدا للفقــرة األولــى مــن املــادة (‪ )62‬مــن النظــام‬\n      ‫املشــار إليــه والتــي تنــص علــى أنــه إذا ارتكــب شــخص عــدة جرائــم‬\n      ‫معاقــب عليهــا مبوجــب أحــكام هــذا النظــام قبــل صــدور حكــم نهائــي‬\n      ‫بحقــه عــن أي واحــدة منهــا وجــب محاكمتــه علــى اجلرميــة ذات العقوبــة‬\n      ‫األشــد واحلكــم بعقوبتهــا دون غيرهــا وبــه حكمــت ثال ًثــا‪ /‬قــررت منــع‬\n      ‫املدعــى عليــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة بحقــه مــدة‬\n      ‫مماثلــة ملــدة ســجنه وذلــك اســتنا ًدا للمــادة (‪ )56‬مــن النظــام املشــار إليــه‬\n      ‫رابعــا‪ /‬قــررت مصــادر جهــاز اجلــوال نــوع ‪ ........‬يحمــل‬  ‫وبــه حكمــت ً‬\n      ‫الرقــم التسلســلي (‪ ).....‬املســتخدم يف عمليــة الترويــج اســتنا ًدا للفقــرة‬\n      ‫األولــى مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه وإيــداع قيمتــه يف حســاب‬\n\n\n‫‪465‬‬\n\f‫اإلدارة العامــة ملكافحــة املخــدرات وفقــا لقــرار مجلــس الــوزراء رقــم‬\n‫(‪ )47‬يف ‪1431/2/18‬ه ـ وإلغــاء شــريحة االتصــال للرقــم (‪).....‬‬\n‫واملســتخدمة يف اجلرميــة وعــدم صرفهــا لــه مــرة أخــرى وبــه حكمــت‬\n‫خامســا‪ /‬إلزامــه بدفــع مبلــغ (‪ )100‬مائــة ريــال املبلــغ احلكومــي املرقــم‬\n                                                                           ‫ً‬\n‫وفقــا ملــا تضمنتــه برقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫‪ 65980/4/5/1‬يف ‪1428/10/22‬ه ـ وبــه حكمــت وبإعــان احلكــم‬\n‫علــى الطرفــن قــرر املدعــي العــام عــدم املعارضــة أمــا املدعــى عليــه‬\n‫فقــرر عــدم القناعــة وطلــب االســتئناف واســتعد بتقــدمي الئحــة اعتراضية‬\n‫وأجيــب لطلبــه وســلم نســخة مــن القــرار يف هــذا اليــوم وأفهــم بــأن مــدة‬\n‫االعتــراض ثالثــن يومــا تبــدأ مــن هــذا اليــوم ففهــم ذلــك وأقفلــت اجللســة‬\n‫يف متــام الســاعة احلاديــة عشــر والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/11/05‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القاضــي باحملكمــة العامــة بالنمــاص الشــيخ ‪..... /‬‬\n‫برقــم ‪ 341759169‬وتاريــخ ‪1434/12/29‬ه ـ املرفــق بها القرار الصادر‬\n‫مــن فضيلتــه برقــم ‪ 34351504‬وتاريــخ ‪1434/11/5‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ض ــد ‪..... /‬يف قضيــة (مخــدرات) علــى الصفــة املوضحة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‬\n         ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪466‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":456,"source_page_end":466,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13348a212f0ec82dd8dff04cd7e997bb7930e7a3ea5b0e00b7699cc26b37c587","normalized_text_hash":"14e5dad1cc7b98a6422376bbf893765d734e038ceb1617b4e97a6709fdd95e53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p456-34351504"},{"id":"c1186a79-1ef2-59b8-a292-7699ccd638f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -التعزير باجللد والسجن والغرامة. -1قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } .","document_number":"34314670","case_number":"34393987","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/8","year":"1434","subject":"مخدرات -ترويج -قات -التعزير باجللد والسجن والغرامة. -1قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه ‪1434/9/8 :‬هـ‬  ‫رقم الصك ‪34314670:‬‬\n                          ‫رقم الدعوى‪34393987:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34342200‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n                 ‫مخدرات ‪ -‬ترويج ‪ -‬قات ‪ -‬التعزير باجللد والسجن والغرامة‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } ‪.‬‬\n               ‫‪ -2‬املادة الثالثة من قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374‬هـ ‪.‬‬\n        ‫‪ -3‬قــرار مجلــس الــوزراء رقــم (‪ )172‬يف ‪1400/9/23‬ه ـ املتضمــن أن‬\n                    ‫العقوبــات الــواردة يف القــرار رقــم ‪ 11‬هــي احلــد األعلــى‪.‬‬\n                      ‫‪ -4‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ ‪.‬‬\n        ‫‪ -5‬خطــاب وزيــر الداخليــة املوجــه إلــى أميــر جــازان رقــم (‪)13476‬‬\n        ‫يف ‪1433/2/22‬ه ـ املتضمــن أن تقريــر العقوبــة هــو مــن اختصــاص‬\n                                                                        ‫احلا كــم‪.‬‬\n\n\n\n\n        ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا باالشــتراك يف ترويــج قــات‬\n        ‫بقصــد االجتــار عــن طريــق النقــل وتســترهما علــى املــروج ‪،‬حيــث‬\n        ‫اعترفــا بعــد القبــض عليهمــا لالشــتباه بأنهمــا قامــا بتســليم القــات‬\n        ‫لشــخصني ســعوديني وأن املدعــى عليــه األول اســتلم القــات واملدعــى‬\n        ‫عليــه الثانــي يقــوم مبســح الطريــق ويتواصــل مــع املســتلمني ‪ ،‬وطلــب‬\n        ‫إثبــات مــا أســند إليهمــا وتعزيرهمــا لقــاء الترويــج والتســتر علــى املــروج‬\n\n‫‪467‬‬\n\f‫ومصــادرة الســيارة واجلــوال واملبلــغ املالــي املتحصــل مــن اجلرميــة ‪ ،‬صــادق‬\n‫املدعــى عليهمــا علــى الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمة‬\n‫بتعزيرهمــا بالســجن ســنة ونصــف وتغــرمي كل واحــد منهمــا ألــف ريــال‬\n‫وبتعزيرهمــا بجلــد كل واحــد منهمــا خمســن جلــدة دفعــة واحــدة لقــاء‬\n‫التســتر وصــرف النظــر عــن طلبــات املدعــي العــام وقنــع املدعــى عليهمــا‬\n‫‪،‬وصــدق احلكــم‬  ‫باحلكــم واعتــرض املدعــي العــام بالئحــة اعتراضيــة ُ‬\n                                                     ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/9/7‬ه ـ ويف متــام الســاعة‬\n‫الثانيــة والنصــف ظهــر ًا افتتحــت اجللســة لدي أنــا ‪.....‬القاضي باحملكمة‬\n‫ـاء علــى املعاملــة احملالــة لنــا من فضيلــة رئيس احملكمة‬‫اجلزائيــة بأبهــا بنـ ً‬\n‫اجلزائيــة بأبهــا املســاعد برقــم ‪ 34393987‬يف ‪1434/8/23‬ه ـ واملقيــدة‬\n‫لدينــا برقــم ‪ 342032948‬يف ‪1434/8/23‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام ‪...../‬املكلــف مــن قبــل االدعــاء العــام مبوجــب أمــر التكليــف‬\n‫رقــم ‪.....‬يف ‪1430/9/9‬ه ـ ضــد الســجني ‪..... /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪.....‬والســجني ‪.....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــي ‪.....‬يف تهمــة حيــازة نبــات محظــور بقصــد االجتــار ‪ .‬وقــد‬\n‫تقــدم املدعــي العــام بدعــوى نــص احلاجــة منهــا باالطــاع علــى محضــر‬\n‫القبــض والتفتيــش املعــد مــن قبــل فرقــة مكافحــة املخــدرات مبنطقــة‬\n‫عســير تبــن أنــه بعــد ظهــر يــوم الســبت املوافــق ‪1434/8/6‬ه ـ توفــرت‬\n‫معلومــات لديهــم عــن قيــام شــخصني ســعوديني باســتالم وتســليم كميــة‬\n‫مــن املمنوعــات يف املــكان املســمى ‪.....‬علــى الطريق الرابط بــن ‪............‬‬\n\n                                                                                       ‫‪468‬‬\n\f      ‫و ‪ ...........‬فتمــت املتابعــة عــن طريــق التقنيــة املتاحــة واتضــح بــأن املســتلم‬\n      ‫لتلــك الكميــة ال يعــرف مــكان تواجــده وأمــا الــذي قــام بالتســليم‬\n      ‫اتضــح بأنــه عائــد ملدينــة ‪ ......‬وبعــد البحــث عنــه اتضــح بأنــه علــى طريــق‬\n      ‫‪ ...‬متجهــا إلــى طريــق ‪ ..............‬ومبســح الطريــق شــوهدت ســيارة مــن‬\n      ‫نــوع ‪ .......‬صنــع عــام (‪2013‬م) حتمــل اللوحــة رقــم (‪ ).....‬كانــت متوقفــة‬\n      ‫عنــد محطــة ‪.....‬للمحروقــات ب‪ .....‬وكان بهــا شــخصني فتــم اســتيقافها‬\n      ‫بعــد وصولهــا إلــى بوابــة مستشــفى الصحــة النفســية وقبــض علــى مــن‬\n      ‫بداخلهــا واتضــح بــأن قائــد الســيارة هــو املتهــم (‪ ).....‬ويرافقــه املتهــم‬\n      ‫(‪ ).....‬وبتفتيشــهما والســيارة املنــوه عنهــا لــم يعثــر علــى أي شــيء مــن‬\n      ‫املمنوعــات ‪ ،‬وبســماع أقوالهمــا اعترفــا بأنهمــا قامــا بتســليم كميــة‬\n      ‫مــن نبــات القــات احملظــور يقــدر عددهــا بســتمائة وســتة وســتني (‪)666‬‬\n      ‫حزمــة لشــخصني ســعوديني كان معهمــا ســيارة مــن نــوع (‪ ).......‬أبيــض‬\n      ‫قابالهمــا بعــد مثلــث ‪.....‬وأن (‪ ).....‬اســتلم كميــة القــات مــن عنــد‬\n      ‫كبــري ‪ .... ...‬مــن شــخص جيزانــي ال يعــرف عنــه شــيء وكانــت تلــك‬\n      ‫الكميــة محملــة يف ســيارة مــن نــوع ‪ ......‬بيضــاء اللــون ال يعــرف رقــم‬\n      ‫لوحتهــا والتــي كان يقــوم بقيادتهــا وأن (‪ ).....‬كان يقــود ‪ ......‬ويقــوم‬\n      ‫مبســح الطريــق ويتواصــل مــع املســتلمني للقــات بواســطة جوالــه رقــم‬\n      ‫(‪ . ).....‬وانتهــى التحقيــق الــى توجيــه االتهــام ل ـ ‪ ..... /‬و‪ ،.....‬باالشــتراك‬\n      ‫يف ترويــج كميــة تقــدر بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات‬\n      ‫القــات احملظــور لــم يتــم ضبطهــا عــن طريــق النقــل بقصــد االجتــار املادي‬\n      ‫‪ ،‬واحملــرم شــرع ًا واملجــرم نظام ـ ًا مبوجــب املــادة (الثالثــة) مــن قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ وتســترهما علــى مــروج القــات‬\n      ‫واحلائــز لــه بعــد اســتالمه املعاقــب عليــه شــرعا ‪ .‬وبالبحــث عن ســوابقهما‬\n\n\n‫‪469‬‬\n\f‫لــم يعثــر لهمــا علــى شــيء لــذا اطلب إثبــات إدانتهما باالشــتراك يف ترويج‬\n‫كميــة تقــدر بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات القــات‬\n‫احملظــور عــن طريــق النقــل واحلكــم عليهمــا بعقوبــة تعزيريــة تزجرهمــا‬\n‫وتــردع غيرهمــا وفقــا للمــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم ‪11‬‬\n‫لعــام ‪ 1374‬وتعزيرهمــا لقــاء تســترهما علــى مــروج القــات واحلائــز لــه‬\n‫بعــد االســتالم ومصــادرة الســيارة نــوع ‪ ......‬غمــارة صنــع عــام (‪2013‬م)‬\n‫حتمــل اللوحــة رقــم (‪ ).....‬واجلــوال ورقمــه املصنعــي (‪ ).....‬واملبلــغ املالــي‬\n‫املتحصــل مــن اجلرميــة وقــدره ألــف ريــال (‪ )1000‬وفــق املــادة (‪)1/53‬‬\n‫الثالثــة واخلمســون الفقــرة األولــى مــن نظــام املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليــه وإيــداع قيمتهــا بحســاب املديرية العامــة ملكافحة املخدرات‬\n‫لــدى مؤسســة النقــد وفقــا للفقــرة الثانيــة مــن قــرار مجلــس الــوزراء‬\n‫رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ ‪ .‬هكــذا ادعــى وبعــرض الدعــوى‬\n‫علــى املدعــى عليهمــا أجــاب كل واحــد بقولــه مــا جــاء يف الدعــوى مــن‬\n‫قيامنــا بنقــل كميــة القــات املوصوفــة يف الدعــوى مــن (‪ ).................‬إلــى‬\n‫مدينــة (‪ )..................‬بقصــد الترويــج مبقابــل مــادي صحيــح ومــا ذكــر‬\n‫املدعــي العــام مــن كوننــا قمنــا بالتســتر علــى املســلم واملســتلم لكميــة‬\n‫نبــات القــات فــا نعلــم عــن ذلــك شــيئ ًا علمـ ًا أننــا لــم نبلــغ عنهمــا اجلهــات‬\n‫األمنيــة وقــد أخذنــا مقابــل ذلــك مبلــغ مالــي قــدره الــف ريــال هكــذا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرره الطرفــان‬      ‫أجابــا‪ .‬فبنـ ً‬\n‫وألن املدعــى عليهمــا أقــرا بقيامهمــا بنقــل كميــة القــات املوصوفــة يف‬\n‫الدعــوى مبقابــل بقصــد الترويــج ونظــر ًا ألنهمــا أقــرا بأنهمــا لــم يقومــا‬\n‫بتبليــغ اجلهــات األمنيــة عــن الشــخص املســلم واملســتلم لكميــة القــات‬\n‫وألن هــذا العمــل يف حقيقتــه هــو تســتر مــن قبلهمــا علــى أمثــال هــؤالء‬\n\n\n                                                                                              ‫‪470‬‬\n\f      ‫والواجــب بحقهمــا التبليــغ عنهمــا واســتناد ًا علــى قــرار مجلــس الــوزراء‬\n      ‫رقــم ‪ 11‬يف ‪13747‬ه املــادة الثالثــة منــه وعلــى قــرار مجلــس الــوزراء‬\n      ‫رقــم ‪ 172‬يف ‪1400/9/23‬ه املتضمــن أن العقوبــات الــواردة يف القــرار‬\n      ‫رقــم ‪ 11‬هــي احلــد األعلــى واســتناد ًا علــى األمــر الســامي الكــرمي رقــم‬\n      ‫‪ 59633‬يف ‪1432/12/9‬ه وعلــى خطــاب ســمو وزيــر الداخليــة املوجــه‬\n      ‫إلــى ســمو أميــر منطقــة جــازان رقــم ‪ 13476‬يف ‪1433/2/22‬ه املتضمــن‬\n      ‫أن تقريــر العقوبــة هــو مــن اختصــاص احلاكــم ونظــر ًا ألن هــذا العمــل‬\n          ‫محــرم شــرع ًا وهــو مــن اإلفســاد يف األرض واملنهــي عنــه بقولــه تعالــى‬\n      ‫( وال تفســدوا يف األرض بعــد إصالحهــا ) وملنافــاة هــذا العمــل ملــا أمــر‬\n      ‫اهلل بحفظــه مــن العقــل واملــال ولــكل مــا تقــدم حكمــت مبــا يلــي أو ًال‬\n      ‫‪ :‬ثبــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف ترويــج كميــة تقــدر‬\n      ‫بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات القــات احملظــور لــم يتــم‬\n      ‫ضبطهــا عــن طريــق النقــل بقصــد االجتــار املادي ثانيـ ًا ‪ :‬حكمت بتعزير‬\n      ‫املدعــى عليهمــا بســجن كل واحــد منهمــا ملــدة ســنة ونصــف تبــدأ مــن‬\n      ‫تاريــخ إيقــاف كل واحــد يف هــذه القضيــة وبتغــرمي كل واحــد منهمــا‬\n      ‫ألــف ريــال تــودع يف خزينــة الدولــة كل ذلــك لقــاء نقلهمــا لكميــة القــات‬\n      ‫املوصوفــة يف الدعــوى ثالث ـ ًا حكمــت بتعزيــر كل واحــد منهمــا لقــاء‬\n      ‫التســتر باجللــد خمســن جلــدة دفعــة واحــدة رابع ـ ًا صرفــت النظــر عــن‬\n      ‫طلبــات املدعــي العــام تطبيــق املادة الثالثة واخلمســن مــن نظام املخدرات‬\n      ‫بحــق املدعــى عليهمــا ألنــه ال محــل لهــا حيــث اســتثنيت قضايــا القــات‬\n      ‫مــن هــذا النظــام باألمــر الســامي املشــار إليــه بعاليــه وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــى عليهمــا عــدم االعتــراض وقــرر املدعــي‬\n      ‫العــام عــدم القناعــة مســتعد ًا بتقــدمي الئحــة فجــرى تســليمه نســخة مــن‬\n\n\n‫‪471‬‬\n\f‫إعــام احلكــم وأفهمتــه أن لــه بعــد ذلــك ثالثــون يومـ ًا ليقــدم الئحتــه فــإن‬\n‫لــم يفعــل ســقط حقــه يف ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة‬\n‫االســتئناف بعســير لتدقيــق احلكــم كاملتبــع جــرى النطــق باحلكــم‬\n‫بتاريــخ ‪1434/9/7‬ه ـ ورفعــت اجللســة عنــد الســاعة الثالثــة وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد ‪.‬ويف يــوم اخلميــس ‪1434 / 11 /13‬ه ـ افتتحــت‬\n‫اجللســة يف متــام الســاعة احلاديــة عشــرة والربــع وفيهــا عــادت املعاملــة‬\n‫رفــق خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم‬\n‫‪ 342398152‬يف ‪1434/11/4‬ه ـ مرفقــا بهــا قــرار املالحظــة الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثالثــة رقــم ‪ 34342200‬يف ‪1434/ 10/27‬ه ـ‬\n‫املتضمــن نــص احلاجــة منــه مــا يلــي ( وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة أن فضيلتــه لــم ينــوه عــن الالئحــة االعتراضيــة املقدمــة مــن‬\n‫ا باملــادة ‪ 1/181‬مــن نظــام املرافعــات‬   ‫املدعــي العــام باالطــاع عليهــا عمـ ً‬\n‫الشــرعية فعلــى فضيلتــه إكمــال الــازم واهلل املوفــق )انتهــى بتوقيــع‬\n‫وختــم قاضــي اســتئناف الشــيخ ‪.....‬وبتوقيــع وختــم قاضــي اســتئناف‬\n‫الشــيخ ‪.....‬و بتوقيــع وختــم رئيــس الدائــرة الشــيخ ‪.....‬وأجيــب أصحــاب‬\n‫الفضيلــة وفقهــم اهلل بــأن ذلــك وقــع ســهوا وجــرى معاجلتــه يف مكانــه‬\n‫ولــذا جــرى مبوجبــه التهميــش وأمــرت برفــع املعاملــة الــى محكمــة‬\n‫اإلســتئناف للتدقيــق كاملتبــع ورفعــت اجللســة عنــد الســاعة احلاديــة‬\n                   ‫عشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بأبهــا برقــم ‪342398152‬‬\n\n\n                                                                                       ‫‪472‬‬\n\f      ‫وتاريخ ‪1434/11/23‬هـ املرفق بها القرار الصادر من فضيل ــة القاضي‬\n      ‫باحملكمــة الشــيخ‪..... /‬برقــم ‪ 34314670‬وتاريــخ ‪1434/9/8‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد كل مــن ‪...../‬و ‪.....‬يف قضيــة (‬\n      ‫قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلتــه واحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قــرار الدائــرة رقــم‬\n      ‫‪ 34342200‬وتاريــخ ‪1434/10/27‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪473‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":467,"source_page_end":473,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97075a67ca045ec9509bc52add710950967b70023cb475e9e3867115ae1c57e3","normalized_text_hash":"e0f0433b8ab17e0be8b5fa929dc5ee7bd756e1e169e8b100700f4c8b295d23df","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p467-34314670"},{"id":"19aaa460-1cec-5234-b9a8-2a0efeef43cf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -هروب املدعى عليه من رجال األمن - تستر على مصدر ما مت ضبطه -التعزير بالسجن واجللد والغرامة وإتاف الكمية املضبوطة -مصادرة السيارة.","document_number":"34325520","case_number":"34423794","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/24","year":"1434","subject":"مخدرات -ترويج -قات -هروب املدعى عليه من رجال األمن - تستر على مصدر ما مت ضبطه -التعزير بالسجن واجللد والغرامة وإتاف الكمية املضبوطة -مصادرة السيارة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34325520:‬تاريخه‪1434/9/24:‬هـ‬\n                   ‫رقم القضية‪34423794:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34344853‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬هــروب املدعــى عليــه مــن رجــال األمــن ‪-‬‬\n‫تســتر علــى مصــدر مــا مت ضبطــه ‪ -‬التعزيــر بالســجن واجللــد والغرامة‬\n                         ‫وإتــاف الكميــة املضبوطــة ‪ -‬مصــادرة الســيارة‪.‬‬\n\n\n\n\n                ‫‪ -1‬األمر السامي الكرمي رقم(‪ )59633‬يف ‪1432/12/9‬هـ ‪.‬‬\n  ‫‪ -2‬املادة الثالثة من قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n                      ‫‪ -3‬قرار مجلس الوزراء رقم (‪ )47‬يف ‪1421/2/18‬هـ ‪.‬‬\n                   ‫‪ -4‬قرار وزير الداخلية رقم(‪ )2057‬يف ‪ 1404/5/26‬هـ ‪.‬‬\n‫‪ -5‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫والهــروب مــن رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة بعــد‬\n‫هروبــه وتســتره علــى مصــدر مــا مت ضبطــه وطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم بتعزيــره وفــق املــادة الثالثــة مــن القــرار رقــم (‪ )11‬لعــام‬\n‫‪1374‬ه وتعزيــره لقــاء تســتره علــى مصــدر مــا مت ضبطــه وهروبــه مــن‬\n‫رجــال األمــن ومصــادرة ســيارته املســتخدمة يف اجلرميــة وذلــك أثنــاء قيــام‬\n\n                                                                                     ‫‪474‬‬\n\f      ‫الدوريــة األمنيــة بواجبهــا مت مشــاهدة ســيارة يقودهــا املدعــى عليــه‬\n      ‫وعنــد اســتيقافه رفــض االمتثــال والذ بالفــرار بســرعة عاليــة وأثنــاء‬\n      ‫املطــاردة كان الغبــار كثيف ـ ًا ممــا أدى إلــى انحــراف ســيارة الدوريــة‬\n      ‫وانقالبهــا وبعدهــا قــام املدعــى عليــه بإيقــاف الســيارة لتعطلهــا والذ‬\n      ‫بالفــرار وبتفتيــش الســيارة عثــر علــى كميــة مــن نبــات أخضــر يشــتبه‬\n      ‫أن يكــون مــن القــات وبعــد ذلــك مت القبــض عليــه وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n      ‫‪،‬صــادق املدعــى عليــه علــى االدعــاء املوجــه إليــه ‪،‬وبنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بســجنه خمــس ســنوات وجلــده ســبعمائة جلــدة علنــا‬\n      ‫مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة وغرامــة ماليــة قدرهــا‬\n      ‫عشــرة آالف ريــال تــودع لصالــح بيــت مــال املســلمني ومصــادرة وإتــاف‬\n      ‫القــات املضبــوط ومصــادرة الســيارة املســتخدمة يف اجلرميــة وإيــداع ثمنهــا‬\n      ‫يف حســاب اإلدارة العامــة ملكافحــة املخــدرات واعتــرض املدعــى عليــه‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬       ‫واملدعــي العــام بــدون الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫ـاء علــى أوراق املعاملــة‬\n                             ‫حاليــا بنـ ً‬\n                                      ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة بجــازان ً‬\n      ‫الــواردة مــن محكمــة االســتئناف مبنطقة عســير برقــم (‪)341901650‬‬\n      ‫وتاريــخ ‪1434/8/30‬ه ـ واملقيــدة بقيــد احملكمــة طرفنــا برقــم‬\n      ‫‪ 342146007‬يف ‪1434/9/8‬ه ـ واإلحالــة رقــم (‪ )34423794‬وتاريــخ‬\n      ‫‪1434/9/14‬ه ـ عطفـ ـ ًـا علــى رقــم الــورود الـس ــابق مــن هيئــة التحقيــق‬\n      ‫واالدعــاء العــام بـمنـطـق ــة ج ــازان بـرق ــم (‪ )309‬يف ‪1434/3/1‬ه ـ‬\n‫‪475‬‬\n\f‫واملقيــدة بقيــد األســاس رقــم (‪ )34562987‬يف ‪1434/3/4‬ه ـ واحملالــة‬\n‫إلــى املكتــب القضائــي الرابــع باحملكمــة طرفنــا مبوجــب اإلحالــة‬\n‫الســابقة رقــم (‪ )34107415‬والصــادر بهــا القــرار الشــرعي رقــم‬\n‫(‪ )3456645‬وتاريــخ ‪ 1434/3/7‬ه ـ واملنقــوض أخيـ ًـرا مــن محكمــة‬\n‫االســتئناف مبنطقــة عســير مبوجــب قــرار النقــض الصــادر مــن الدائــرة‬\n‫اجلزائيــة الرابعــة برقــم (‪)34294301‬وتاريــخ ‪1434/8/10‬ه ـ اخلاصــة‬\n‫بالســجني ‪ ...../‬املتهــم يف قضيــة قــات ؛ عليــه ففــي هــذا اليــوم الثالثــاء‬\n‫املوافــق ‪1434/9/15‬ه ـ افتتحــت اجللســة الســاعة العاشــرة والنصــف‬\n‫صباحــا بحضــور املدعــي العــام واملدعــى عليــه ؛ وجــرى م ّنــا اإلطــاع‬   ‫ً‬\n‫علــى الئحــة الدعــوى العامــة اخلطيــة املرفقــة بــأوراق املعاملــة املقدمــة مــن‬\n‫املدعــي العــام بدائــرة اإلدعــاء العــام بجــازان ‪..... /‬املوجــه إلينــا مبوجــب‬\n‫خطــاب التعميــد الصــادر مــن فــرع هيئــة التحقيــق واإلدعــاء العــام بجازان‬\n‫حرفيــا‬\n   ‫ً‬     ‫رقــم (‪ ).....‬وتاريــخ ‪1434/8/29‬ه ـ ونــص الئحــة الدعــوى العامــة‬\n                            ‫احلمد هلل والصالة والسالم على رسول اهلل وبعد‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة أحــد‬\n‫املســارحة أدعــي علــى ‪:‬ـ‪ 25.....‬عامــا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدني رقم ‪(.....‬عزب‪ /‬متعلم‪ /‬متسبب ) أودع بشعبة سجن جازان العام‬\n‫( قســم ســجن أحــد املســارحة ) مبوجــب أمــر متديــد التوقيــف واإلحالــة‬\n‫رقــم(‪ ).....‬وتاريــخ ‪1433/12/28‬ه ـ لكــون جرميتــه مــن اجلرائــم املوجبــة‬\n‫للتوقيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ‬\n               ‫ويعتبــر إيقافــه مــن تاريــخ القبــض عليــه يف ‪1433/12/9‬ه ـ ‪.‬‬\n‫أنــه يف متــام الســاعة الثالثــة والنصــف مــن صبــاح يــوم اخلميــس املوافــق‬\n‫‪1433/12/9‬ه ـ وأثنــاء قيــام إحــدى دوريــات شــرطة محافظــة احلــرث‬\n\n\n                                                                                        ‫‪476‬‬\n\f      ‫بواجبهــا امليدانــي يف املوقــع املســمى قــرى ‪.....‬وبالتحديــد اخلــط الترابــي‬\n      ‫املــؤدي إلــى قريــة ‪.....‬مت مشــاهدة ســيارة مــن نــوع ‪......‬موديــل ‪ 2010‬م‬\n      ‫حتمــل اللوحــة رقــم (‪ ).....‬تعــود ملكيتهــا ( للمدعــى عليــه ) وبقيادتــه‪،‬‬\n      ‫وعنــد اســتيقافها رفــض االمتثــال بالوقــوف والذ بالفــرار متجه ـ ًا إلــى‬\n      ‫قريــة ‪.....‬بســرعة عاليــة علــى اخلــط الترابــي فتــم إطــاق ثــاث طلقــات‬\n      ‫حتذيريــة إال أنــه واصــل ســيره رافض ـ ًا الوقــوف وأثنــاء املطــاردة كان‬\n      ‫الغبــار كثيفـ ًا ممــا أدى إلــى انحــراف ســيارة الدوريــة وانقالبهــا وإصابــة‬\n      ‫أفرادهــا بجــروح ســطحية(فرزت لــه أوراق لــدى شــرطة احلــرث بشــأن‬\n      ‫احلــادث)وكان بالقــرب مــن املوقــع دوريــة أخــرى وعنــد ســماع البــاغ‬\n      ‫قامــت الدوريــة علــى الفــور مبتابعــة الســيارة حتــى وصلــت إلــى قريــة‬\n      ‫‪.....‬وبعدهــا قــام بإيقــاف الســيارة بعــد أن تعطلــت والذ بالفــرار داخــل‬\n      ‫املنــازل ومت ضبــط الســيارة وبتفتيشــها عثــر بداخلهــا كميــة مــن نبــات‬\n      ‫أخضــر يشــتبه أن يكــون مــن نبــات القــات احملظــور بلــغ وزنهــا (‪. 974‬‬\n      ‫‪10‬كجم)عشــرة كيلــو وتســعمائة وأربعــة وســبعني جــرام وعــن طريــق‬\n      ‫أحــد املصــادر أفــاد بأنــه قــام بركــوب ســيارة مــن نــوع ‪....‬موديــل ‪1985‬م‬\n      ‫اللــون (‪ ).......‬وأنهــا متجهــة إلــى محافظــة ‪ ،....‬ومت القبــض علــى مــن‬\n      ‫كان يف الســيارة مــن قبــل دوريــات ‪ ....‬وهــم كلٌ مــن ( املدعــى عليــه‬\n      ‫) واملدعو‪...../‬و‪.....‬و‪(.....‬فــرزت لهــم أوراق مســتقلة لعرضهــا علــى جلنــة‬\n      ‫العفو)اثبــت التقريــر الكيميائــي الشــرعي رقم(‪).....‬لعام‪1433‬ه ـ‬\n      ‫الصــادر مــن املستشــفى إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور باســتجواب ( املدعــى عليــه ) بعــد مواجهتــه‬\n      ‫بالتهمــة املنســوبة إليــه أقــر بــأن كميــة القــات املضبوطــة والبالــغ‬\n      ‫وزنهــا(‪10 . 974‬كجــم) عشــرة كيلــو وتســعمائة وأربعــة وســبعني‬\n\n\n‫‪477‬‬\n\f‫جرام ـ ًا تعــود لــه حصــل عليهــا بالشــراء مــن شــخص ال يعرفــه مببلــغ‬\n‫(‪)200‬مائتــي ريــال وأن غرضــه منهــا إيصالهــا إلــى قريــة ‪.....‬لصالــح‬\n‫كل مــن املدعــو‪..... /‬و‪.....‬و‪.....‬مقابــل مبلــغ مالــي قــدره (‪ )200‬مائتــي‬\n‫ريــال وأقــر بقيامــه بالهــروب مــن رجــال األمــن وأنــه قــام باالتصــال علــى‬\n‫املدعو‪...../‬بعــد هروبــه مــن الســيارة واخبــره بأنــه مت ضبــط الســيارة‬\n‫وطلــب منــه ‪.....‬مقابلتــه عنــد احملطــة يف الشــارع العــام بقريــة ‪.....‬وقــام‬\n‫مبقابلتــه والركــوب معــه وقــد أســفر التحقيــق مــع ( املدعــى عليــه )‬\n‫عــن توجيــه االتهــام إليــه بنقــل مــا وزنــه (‪10 . 974‬كجــم) عشــرة كيلــو‬\n‫وتســعمائة وأربعــة وســبعني جرام ـ ًا مــن نبــات القــات احملظــور بقصــد‬\n‫الترويــج وهروبــه مــن رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة‬\n                         ‫بعــد هروبــه ؛ وتســتره علــى مصــدر مــا مت ضبطــه ‪:‬‬\n                                                  ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ /1‬مــا جــاء يف إقــراره املــدون ص(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــة رقــم‬\n                                                                            ‫(‪. )16‬‬\n          ‫‪ /2‬محضر القبض والتفتيش املنوه عنه املرفق لفة رقم (‪. )2-1‬‬\n        ‫‪ / 3‬التقرير الكيميائي الشرعي املنوه عنه املرفق لفه رقم (‪.)26‬‬\n                                  ‫‪ /4‬مراوغته وتناقض أقواله أثناء التحقيق ‪.‬‬\n‫وبالبحــث عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى ‪:‬ترويــج‬\n                               ‫القــات‪ ،‬والثانيــة والثالثــة ‪ :‬ســرقة ســيارات ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه ( املدعــى عليــه ) فعــل محــرم شــرع ًا ومعاقــب‬\n‫عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا‬\n                                       ‫حلــق بــه مــن تعديــات لــذا أطلــب اآلتــي ‪:‬‬\n‫‪/1‬إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املادة(الثالثة)‬\n\n\n                                                                                         ‫‪478‬‬\n\f      ‫مــن القــرار الــوزاري املشــار إليــه إنفــاذ ًا لألمــر الســامي الكــرمي‬\n      ‫رقــم(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وتشــديد العقوبــة عليــه لقــاء تعدد‬\n                                                                              ‫ســوابقه‪.‬‬\n                ‫‪ /2‬احلكم بتعزيره شرع ًا لقاء تستره على مصدر ما مت ضبطه ‪.‬‬\n      ‫‪/3‬احلكــم بتعزيــره شــرع ًا لقــاء تســببه يف انقــاب ســيارة الدوريــة بعــد‬\n                                                                                ‫هروبــه ‪.‬‬\n      ‫‪ /4‬احلكــم مبصــادرة الســيارة نــوع( ‪) .....‬حتمــل اللوحــة رقــم(‪).....‬‬\n      ‫رقــم الهيــكل (‪).....‬العائــدة ملكيتهــا للمتهــم واملســتخدمة يف اجلرميــة‬\n      ‫وبســؤال املدعــى عليــه اجلــواب أجــاب معترفـ ـ ًـا بالقبــض عليــه بتاريــخ‬\n      ‫‪1433/12/9‬ه ـ مــن قبــل رجــال األمــن بعــد هروبــه مــن قبضتهم وتســببه‬\n      ‫يف انقــاب ســيارة الدوريــة أثنــاء هروبــه وبحوزتــه (‪10 . 974‬كجــم)‬\n      ‫عشــرة كيلــو وتســعمائة وأربعــة وســبعني جرام ـ ًا مــن نبــات القــات‬\n      ‫احملظــور ذكــر أن غرضــه مــن تلــك الكميــة هــو ن ــقلها مــن قريــة ‪.....‬‬\n      ‫إلــى قريــة ‪.....‬لصالــح كال مــن ‪..... /‬و ‪..... /‬و ‪..... /‬مقابــل أجــرة ماليــة‬\n      ‫قدرها(‪)200‬مائتــي ريــال ســعودي ؛ وصــادق علــى الســوابق املوضحــة‬\n      ‫يف بطاقــة بصمــات العشــرية ‪.‬وبالرج ــوع إلــى أوراق املعاملــة وجــدت أن‬\n      ‫الـت ــقرير الكيميائــي الـش ــرعي ومحضــر الــوزن يتطابقــان مع ما ورد يف‬\n      ‫الئحــة الدعــوى وأن للم ــدعى عليــه ثــاث ســوابق األولــى ‪ :‬ترويــج القــات‬\n                                              ‫؛ والثانيــة والثالثــة ‪ :‬ســرقة ســيارات ‪.‬‬\n      ‫ـاء علــى مــا ت ــقدم يف الدع ــوى والـج ــواب ومــا ورد يف الـت ــقرير‬    ‫وبـنـ ـ ً‬\n      ‫ـرعا‬\n         ‫ـدي ش ـ ً‬‫الك ــيميائي وم ــحضر الــوزن وكــرت الســوابق فقــد ثبــت لـ ّ‬\n      ‫إدان ــة املدعــى عليــه ‪..... /‬بالقبــض عليــه بتاريــخ ‪1433/12/9‬ه ـ مــن‬\n      ‫قبــل رجــال األمــن بعــد هروبــه مــن قبضتهــم وتســببه يف انقــاب ســيارة‬\n\n\n‫‪479‬‬\n\f‫الدوريــة أثنــاء هروبــه وبحوزتــه كميــة مــن نبــات القــات احملظــور تــزن‬\n‫(‪10 . 974‬كجــم) عشــرة كيلــو وتســعمائة وأربعــة وســبعني جرام ـ ًا‬\n‫لغــرض النقــل لصالــح الغيــر مقابــل األجــر املــادي ؛ وهــو يســتحق التعزيــر‬\n‫علــى مــا أديــن بــه إنفــا ًذا لألمــر الســامي الكــرمي رقــم (‪)59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وفــق املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫وتاريــخ ‪1374/2/1‬ه ـ واملعدلــة بقــرار وزيــر الداخليــة رقــم (‪)2057‬‬\n‫وتاريــخ ‪1404 /5/26‬ه ـ والتشــديد يف حقــه نظـ ًـرا لهروبــه مــن قبضــة‬\n‫رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة أثنــاء هروبــه ؛ إضافــة‬\n‫إلــى وجــود ســوا بــق لــه ؛ لــذا فقــد حكمــت بسج ــنه ملــدة خ ــمس ســنوات‬\n‫ـارا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة يف ‪1433/12/9‬ه ـ‬      ‫اعتبـ ً‬\n‫وجلــده ب ــسبعمائة جلــدة عل ًنــا مفرقــة علــى دفعــات بواقــع خ ــمسني جلــدة‬\n‫لــكل دفعــة بــن الدفعــة والتــي تليهــا خ ــمسة أيــام ؛ وغرامة ماليــة قدرها‬\n‫عشــرة آالف ريــال ســعودي تــودع لصالــح بيــت مــال املســلمني ؛ ومصــادرة‬\n‫ثانيــا ‪/‬‬\n       ‫وإتــاف كميــة نبــات القــات املضبوطــة بواســطة اجلهــة املختصــة ً‬\n‫قــررت مصــادرة الســيارة نــوع ( ‪ ) ....‬صنــع ســنة ‪ 2010‬م حتمــل اللوحــة‬\n‫رقــم (‪ ).....‬ورقــم الهيــكل (‪ ).....‬العائــدة ملكيتهــا للمدعــى عليــه‬\n‫واملســتخدمة يف اجلرميــة وذلــك ببيعهــا وإيــداع ثمنهــا يف حســاب اإلدارة‬\n‫العامــة ملكافحــة املخــدرات وفق ـ ًـا لقــرار مجلــس الــوزراء املوقــر رقــم‬\n‫(‪)47‬تاريــخ ‪ 1421/2/18‬ه ـ وذلــك يف ضــوء الفقــرة (‪ )1‬مــن املــادة(‪)53‬‬\n‫مــن ذات النظــام هــذا مــا ان ــتهت إليــه ال ــقضية وبــه حكمــت يف احلــق‬\n‫العــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه عــدم قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام اعتراضــه عليــه وطلبــا اســتئنافه دون تقــدمي الئحــة‬\n‫اعتراضيــة فأجبتهمــا لطلبهمــا ‪ .‬وصلــى اهلل علــى ســيدنا مح ــمد وآلــه‬\n\n\n                                                                                     ‫‪480‬‬\n\f                                                                        ‫وصحبــه وســلم‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342146007‬وتاريــخ ‪1434/10/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34325520‬وتاريــخ‬\n      ‫‪1434/9/24‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪..... /‬يف قضيــة‬\n      ‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                                  ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪481‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":474,"source_page_end":481,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b256aa3adc591d1b934642df477402674d1edb74ff77e19f2976eac3a44fcbb9","normalized_text_hash":"2d2724033f868c4c3c5f10b0e8ee4265ad65cc47043fb2bd2a2b9db83d2303eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p474-34325520"},{"id":"25b9ef86-8bd1-5238-bd9e-8c564b5b4ce4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -توسط يف بيع احلبوب احملظورة الكبتاجون -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال وإلغاء الشريحة املستخدمة يف اجلرمية.","document_number":"34205167","case_number":"34440251","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -توسط يف بيع احلبوب احملظورة الكبتاجون -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال وإلغاء الشريحة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪34205167 :‬تاريخه‪1434/5/4 :‬هـ‬\n                   ‫رقم الدعوى‪34440251:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34236440‬تاريخه‪1434/6/11 :‬هـ‬\n\n\n‫مخدرات ‪ -‬ترويج احلبوب احملظورة ‪ -‬توسط يف بيع احلبوب احملظورة‬\n‫الكبتاجــون ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬عــدم‬\n‫وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن‬\n ‫الســفر ومبصــادرة اجلــوال وإلغــاء الشــريحة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )56‬واملــادة (‪)60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات احلبــوب‬\n‫احملظــورة «الكبتاجــون» ‪ -‬مت القبــض علــى املدعــى عليــه وهــو يســلم‬\n‫املصــدر الســري حبــوب الكبتاجــون ‪ ،‬أقــر املدعــى عليــه بالترويــج‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫الكبتاجــون املخــدر‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه بتعزيــره شــرع ًا ومنعــه مــن الســفر خــارج البــاد بعــد انقضــاء‬\n‫محكوميتــه ومصــادرة جوالــه املســتخدم يف اجلرميــة‪ ،‬ومصادرة الســيارة‬\n‫وإلغــاء الشــريحة وعــدم صرفهــا مــرة أخــرى إلســاءة اســتخدامها ‪.‬‬\n\n                                                                                 ‫‪482‬‬\n\f      ‫حكمــت احملكمــة بثبــوت إدانــة املدعــى عليــه بقيامــه بالتوســط يف‬\n      ‫بيــع احلبــوب احملظــورة‪ ،‬قــررت احملكمــة احلكــم علــى املدعــى عليــه‬\n      ‫بتعزيــره للتهــم والقرائــن بالســجن ملــدة اثنــي عشــر شــهرا اعتبــارا مــن‬\n      ‫تاريــخ دخولــه الســجن‪ ،‬وجلــده مائتــي جلــدة علنــا علــى أربعــة دفعــات‬\n      ‫كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة عشــر يومــا‪،‬‬\n      ‫وتغرميــه مبلغـ ًا وقــدره ألــف ري ــال‪ ،‬مصــادرة اجلــوال املســتخدم يف ترويــج‬\n      ‫احلبــوب احملظــورة وإلغــاء الشــريحة املســجلة باســمه وعــدم صرفهــا لــه‬\n      ‫مــرة أخــرى‪ ،‬واملنــع مــن الســفر خلــارج البــاد بعــد تنفيــذ محكوميتــه‬\n      ‫ملــدة ســنتني‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق‬\n                                        ‫احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪1434/01/24..........‬ه ـ املقيــدة باحملكمة برقم‬\n      ‫‪..........‬وتاريخ ‪1434/01/24‬هـ ففي يوم األحد املوافق‪1434/04/21‬هـ‬\n      ‫افتتحــت اجللســة الســاعة ‪09 : 00‬وفيهــا حضــر املدعــي العــام ‪.......... /‬‬\n      ‫واملكلف بحضور اجللسات باخلطاب رقــم ( ‪ )..........‬يف ‪1433/3/22‬هـ‬\n      ‫وادعــى علــى احلاضــر معــه باملجلــس الشــرعي الســجني ‪.......... /‬ســعودي‬\n      ‫بالســجل املدني رقم (‪ )..........‬قائال يف دعواه ‪ :‬بتاريخ ‪1433/11/11‬هـ‬\n      ‫وردت معلومــات ملكافحــة املخــدرات مــن أحــد املصــادر بــان املدعــى‬\n      ‫ـاء عليهــا مت تكليــف احــد األفــراد بتمثيــل‬\n                                                   ‫عليــه مــن مروجــي احلبــوب و بنـ ً‬\n      ‫دور املشــتري وقــد ورد إتصــال مــن جــوال املصــدر علــى الفــرد ممثــل‬\n\n‫‪483‬‬\n\f‫دور الشــراء يفيــد بــأن املــروج لديــه خمــس وعشــرون حبــة مــن حبــوب‬\n‫الكبتاجــون ويرغــب يف بيعهــا ومتواجــد مبحافظــة صبيــا وقــام املصــدر‬\n‫بتزويــد الفــرد ممثــل دور الشــراء جــوال املــروج رقــم‪........../‬ويف احلاديــة‬\n‫عشــرة والنصــف مت االتصــال علــى املــروج مــن جــوال الفــرد وكان‬\n‫علــى مســمع مــن الفرقــة وطلــب الفــرد مــن املــروج كميــة مــن حبــوب‬\n‫الكبتاجــون فــرد عليــه أنــه توجــد خمــس وعشــرون حبــة فقــط وإذا‬\n‫يرغــب يف شــرائها عليــه احلضــور حملافظــة (‪ )........‬وأن قيمــة احلبــوب‬\n‫ســبعمائة وخمســون ريــال فوافــق الفــرد ممثــل دور الشــراء علــى ذلــك‬\n‫وطلــب املــروج مــن الفــرد عنــد وصولــه محافظــة (‪ )........‬عنــد البنــك ‪...‬‬\n‫االتصــال عليــه وانتهــت املكاملــة فتــم االنتقــال بالفرقــة إلــى محافظــة‬\n‫صبيــا ومت إعــداد خطــة للقبــض علــى املــروج ومت توزيــع الفرقــة حــول‬\n‫املوقــع املتفــق عليــه ومت تكليــف فــرد آخــر مــع الفــرد ممثــل دور الشــراء‬\n‫ومت تزويــده باملبلــغ احلكومــي املتفــق عليــه يف شــراء كمية احلبوب وعند‬\n‫وقوفهــم أمــام البنــك ‪ ...‬وكانــوا حتــت أنظــار الفرقــة حضــرت ســيارة‬\n‫مــن نــوع ‪ ....‬موديــل ‪ 2011‬رقــم اللوحــة (‪ )..........‬ونــزل منهــا شــخص وقــام‬\n‫بالركــوب مــع الفرديــن وطلــب الفــرد ممثــل دور الشــراء منــه الكميــة‬\n‫فــرد عليــه بــأن كميــة احلبــوب املتفــق عليهــا عنــد شــخص مينــي آخــر‬\n‫وأنــه ال يقــوم ببيعهــا بــل يقــوم بتوجيههــم لــه وهــو مــن ســيقوم بتســليمهم‬\n‫الكميــة فطلــب الفــرد منــه اإلتصــال علــى الشــخص اليمنــي التــي‬\n‫بحوزتــه كميــة احلبــوب وأبلغــه بــأن الفــرد معــه ومتجهــن إليــه الســتالم‬\n‫كميــة احلبــوب واســتالم املبلــغ ‪ ،‬عندهــا حتــرك الفرديــن ومعهمــا املــروج‬\n‫الــذي اتضــح أنــه وســيط إلــى صاحــب الكميــة الــذي يســكن حــارة‬\n‫‪..........‬بصبيــا ومتــت متابعتهــم مــن الفرقــة وعنــد وصولهــم بالقــرب مــن‬\n\n\n                                                                                      ‫‪484‬‬\n\f      ‫منــزل صاحــب الكميــة وطلــب منــه اخلــروج إلــى الشــارع وأعطــاه احلبــوب‬\n      ‫وأخــذ املبلــغ وعنــد توقــف ســيارة الفرديــن والوســيط خــرج شــخص مــن‬\n      ‫احــد املنــازل وبيــده كيــس وعنــد اقترابــه مــن الســيارة ونــزول الفــرد‬\n      ‫ممثــل دور املشــتري قــام برمــي الكيــس والذ بالفــرار داخــل أحــد املنــازل‬\n      ‫ا ولكــون املنــزل يوجــد بــه عائلــة ولظــام‬   ‫حوالــي الســاعة الواحــدة لي ـ ً‬\n      ‫الليــل داخــل احلــي مت التحفــظ علــى الكيــس الــذي قــام برميــه وبداخلــه‬\n      ‫(‪ )19‬تســعة عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪ 1433‬ه ـ الصــادر مــن‬\n      ‫مركــز الســموم والكيميــاء الشــرعية مبكــة املكرمــة ومت القبــض‬\n      ‫علــى املدعــى عليــه واتضــح أن اســم صاحــب الكميــة يدعــى‪............. /‬‬\n      ‫اجلنســية ومــن أكبــر املروجــن للحبــوب املخــدرة (‪ )........‬والزال البحــث‬\n      ‫جــاري عنــه القبــض عليــه ‪ ،‬وباســتجواب املدعــى عليــه والتحقيــق معــه‬\n      ‫أســفر التحقيــق عــن توجيــه االتهــام إليــه بالتوســط يف بيــع عــدد (‪)19‬‬\n      ‫تســع عشــرة حبــة يشــتبه أن تكــون مــن حبــوب الكبتاجــون احملظــورة‬\n      ‫عــن طريــق االتفــاق واملســاعدة وذلــك لألدلــة والقرائــن املرفقــة بــأوراق‬\n      ‫القضيــة وحيــث إمنــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا ومعاقــب‬\n      ‫عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب‬\n      ‫‪ -1‬إثبــات مــا أســند إليــه واحلكــم بتعزيــره شــرع ًا يف ضــوء املــادة (‪)38‬‬\n      ‫مــن ذات النظــام و التشــديد عليــه اســتنادا لتعميــم صاحــب الســمو‬\n      ‫امللكــى وزيرالداخليــه رقــم ‪ 8346‬يف ‪1427/2/8‬ه ـ خلطورتة احلبوب يف‬\n      ‫تدميــر مراكــز نهايــة االعصــاب املركزيــه باملــخ ‪-2‬احلكــم مبنعــه مــن‬\n      ‫الســفر خــارج البــاد بعــد انقضــاء محكومتيــه اســتنادا للفقــرة األولــى‬\n\n\n‫‪485‬‬\n\f‫مــن املــادة (‪ )56‬مــن ذات النظــام‪ -3‬مصــادرة الســيارة نــوع ‪ .....‬موديــل (‬\n‫‪ ) 2011‬ـرقم اللوحة (‪ )..........‬استنادا للفقرة ‪ 1‬من املادة ( ‪ ) 53‬من ذات‬\n‫النظــام وإيــداع قيمتهــا لــدى حســاب اإلدارة العامــة ملكافحــة املخــدرات‬\n‫اســتناد ًا للقــرار الــوزاري رقــم ‪ 47‬وتاريــخ ‪1421/2/18‬ه ـ ومصــادرة‬\n‫اجلــوال املســتخدم يف اجلرميــة نــوع ‪........‬الرقــم املصنعــي (‪ )..........‬اســتناد ًا‬\n‫للفقــرة ‪ 1‬مــن املــادة ‪ 53‬مــن ذات النظــام وإيــداع قيمتهــا لــدى حســاب‬\n‫اإلدارة العامــة ملكافحــة املخــدرات اســتناد ًا للقــرار الــوزاري رقــم ‪47‬‬\n‫وتاريــخ ‪1421/2/18‬ه ـ ‪ .‬وإلغــاء الشــريحة اخلاصــة باجلوال رقــم (‪)..........‬‬\n‫وعدم صرفها مرة أخرى ملن أســاء اســتخدامها اســتناد ًا لتعميم صاحب‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬وتاريــخ ‪1428/2/10_9‬ه ـ ‪.‬‬\n‫وبســؤال املدعــى عليــه أجــاب قائــا ‪ :‬أعتــرف بتوســطي يف بيــع مــا‬\n‫عــدده (‪ )19‬ـ تســع عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة عــن‬\n‫طريــق اإلتفــاق واملســاعدة يف ذلــك بهــذا أجــاب ‪ ،‬وبســؤاله عــن الســيارة‬\n‫قــال الســيارة عائــدة للشــركة للبيــع بالتقســيط ومؤجــرة علــي بعقــد‬\n‫إيجــار ينتهــي بالتمليــك ‪ .‬وباإلطــاع علــى أوراق القضيــة وجــد ضمنهــا‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪ 1433‬ه ــو املتضمــن‬\n‫ثبــوت إيجابيــة العينــة املرســلة مــن الكميــة حلبــوب اإلمفيتامــن املنبهــة‬\n‫احملظــورة ‪ ،‬كمــا وجــد كــرت بصمــات املدعــى عليــه واملتضمــن عــدم‬\n‫وجــود ســوابق عليــه ‪ ،‬وعليــه ف ــبناء علــى ســماع الدعــوى واإلجابــة فقــد‬\n‫ثبــت لــدي شــرعا إدانــة املدعــى عليــه ‪ 0000 /‬بقيامــه بالتوســط يف بيــع‬\n‫( ‪19‬حبــة ) ـ تســع عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة عــن‬\n‫طريــق اإلتفــاق واملســاعدة ويســتحق التعزيــر علــى ذلــك وفــق املــادة ( ‪38‬‬\n‫) مــن نظــام مكافحــة املخــدرات إال أنــه نظــرا لعــدم وجــود ســوابق عليــه‬\n\n\n                                                                                            ‫‪486‬‬\n\f      ‫ولكونــه يعــول أســرة وإلظهــاره ندمــه وتوبتــه واســتنادا للمــادة رقــم (‪) 60‬‬\n      ‫مــن ذات النظــام لــذا فقــد حكمــت بتعزيــره بالســجن ملــدة إثنــا عشــر‬\n      ‫شــهرا إعتبــارا مــن تاريــخ دخولــه الســجن وجلــده مائتــي جلــدة علنــا علــى‬\n      ‫أربــع دفعــات كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة‬\n      ‫عشــر يومــا وتغرميــه مبلــغ وقــدره ألــف ريــال ومصــادرة اجلــوال املســتخدم‬\n      ‫يف ترويــج احلبــوب احملظــورة وإلغــاء الشــريحة املســجلة باســمه وعــدم‬\n      ‫صرفهــا للمدعــى عليــه مــرة أخــرى وصرفــت النظــر عــن طلــب املدعــي‬\n      ‫العــام مصــادرة الســيارة لكونهــا ليســت ملــكا للمدعــى عليــه ومنعــه‬\n      ‫مــن الســفر خــارج البــاد بعــد تنفيــذ محكوميتــه ملــدة ســنتني بذلــك‬\n      ‫حكمــت وأفهمــت املدعــى عليــه باحلكــم فقــرر القناعــة وقــرر املدعــي‬\n      ‫العــام معارضتــه وطلــب رفــع احلكــم حملكمــة اإلســتئناف بالئحــة‬\n      ‫إعتراضيــة وبــه حــرر يف ‪1434/4/21‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم‪،،،‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/5/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪.......... /‬برقــم ‪..........‬وتاريــخ ‪1434/5/4‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ (.......... /‬ســعودي اجلنســية ) يف قضيــة (‬\n      ‫مخــدرات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n                              ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n‫‪487‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":482,"source_page_end":487,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"46cac2a1762f92462a2ebccc43223c201f5ba5df1180019840a84e0c130bf3a5","normalized_text_hash":"1e3a23036a8b0fbd8d1371daf749fb1e9da7eec21a760335b08f3707afbcfc34","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p482-34205167"},{"id":"6c36372e-78a6-5d10-9622-cfc4a51a68b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -الوساطة يف بيع بقصد الترويج -قات -التعزير بالسجن واجللد والغرامة واإلبعاد عن الباد بعد إنفاذ العقوبة ورد املبلغ","document_number":"34340849","case_number":"34446231","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/6","year":"1434","subject":"مخدرات -الوساطة يف بيع بقصد الترويج -قات -التعزير بالسجن واجللد والغرامة واإلبعاد عن الباد بعد إنفاذ العقوبة ورد املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34340849 :‬تاريخه ‪1434/10/6 :‬هـ‬\n                     ‫رقم الدعوى‪34446231:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34364069‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n ‫مخدرات ‪ -‬الوســاطة يف بيع بقصد الترويج ‪ -‬قات ‪ -‬التعزير بالســجن‬\n ‫واجللــد والغرامــة واإلبعــاد عــن البــاد بعــد إنفــاذ العقوبــة ورد املبلــغ‬\n                                                                         ‫املرقــم ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قرار مجلس الوزراء رقم‪ 11‬يف ‪1374/2/1‬هـ‬\n                ‫‪ -2‬األمر السامي الكرمي رقم ‪ 59633‬يف ‪1432/12/9‬هـ‪.‬‬\n      ‫‪ -3‬املادة الثالثة من قرار وزير الداخلية رقم ‪2057‬يف ‪1404/5/26‬هـ‬\n                      ‫‪ -4‬القرار الوزاري رقم ‪ 3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بالوســاطة يف بيــع قــات بقصــد‬\n ‫الترويــج و طلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره وتشــديد العقوبة‬\n ‫لتعــدد ســوابقه وإبعــاده عــن البــاد بعــد تنفيــذ احلكــم وإلزامه بــرد املبلغ‬\n ‫احلكومــي املرقــم وقــدره مائــة ريــال ‪،‬حيــث مت االشــتباه باملدعــى عليــه‬\n ‫أثنــاء وقوفــه عنــد أحــد املنــازل يقــوم بترويــج القــات وعنــد ســؤاله عــن‬\n ‫مــكان بيــع القــات مــن قبــل أحــد أفــراد فرقــة املكافحــة قــام بإدخالــه‬\n ‫للمنــزل والتوســط لشــراء القــات وعنــد خروجــه مــن املنــزل برفقــة الفــرد‬\n ‫مت القبــض عليــه وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n\n                                                                                      ‫‪488‬‬\n\f      ‫املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه الدعــوى ‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بســجنه مــدة ســنتني تعزيــر ًا وجلــده‬\n      ‫خمســمائة جلــدة علنـ ًا مفرقــة كل دفعــة خمســون جلــدة وغرامــة ماليــة‬\n      ‫قدرهــا خمســة آالف ريــال تــودع يف بيــت مــال املســلمني وإبعــاده عــن‬\n      ‫البــاد بعــد تنفيــذ العقوبــة املقــررة بحقــه ورد املبلــغ احلكومــي املرقــم‬\n      ‫وقــدره مائــة ريــال وقنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫مكتفيـ ًا بالئحــة الدعــوى ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34446231‬وتاريــخ ‪1434/10/12‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 342294560‬وتاريــخ ‪1434/10/12‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق ‪1434/10/19‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬يف ‪1431/8/13‬ه ـ‬\n      ‫واملدعــى عليــه ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪).....‬‬\n      ‫وقــدم املدعــي العــام دعــوى محــررة تتضمن ‪ :‬أنه بتاريــخ ‪1434/8/19‬هـ‬\n      ‫وأثنــاء قيــام إحــدى فــرق مكافحــة املخــدرات بواجبهــا يف قريــة ‪.....‬مت‬\n      ‫االشــتباه يف املدعــى عليــه عندمــا كان واقف ـ ًا بجانــب منــزل ‪(.....‬متــت‬\n      ‫املخاطبــة بشــأنه) يقــوم بترويــج نبــات القــات احملظــور وعنــد نــزول أحــد‬\n      ‫أفــراد الفرقــة القابضــة وســؤاله عــن مــكان القــات قــام بإدخــال الفــرد‬\n      ‫للمنــزل وإيصالــه إلــى مــكان ترويــج نبــات القــات والتوســط لشــراء‬\n      ‫كميــه مــن نبــات القــات مببلــغ (‪ )100‬مائــه ريــال وأثنــاء خروجــه مــن‬\n\n‫‪489‬‬\n\f‫املنــزل برفقــة الفــرد مت القبــض عليــه ولــم يتــم القبــض علــى املروجــن‬\n‫لكــون املنــزل بــه عوائــل وبــوزن الكميــه املباعــة مــن نبــات القــات‬\n‫احملظــور بلــغ وزنها(‪200‬جــم ـ مائتــن جرامـاً) أثبــت التقريــر الكيميائي‬\n‫الشــرعي رقم(‪.....‬لعــام ‪1434‬هــ) إيجابيــة العينــة املرســلة مــن الكميــة‬\n‫املضبوطــة لنبــات القــات احملظــور وباســتجواب املدعــى عليــه املذكــور‬\n‫أقــر بالتوســط يف بيــع مــا وزنــه(‪ 200‬جــم ـ مائتــان جراماً)مــن نبــات‬\n‫القــات احملظــور لغــرض احلصــول علــى املــال لصالــح صاحــب املنــزل‪...../‬‬\n‫(متــت املخاطبــة بشــأنه)كما أقــر بــأن الذيــن يبيعــون القــات بداخــل‬\n‫املنــزل شــخصان همــا ‪.....‬و‪(.....‬متــت املخاطبــة بشــأنهما) وقــد أســفر‬\n‫التحقيــق مــع املدعــى عليــه عــن توجيــه االتهــام إليــه بالتوســط يف بيــع‬\n‫مــا وزنــه (‪200‬جــم ـ مائتــن جراماً)مــن نبــات القــات احملظــور بقصــد‬\n‫االجتــار املجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪1 :‬ـ مــا جــاء يف إقــراره املرفــق ‪ 2‬ـ مــا جــاء يف محضــر القبــض والتفتيــش‬\n‫املرفــق ‪3‬ـ التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق وبالبحــث‬\n‫عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى مخالفــة نظــام أمــن‬\n‫احلــدود مقترنــة بتهريــب القــات والثانيــة حيــازة القــات والثالثــة مخالفــة‬\n‫نظــام أمــن احلــدود وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فإنــي أطلــب ‪ -1 :‬إثبــات مــا‬\n‫أســند إليــه واحلكــم بتعزيــره يف ضــوء املادة(الثالثة)مــن القــرار الــوزاري‬\n‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وتشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه ‪ -2‬احلكــم‬\n\n\n                                                                                     ‫‪490‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":488,"source_page_end":490,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4cb980323a933ff15ebdc39eb019a51b876b528a816cf82874eac39a0fa7a242","normalized_text_hash":"00d47f75ed87aa5061ce9d4551579476670672523bbbd3790d918236ab2491c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p488-34340849"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c2eeb27f-c91a-58a2-86db-b2a5b84c2827","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -تستر على مصدر الكمية -مصادرة اجلوال املستخدم يف اجلرمية -صرف النظر عن مصادرة املبلغ- التعزير بالسجن واجللد والغرامة.","document_number":"34279956","case_number":"34328810","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/ 7 /25","year":"1434","subject":"مخدرات -ترويج -قات -تستر على مصدر الكمية -مصادرة اجلوال املستخدم يف اجلرمية -صرف النظر عن مصادرة املبلغ- التعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34279956 :‬تاريخه‪1434/ 7 /25 :‬هـ‬\n                            ‫رقم الدعوى‪34328810:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34342437‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬تســتر علــى مصــدر الكميــة ‪ -‬مصــادرة‬\n       ‫اجلــوال املســتخدم يف اجلرميــة ‪ -‬صــرف النظــر عــن مصــادرة املبلــغ‪-‬‬\n                                        ‫التعزيــر بالســجن واجللــد والغرامــة‪.‬‬\n\n\n\n\n                                      ‫قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليهــا ببيــع قــات بقصــد الترويــج‬\n       ‫واالجتــار وتســترها علــى املصــدر وطلــب إثبــات إدانتهــا مبــا أســند إليهــا‬\n       ‫ومعاقبتهــا بعقوبــة تعزيريــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n       ‫وإلغــاء الشــريحة وتعزيرهــا لقــاء التســتر ‪،‬مت القبــض علــى املدعــى‬\n       ‫عليهــا وتفتيشــها ومت العثــور علــى املبلــغ املرقــم بحوزتهــا وبتفتيــش املنــزل‬\n       ‫مت العثــور علــى قــات بالثالجــة وأثبــت التقريــر الكيميائــي الشــرعي‬\n       ‫إيجابيــة العينــة لنبــات القــات احملظــور وصادقــت املدعــى عليهــا علــى‬\n       ‫الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيرهــا بالســجن‬\n       ‫مــدة ســنتني وجلدهــا مائــة وخمســن جلــدة مفرقــة علــى دفعــات مقــدار‬\n       ‫كل دفعــة خمســون جلــدة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n       ‫وصــرف النظــر عــن مصــادرة املبلــغ املضبــوط وقنعــت املدعــى عليهــا‬\n\n‫‪449‬‬\n\f‫‪،‬وصــدق احلكــم مــن‬\n                 ‫واعتــرض املدعــي العــام بــدون الئحــة اعتراضيــة ُ‬\n                                              ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34328810‬وتاريــخ ‪ 1434/07/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341715750‬وتاريــخ ‪ 1434/07/16‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/07/25‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا قــدم املدعــي العــام ‪..... /‬الئحــة دعــوى عامــة ضــد ‪ ،..... /‬البالغــة‬\n‫مــن العمــر (‪ )54‬عام ـ ًا ‪ ،‬صوماليــة اجلنســية مبوجــب رخصــة اقامــة‬\n‫رقــم (‪ ،).....‬متزوجــة ‪ ،‬متعلمــة ‪ ،‬عاملــه منزليــة ‪ ،‬تقيــم يف الريــاض‬\n‫‪ ،‬أودعــت بســجن النســاء مبوجــب مذكــرة إحالــة ومتديــد توقيــف رقــم‬\n‫(‪ ).....‬وتاريخ ‪1434/5/ 18‬هـ اســتنادا للقرار الوزاري رقم (‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة واحلاضــرة برفقــه الســجانة ‪..... /‬والعســكري ‪......‬حيــث إنــه‬\n‫بتاريــخ ‪1434/5/7‬ه ـ قبــض علــى املذكــورة مــن قبــل إحــدى فــرق ادارة‬\n‫العمليــات مبكافحــة املخــدرات مبنطقــة الريــاض بعــد ورود معلومــات‬\n‫مــن أحــد املصــادر الســرية عــن وجودها يف حــي ‪ .....‬وقيامها بترويج نبات‬\n‫القــات احملظــور وتتواجــد علــى الهاتــف رقــم (‪ ).....‬فتــم االيعــاز للمصــدر‬\n‫باالتصــال بهــا وطلــب حزمــة مــن القــات مببلــغ (‪ )150‬مائــة وخمســن‬\n‫ريــال فوافقــت وطلبــت مــن املصــدر احلضــور إلــى منزلهــا وكان ذلــك‬\n‫علــى مســمع مــن أحــد أفــراد الفرقــة القابضــة عليــه مت انتقــال الفرقــة‬\n\n                                                                                      ‫‪450‬‬\n\f      ‫إلــى املوقــع احملــدد وعنــد الوصــول طلــب مــن املصــدر الترجــل مــن‬\n      ‫ســيارة الفرقــة بعــد أن مت تفتيشــه وتزويــده باملبلــغ املرقــم ثــم توجــه إلــى‬\n      ‫شــقتها وقابلهــا أمــام شــقتها وســلمها املبلــغ احلكومــي املرقــم وســلمت‬\n      ‫املذكــورة للمصــدر حزمــة يشــتبه أن تكــون مــن نبــات القــات احملظــور‬\n      ‫بلــغ وزنهــا (‪ )158‬مائــة وثمــان وخمســن جرامـ ًا وكان ذلــك علــى مــرأى‬\n      ‫مــن رقيــب الفرقــة فتــم ضبطهــا مــن قبــل املفتشــة النســائية و بتفتيشــها‬\n      ‫شــخصي ًا مــن قبــل املفتشــة النســائية لــم يعثــر معهــا علــى ممنوعــات و‬\n      ‫عثــر علــى جــوال نــوع يحمــل الرقــم املصنعــي (‪ ).....‬وهــو اجلــوال الــذي متــت‬\n      ‫عليــه عمليــة التفــاوض(مت طلــب حجــزه متهيــد ًا لطلــب مصادرتــه مبوجــب‬\n      ‫اخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1434/ 5/ 14‬هــ) وعثــر معهــا علــى املبلــغ‬\n      ‫املرقــم (جــرى مطابقتــه) كمــا عثــر علــى مبلــغ مالــي قــدرة(‪ )1850‬ألــف‬\n      ‫وثمــان مائــة وخمســن ريــال (مت طلــب حجــزه متهيــد ًا لطلــب مصادرتــه‬\n      ‫مبوجــب اخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1434/5 / 14‬هــ) وبعــد (اخــذ‬\n      ‫االذن الــازم) مت دخــول شــقتها و بتفتيشــها عثــر بالثالجــة علــى (‪)6‬‬\n      ‫ســت حــزم يشــتبه أن تكــون مــن نبــات القــات احملظــور بلــغ وزنهــا جميعــا‬\n                                      ‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرام ـاً‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم ( ‪ ).....‬لعــام‬\n      ‫‪1434‬ه ـ ايجابيــة مســتخلص عينــة األوراق النباتيــة املبيعــة واملضبوطــة‬\n      ‫لنبــات القــات وهــو مــن املــواد املدرجــة يف اجلــدول رقــم (‪ )4‬امللحــق بنظــام‬\n                                             ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالهــا األوليــة واســتجوابها اعترفــت بترويــج حزمــة مــن نبــات‬\n      ‫القــات وحيــازة مــا ضبــط منــه بقصــد ترويجــه وترويجهــا لنبــات القــات‬\n\n\n‫‪451‬‬\n\f‫يف الســابق واســتخدامها جلوالهــا يف عمليــة الترويــج ‪ .‬وقــد أســفرت‬\n‫إجــراءات التحقيــق عــن توجيــه االتهــام للمــرأة ‪...../‬ببيــع حزمــه مــن‬\n‫نبــات القــات احملظــور تــزن (‪ )158‬مائــة وثمــان وخمســن جرامـ ًا بقصــد‬\n‫االجتــار والترويــج وحيــازة (‪ )6‬ســت حــزم مــن نفــس النــوع تــزن جميعهــا‬\n‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرامـ ًا بقصــد االجتــار والترويــج‬\n‫وترويــج نبــات القــات يف الســابق املعاقــب عليــه وفــق قــرار مجلــس الوزراء‬\n‫رقــم (‪ )11‬لعــام ‪1373‬ه ـ وتســترها علــى مصــدر مــا باعتــه ومــا ضبــط‬\n                ‫املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ - 1‬مــا تضمنــه اعترافهــا حتقيقــا املنــوه عنــه املــدون علــى الصفحــات‬\n                  ‫رقــم (‪ )2-1‬و مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ‪.)22‬‬\n‫‪ -2‬مــا تضمنــه اعترافهــا يف محضــر ســماع اقوالهــا املنــوه عنــه املرفــق‬\n                                                               ‫لفــه رقــم (‪.)17-16‬‬\n‫‪ -3‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون علــى الصفحــة‬\n‫رقــم(‪ )11‬ومحضــر مطابقــة املبلــغ املرقــم علــى الصفحــة رقــم(‪ )4‬مــن‬\n                 ‫ملــف ضبــط اجــراءات االســتدالل املرفــق لفــة رقــم (‪.)1‬‬\n‫‪ - 4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n                                                                        ‫رقــم (‪. )23‬‬\n   ‫وببحث سوابقها اتضح عدم وجود سوابق مسجلة عليها حتى تاريخه‪.‬‬\n‫وحيــث إن مــا أقدمــت عليــه املذكــورة فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا لــذا أطلــب إثبــات إدانتهــا مبــا أســند إليهــا واحلكــم عليهــا‬\n                                                                              ‫باآلتــي‪:‬‬\n‫وفقــا للقــرار الــوزاري املشــار إليــه لقــاء مــا‬\n                                                  ‫‪ -1‬بعقوبــة تعزيريــة بحقهــا ً‬\n                                                                      ‫أســند إليهــا ‪.‬‬\n\n\n                                                                                          ‫‪452‬‬\n\f      ‫‪ -2‬مصــادرة اجلــوال املســتخدم يف اجلرميــة مــن نــوع ‪ ...‬ذو الرقــم املصنعــي‬\n                                                            ‫(‪ ).....‬الســتخدامه يف اجلرميــة‪.‬‬\n      ‫‪ -3‬إلغــاء الشــريحة الهاتفيــة املســتخدمة يف اجلرميــة ذات الرقــم (‪).....‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور حكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميم ســمو وزيــر الداخلية‬\n                                            ‫رقــم (‪ )9798‬وتاريــخ ‪1428/2/10- 9‬هــ‪.‬‬\n      ‫‪ -4‬بعقوبــة تعزيريــة لقــاء تســترها علــى مصــدر مــا باعتــه ومــا ضبــط‪.‬‬\n      ‫وبــاهلل التوفيــق وبســؤال املدعــى عليهــا عــن دعــوى املدعــي العــام اجابــت‬\n      ‫املدعــى عليهــا بلغــة عربيــة مفهومــة قائلــة مــا ذكــره املدعــي العــام يف‬\n      ‫ا فقــد قمــت ببيــع حزمــة مــن نبــات‬     ‫دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n      ‫القــات احملظــور تــزن (‪ )158‬مائــة وثمان خمســن جرامـ ًا بقصد االجتار‬\n      ‫والترويــح وحــزت (‪)6‬ســت حــزم مــن القــات احملظــور تــزن جميعهــا‬\n      ‫(‪ )2124‬ألفــان ومائــة وأربــع وعشــرين جرام ـ ًا بقصــد الترويــج وروجــت‬\n      ‫نبــات القــات احملظــور يف الســابق وتســترت علــى مصــدر مــا بعتــه ومــا‬\n      ‫ضبــط واملبلــغ املضبــوط معــي وقــدره الــف وثمامنائــة وخمســن ريــا ًال هــو‬\n      ‫خــاص فينــي وليــس لــه عالقــة بترويــج القــات وليــس علــي ســوابق هكذا‬\n      ‫اجابــت وبطلــب البينــة مــن املدعــي العــام علــى ان املبلــغ املالــي وقــدره الف‬\n      ‫وثمامنائــة وخمســن ريــا ًال انــه من مصدر غير مشــروع فقــال املدعي العام‬\n      ‫ليــس لــدي ســوى مــا يف أوراق املعاملــة وباالطــاع علــى اوراق املعاملــة‬\n      ‫وجــدت تقريــر كيميائــي شــرعي رقــم ( ‪ ).....‬لعــام ‪1434‬ه ـ واملتضمــن‬\n      ‫ـاء علــى مــا‬‫ايجابيــة العينتــن املرســلتني للمــواد الفعالــة لنبــات القــات فبنـ ً‬\n      ‫تقــدم مــن الدعــوى واالجابــة وحيــث اقــرت املدعــى عليهــا بصحــة دعــوى‬\n      ‫املدعــي العــام وحيــث ان مــا أقدمــت عليــه فعــل محــرم تســتحق عليــه‬\n\n\n‫‪453‬‬\n\f‫ـاء علــى قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪ 1374‬ه ـ وحيــث‬        ‫اجلــزاء وبنـ ً‬\n‫قــررت املدعــى عليهــا ان املبلــغ املضبــوط املطلــوب مصادرتــه هــو خــاص‬\n‫بهــا وحيــث لــم يســتطع املدعــي العــام اثبــات عــدم مشــروعيته لهــذا كلــه‬\n‫‪ /‬أو ًال ـ ثبــت لــدي ادانــة املدعــى عليهــا ببيــع حزمــه مــن نبــات القــات‬\n‫احملظــور تــزن (‪)158‬مائــه وثمــان وخمســن جرام ـ ًا بقصــد االجتــار‬\n‫والترويــج وحيازتهــا (‪)6‬ســت حــزم مــن نفــس النــوع تــزن جميعهــا (‪)2124‬‬\n‫ألفــان ومائــة وأربــع وعشــرين جرامـ ًا بقصــد الترويج وترويــج نبات القات‬\n‫يف الســابق وتســترها علــى مصــدر مــا باعتــه ومــا ضبــط وقــررت تعزيرها‬\n‫بســجنها ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفهــا وجلدهــا مائة وخمســن‬\n‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة علــى ان يكــون‬\n‫بــن فتــرات اجللــد مــدة ال تقــل عــن عشــرة ايــام وتغرميهــا خمســمائة ريــال‬\n‫ومصــادرة اجلــوال املســتخدم يف اجلرميــة املذكــور يف الدعــوى والغــاء‬\n‫الشــريحة املســتخدمة يف اجلرميــة املذكــورة يف الدعــوى وعــدم صرفهــا‬\n‫لنفــس املشــتركة وابــاغ الشــركة مصــدرة الشــريحة بذلــك وامــا مــا‬\n‫يتعلــق بتعزيــره لقــاء التســتر فهــو داخــل يف العقوبــة التعزيريــة املذكــورة‬\n‫‪ .‬ثانيـ ًا ـ صــرف النظــر عــن مطالبــة املدعــي العــام مبصــادرة املبلــغ املالــي‬\n‫املضبــوط املذكــور يف الدعــوى ومبــا ذكــر حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام االعتــراض علــى‬\n‫ا اننــي‬ ‫احلكــم وطلــب التمييــز فأجبتــه لطلبــه ثــم قــرر املدعــي العــام قائـ ً‬\n‫اكتفــي بالئحــة الدعــوى العامــة فهــي الالئحــة االعتراضيــة هكــذا‬\n‫قــرر وقــررت املدعــى عليهــا القناعــة باحلكــم وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n\n\n                                                                                             ‫‪454‬‬\n\f      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقم ‪ 341715750‬وتاريخ ‪1434/9/6‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪/‬‬\n      ‫‪.....‬املســجل برقــم ‪ 34279956‬وتاريــخ ‪1434/7/25‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعــي العــام ضــد املــرأة‪(..... /‬صوماليــة اجلنســية) (‪ ).....‬التهامهــا‬\n      ‫بقضيــة قــات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أنــه لــم يتــم‬\n      ‫تصديــق صــورة الضبــط فيالحــظ هــذا مســتقبالً‪ 0‬واهلل املوفــق وصلــى‬\n                                      ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪455‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":449,"source_page_end":455,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"94743c1637cd20b8e798b199b423f7bed7208b08ea0f064fbee19695d5c63331","normalized_text_hash":"5a2a90916e58fae3b5fd26d90dd1a459eea90038bd91bf90e14b9d0094fdcf09","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p449-34279956"},{"id":"9ce5011b-ae0c-53d1-aeac-b3a7011c0c28","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة حشيش بقصد التعاطي -حد املسكر -محاكمته على اجلرمية ذات العقوبة األشد إذا ارتكب عدة جرائم معاقب عليها مبوجب نظام مكافحة املخدرات -التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال -تغليظ العقوبة خلطورة اجلرمية ولوجود سابقة من جنس اجلرمية املنظورة.","document_number":"34351504","case_number":"34337433","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالنماص","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/05","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة حشيش بقصد التعاطي -حد املسكر -محاكمته على اجلرمية ذات العقوبة األشد إذا ارتكب عدة جرائم معاقب عليها مبوجب نظام مكافحة املخدرات -التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال -تغليظ العقوبة خلطورة اجلرمية ولوجود سابقة من جنس اجلرمية املنظورة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34351504:‬تاريخه‪1434/11/05 :‬هـ‬\n                    ‫رقم الدعوى‪34337433 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35114763‬تاريخه‪1435/1/14 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة حشــيش بقصــد‬\n ‫التعاطــي ‪ -‬حــد املســكر ‪ -‬محاكمتــه علــى اجلرميــة ذات العقوبــة‬\n ‫األشــد إذا ارتكــب عــدة جرائــم معاقــب عليهــا مبوجــب نظــام مكافحــة‬\n ‫املخــدرات‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ومصــادرة‬\n ‫اجلــوال ‪ -‬تغليــظ العقوبــة خلطــورة اجلرميــة ولوجــود ســابقة مــن‬\n                                            ‫جنــس اجلرميــة املنظــورة‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -2‬الفقــرة األولــى مــن املــادة ‪ 62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                        ‫العقليــة ‪.‬‬\n             ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -4‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                        ‫العقليــة ‪.‬‬\n                    ‫‪ -5‬قرار مجلس الوزراء رقم ‪ 47‬تاريخ ‪1434/2/18‬هـ ‪.‬‬\n              ‫‪ -6‬برقية وزير الداخلية رقم ‪ 65980‬تاريخ ‪1428/10/22‬هـ ‪.‬‬\n\n\n\n\n                                                                                      ‫‪456‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وترويــج حبــوب‬\n      ‫اإلمفيتامــن وحيــازة حشــيش بقصــد التعاطــي وتعاطيــه لــه ‪ ،‬طلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وعقوبــة تعزيريــة‬\n      ‫وتشــديدها لتعدد ســوابقه ومنعه من الســفر ومصادرة اجلوال املســتخدم‬\n      ‫يف اجلرميــة وإلغــاء الشــريحة ورد املبلــغ املرقــم وفــق األنظمــة والتعليمــات‪،‬‬\n      ‫حيــث مت االتصــال مــن قبــل املصــدر باملدعــى عليــه وطلــب منــه حبوب ـ ًا‬\n      ‫محظــورة مببلــغ مالــي فوافــق املدعــى عليــه وكان ذلــك مبســمع أفــراد‬\n      ‫فرقــة املكافحــة وبنــاء عليــه مت ترقيــم املبلــغ وجتنيــد أحــد األفــراد‬\n      ‫ملرافقــة املصــدر إلــى منــزل املدعــى عليــه ومبقابلــة املدعــى عليــه قــام‬\n      ‫املصــدر بتســليم املدعــى عليــه املبلــغ املتفــق عليــه واســتلم منــه حبتــن‬\n      ‫يشــتبه أنهــا مــن احلبــوب احملظــورة ولــم يتــم القبــض عليــه يف حينــه خشــية‬\n      ‫انكشــاف املصــدر ويف مســاء يــوم آخــر وأثنــاء قيــام الفرقــة بعملهــا مت‬\n      ‫االشــتباه بشــخص يســير علــى قدميــه يف أحــد األماكــن املظلمــة وعنــد‬\n      ‫التوقــف عنــده حــاول الهــرب وقــام برمــي كيــس يف يــده فتــم القبــض‬\n      ‫عليــه ومبعاينــة مــا قــام برميــه ضبطــت قطعــة يشــتبه أن تكــون مــن‬\n      ‫احلشــيش كمــا ضبــط معــه جــوال ‪ .....‬فاتضــح أنــه املدعــى عليــه ‪،‬‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينتــن ملادتــي احلشــيش‬\n      ‫املخــدر واإلمفيتامــن صــادق املدعــى عليــه علــى الدعــوى ماعــدا ترويــج‬\n      ‫احلبــوب احملظــورة بينــة املدعــي العــام شــهود مــن الفرقــة القابضــة‬\n      ‫شــهدت بترويــج املدعــى عليــه للحبــوب احملظــورة ومبــا أن املدعــى عليــه‬\n      ‫صــادق علــى حيــازة احلشــيش بقصــد التعاطــي وتعاطــي احلشــيش ‪ ،‬وبنــاء‬\n\n‫‪457‬‬\n\f‫علــى شــهادة الشــاهدين ‪ ،‬ولكــون مــا صــدر مــن املدعــى عليــه يعــد مــن‬\n‫اإلفســاد يف األرض ‪ ،‬ولوجــود ســوابق علــى املدعــى عليــه ممــا يســتدعي‬\n‫تعزيــره تعزيــرا بالغـ ًا ‪ ،‬احلكــم علــى املدعــى عليــه بحــد املســكر بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة لقــاء تعاطــي احلشــيش ‪ ،‬تعزيــره بالســجن‬\n‫خمــس ســنوات وجلــده مائتــن وخمســن جلــدة مفرقــة علــى دفعــات‬\n‫كل دفعــة خمســن ‪ ،‬تغرميــه ألــف ريــال ‪ ،‬منــع املدعــى عليــه مــن الســفر‬\n‫إلــى اخلــارج بعــد تنفيــذ العقوبــة مــدة مماثلــة لســجنه‪ ،‬ومصــادرة هاتفــه‬\n‫اجلــوال املســتخدم يف الترويــج وإيــداع قيمتــه يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات وإلغــاء الشــريحة وفــق األنظمــة والتعليمــات ‪،‬‬\n‫إلزامــه بــرد املبلــغ احلكومــي املرقــم وقــدره مائــة ريــال ‪ ،‬قنــع املدعــي‬\n‫العــام واعتــرض املدعــى عليــه بالئحــة ‪ُ ،‬صــدق احلكــم مــن الدائــرة‬\n                                    ‫اجلزائيــة الرابعــة مبحكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة العامــة‬\n‫بالنمــاص وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالنمــاص برقــم ‪ 34337433‬وتاريــخ ‪ 1434/07/22‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341759169‬وتاريــخ ‪ 1434/07/22‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/08/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام ‪.....‬مبوجــب‬\n‫خطــاب التعميــد رقــم‪.....‬يف ‪1434/2/26‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫يف مجلــس احلكــم ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫ـاء‬\n‫‪.....‬قائــا يف حتريــر دعــواه أنــه عنــد الســاعة الثامنــة والنصــف مسـ ً‬\n\n                                                                                    ‫‪458‬‬\n\f      ‫ـاء علــى ما توفر مــن معلومات لدى مكافحة‬            ‫بتاريــخ ‪1434/2/14‬ه ـ وبنـ ً‬\n      ‫املخــدرات مبحافظــة النمــاص عــن أن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n      ‫احملظــورة يف محافظــة ‪ ،‬فقــد مت إعــداد اخلطــة الالزمــة وبالتنســيق مــع‬\n      ‫املصــدر مت االتصــال مــن قبــل املصــدر باملدعــى عليــه علــى جوالــه رقــم‬\n      ‫(‪ ).....‬وطلــب منــه حبوب ـ ًا محظــورة مببلــغ (‪ )100‬مائــة ريــال فوافــق‬\n      ‫ـاء عليــه مت ترقيــم‬ ‫املدعــى عليــه وكان ذلــك مبســمع أفــراد الفرقــة وبنـ ً‬\n      ‫املبلــغ احلكومــي وجتنيــد أحــد األفــراد ملرافقــة املصــدر إلــى منــزل‬\n      ‫املدعــى عليــه ‪ ،‬ومبقابلــة املدعــى عليــه قــام املصــدر بتســليم املدعــى‬\n      ‫عليــه املبلــغ املتفــق عليــه واســتلم منــه (‪ )2‬حبتــن يشــتبه أنهــا مــن احلبــوب‬\n      ‫احملظــورة وكان ذلــك أمــام نظــر الفــرد املرافــق للمصــدر ولــم يتــم‬\n      ‫القبض عليه يف حينه خشية انكشاف املصدر وبتاريخ ‪1434/5/24‬هـ‬\n      ‫ـاء وأثنــاء قيــام الفرقــة امليدانيــة ملكافحــة‬ ‫وعنــد الســاعة التاســعة مسـ ً‬\n      ‫املخــدرات مبحافظــة النمــاص بعملهــا يف مركــز ثلــوث املنظــر مت‬\n      ‫االشــتباه يف شــخص يســير علــى قدميــه يف أحــد األماكــن املظلمــة‬\n      ‫وعنــد التوقــف عنــده الحــظ أفــراد الدوريــة فحــاول الهــرب وقــام برمــي‬\n      ‫كيــس يف يــده فتمــت الســيطرة والقبــض عليــه ومبعاينــة مــا قــام برميــه‬\n      ‫ضبطــت قطعــة ســمراء اللــون وزنهــا (‪)9‬جــم تســعة جرامــات يشــتبه أن‬\n      ‫تكــون مــن احلشــيش املخــدر كمــا ضبــط معــه جــوال نــوع ‪...‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ ).....‬واتضــح بأنــه املدعــى عليــه أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي رقــم (‪ ).....‬لعــام ‪1434‬ه ـ احتــواء احلبتــن‬\n      ‫املضبوطتــن اللتــن قــام املدعــى عليــه بترويجهــا بتاريــخ ‪1434/2/14‬ه ـ‬\n      ‫علــى اإلمفيتامــن كمــا أثبــت التقريــر الكيمائــي الشــرعي رقــم (‪).....‬‬\n      ‫لعــام ‪1434‬ه ـ أن عينــة املــادة املضبوطــة بتاريــخ ‪1433/5/24‬ه ـ حشــيش‬\n\n\n‫‪459‬‬\n\f‫مخــدر وحتتــوي علــى املــادة الفعالــة لــه ‪ .‬ومادتــا اإلمفيتامــن واحلشــيش‬\n‫املخــدر مــن املــواد املدرجــة بجــداول املــواد املخــدرة واملؤثــرات العقليــة‬\n‫باجلــدول (‪ )2‬الثانــي الفئــة (ب) واجلــدول (‪ )1‬األول الفئــة (أ) املرفقــة‬\n‫بتعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء‬\n‫وزيــر الداخليــة رقــم (‪ )74831‬وتاريــخ ‪1431/7/9‬ه ـ وبإســتجواب‬\n‫املدعــى عليــه ‪ /‬أقــر بحيــازة قطعــة احلشــيش املخــدر البالــغ وزنهــا (‪)9‬جــم‬\n‫تســعة جرامــات املضبوطــة معــه بتاريــخ ‪1434/5/24‬ه ـ بقصــد التعاطــي‬\n‫وأنــه حصــل عليهــا مببلــغ (‪ )100‬مائــة ريــال مــن شــخص مجهــول الهويــة‬\n‫يســكن يف أحــد اجلبــال وأنــه قبــل القبــض عليــه حــاول الهــرب مــن أفــراد‬\n‫الدوريــة وقــام برمــي قطعــة احلشــيش املضبوطــة وأقــر بأنــه يتعاطــى‬\n‫احلشــيش املخــدر منــذ ثالثــة أشــهر تقريب ـ ًا وأن آخــر مــرة تعاطــى فيهــا‬\n‫احلشــيش املخــدر كان قبــل القبــض عليــه بثالثــة أيــام تقريبـ ًا وأن عليــه‬\n‫ســابقة ترويــج مخــدرات قبــل أربــع ســنوات تقريبـ ًا وصــدق إقــراره بذلــك‬\n‫شــرع ًا كمــا أقــر حتقيقـ ًا بــأن رقــم اجلــوال (‪ ).....‬يخصــه دون غيــره وأنــه‬\n‫مســجل باســمه لــدى االتصــاالت الســعودية وأقــر حتقيق ـ ًا بتعاطيــه‬\n‫الشــراب املســكر وأن آخــر مــرة تعاطــاه كان قبــل ســنة تقريبـ ًا وبعرض‬\n‫املدعــى عليــه علــى الفــرد املرافــق للمصــدر الشــاهد علــى عمليــة بيــع‬\n‫املدعــى عليــه احلبــوب احملظــورة بتاريــخ ‪1434/2/14‬ه ـ اســتطاع‬\n‫التعــرف عليــه وأنــه هــو مــن قــام بتســليم املصــدر احلبــوب املتفــق عليهــا‬\n‫واســتالم املبلــغ احلكومــي وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫للمدعــى عليــه ‪ /‬بشــرب املســكر ‪ ،‬وبترويــج (‪ )2‬حبتــن حتتويــان علــى‬\n‫مــادة االمفيتامــن املنبهــة واحملظــورة عــن طريــق البيــع ‪ ،‬وبحيــازة قطعــة‬\n‫حشــيش مخــدر وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد التعاطــي ‪،‬‬\n\n\n                                                                                       ‫‪460‬‬\n\f      ‫وبتعاطيــه احلشــيش املخــدر لألدلــة والقرائــن التاليــة ‪-1 :‬مــا ورد يف‬\n      ‫إقــراره املصــدق شــرع ًا بحيازتــه قطعــة احلشــيش املخــدر بقصــد التعاطي‬\n      ‫وتعاطيــه لــه ‪ ،‬املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )4‬مــن فباالطالع‬\n      ‫علــى محضــري الشــراء والقبــض والتفتيــش تبــن ملــف التحقيــق املرفــق‬\n      ‫حتقيقــا بعائديــة رقــم اجلــوال املنــوه عنــه‬\n                                                 ‫ً‬      ‫برقــم (‪-2 )14‬مــا ورد يف إقــراره‬\n      ‫إليــه شــخصي ًا وبتعاطيــه للمســكر ‪ ،‬املنــوه عنهمــا واملدونــان علــى‬\n      ‫الصفحتــن رقــم (‪ )5‬ورقــم (‪ )8‬مــن ملــف التحقيــق املرفــق برقــم (‪)14‬‬\n      ‫‪-3‬مــا تضمنــاه محضــرا الشــراء والقبــض والتفتيــش املنــوه عنهمــا‬\n      ‫واملدونــان علــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل املرفــق برقــم‬\n      ‫(‪ )1‬وعلــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل املرفــق برقــم (‪)7‬‬\n      ‫‪-4‬مــا تضمنــه محضــر التعــرف علــى املدعــى عليــه املنــوه عنــه واملرفــق‬\n      ‫برقــم (‪-5 )32‬مــا تضمنــاه التقريــران الكيميائيــان الشــرعيان املنــوه‬\n      ‫عنهمــا واملرفقــان برقــم (‪ )5‬ورقــم (‪ )27‬وحيــث إن مــا أقــدم عليــه املدعى‬\n      ‫عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ونظامـ ًا ومجــرم مبوجــب الفقــرة (‪ )2‬الثانيــة مــن املــادة (‪ )3‬الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬واســتناد ًا للفقــرة (‪)1‬‬\n      ‫األولــى مــن املــادة (‪ )62‬الثانيــة والســتني مــن ذات النظــام لــذا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪-1 :‬جلــده ثمانــون جلــدة‬\n      ‫حــد املســكر ‪-2‬عقوبــة تعزيريــة بحقــه وفق ـ ًا ملــا تضمنتــه الفقــرة (‪)1‬‬\n      ‫األولــى مــن املــادة (‪ )38‬الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه بحدهــا األعلــى ‪ ،‬وتشــديدها بحقــه لتعــدد ســوابقه وعــدم‬\n      ‫ارتداعــه بعقوباتهــا ‪-3‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n\n\n‫‪461‬‬\n\f‫العقوبــة املقــررة بحقــه اســتناد ًا للفقــرة (‪ )1‬األولــى مــن املــادة (‪)56‬‬\n‫السادســة واخلمســن مــن ذات النظــام ‪-4‬مصــادرة جهــازه اجلــوال نــوع ‪.....‬‬\n‫يحمــل الرقــم التسلســلي (‪ ).....‬املســتخدم يف عمليــة الترويــج وفقا للفقرة‬\n‫(‪ )1‬األولــى مــن املــادة (‪ )53‬الثالثــة واخلمســن مــن النظــام املشــار إليــه‬\n‫وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وفق ـ ًا‬\n‫لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1431/2/18‬ه ـ وإلغــاء شــريحة‬\n‫االتصــال للرقــم (‪ ).....‬املســتخدمة يف اجلرميــة وعــدم صرفهــا لــه مــرة‬\n‫أخــرى وفقــا لتعميــم صاحــب الســمو امللكــي النائــب لرئيــس مجلــس‬\n‫الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ‬\n‫‪-5‬إلزامــه بدفــع مبلــغ (‪ )100‬مائــة ريــال املبلــغ احلكومــي املرقــم وفقـ ًا ملــا‬\n‫تضمنتــه برقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه عمــا جــاء يف دعــوى املدعــي العــام أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام مــن أنــه قبــض علــي يف املــكان والتاريــخ وأننــي قمــت‬\n‫بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪ )9‬تســعة جرامــات بقصــد‬\n‫التعاطــي وبتعاطــي احلشــيش املخــدر فهــذا صحيــح أمــا مــا ذكــره مــن‬\n‫أننــي قمــت بترويــج حبتــن مــن مــادة األمفيتامــن املنبهــة عــن طريــق البيع‬\n‫فغيــر صحيــح وبســؤال املدعــي العــام عــن البينــة التــي تثبــت صحــة دعــواه‬\n‫بــأن املدعــى عليــه قــام بترويــج حبتــن مــن احلبــوب احملظــورة قــال أطلــب‬\n‫مهلــة إلحضــار الفرقــة القابضــة وعليــه رفعــت اجللســة وتأجلــت إلــى يــوم‬\n‫الثالثــاء املوافــق ‪1434/8/23‬ه ـ الســاعة التاســعة والنصــف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/08/21‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضي‬\n\n\n                                                                                         ‫‪462‬‬\n\f      ‫باحملكمــة العامــة بالنمــاص وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بالنمــاص برقــم ‪ 34337433‬وتاريــخ‬\n      ‫‪ 1434/07/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341759169‬وتاريــخ‬\n      ‫‪ 1434/07/22‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/11/05‬هـ افتتحت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وجــرى ســؤال املدعــي العــام عــن البينــة التــي وعــد بإحضارهــا قــال‬\n      ‫أحضــرت للشــهادة وأدائهــا كال مــن ‪ ..........‬ســعودي اجلنســية بالســجل‬\n      ‫املدنــي رقــم ‪.....‬وبســؤاله عــن عمــره ومحــل إقامتــه وصلتــه بالطرفــن‬\n      ‫أجــاب مــن مواليــد عــام ‪1394‬ه ـ ومحــل إقامتــي ‪ ......‬وليــس لــي صلــة‬\n      ‫بالطرفــن ‪..... .‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫وبســؤاله عــن عمــره ومحــل إقامتــه وصلتــه باملدعــى عليــه أجــاب مــن‬\n      ‫مواليــد عــام ‪1392‬ه ـ ومحــل إقامتــي ‪ .......‬وليــس لــي صلة قرابــة باملدعى‬\n      ‫عليــه وباستشــهادهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫مبفــرده قائــا واهلل العظيــم أنــه يف يــوم اخلميــس املوافــق ‪1434/2/14‬هـ‬\n      ‫وأثنــاء قيامنــا بالعمــل امليدانــي توفــرت لدينــا معلومــة مــن أحــد مصادرنــا‬\n      ‫الســرية عــن شــخص يقــوم بترويــج احلبــوب احملظــورة يســكن يف‬\n      ‫محافظــة ‪ .........‬طريــق ‪.....‬يدعــى ‪.......... /‬وعندهــا مت إعــداد اخلطــة‬\n      ‫الالزمــة وعندهــا مت االتصــال عليــه مــن جــوال املصــدر علــى جــوال املروج‬\n      ‫رقــم (‪ ).....‬وطلــب منــه حبــوب محظــورة مببلــغ مائــة ريــال فوافــق املــروج‬\n      ‫علــى ذلــك وكان علــى مســمع مــن أفــراد الفرقــة فتــم ترقيــم املبلــغ‬\n      ‫احلكومــي كمــا يتضــح مــن صفحــة رقــم (‪ )4‬وجتنيــد أحــد أراد الفرقــة‬\n      ‫املرافقــة املصــدر إلــى منــزل املــروج فتــم االنتقــال إلــى املوقــع املتفــق عليــه‬\n      ‫ـاءا وعنــد الوصــول‬   ‫وكان ذلــك يف متــام الســاعة الثامنــة والنصــف مسـ ً‬\n\n‫‪463‬‬\n\f‫إلــى املوقــع خــرج املــروج مــن منزلــه وقــام املصــدر بالنــزول مــن الســيارة‬\n‫ومقابلــة املــروج وعندهــا قــام املصــدر بتســليمه املبلــغ املتفــق عليــه‬\n‫واســتالم احلبــوب احملظــورة وكان ذلــك أمــام نظــر الفــرد املرافــق‬\n‫وعندهــا حظــر املصــدر إلــى الفــرد املرافــق وســلمه عــدد حبتــن حتمــل‬\n‫العالمــة املميــزة لعقــار الكبتاجــون فتــم االنتقــال مــن املوقــع وأرجــيء‬\n‫القبــض علــى املــروج خشــية انكشــاف املصــدر وحرصــه الشــديد‬\n‫وعندهــا مت التحفــظ علــى املضبوطــات وتســليمها لضابــط خفــر املنــاوب‬\n‫يف الشــعبة طرفنــا هكــذا شــهدا وبعــرض الشــاهدين ومــا جــاء يف‬\n‫شــهادتهما علــى املدعــى عليــه أجــاب قائــا أمــا الشــاهدين فــا أعرفهمــا‬\n‫وال أقــول فيهمــا إال خيــرا أمــا مــا جــاء يف شــهادتهما فغيــر صحيــح وقــد‬\n‫جــرى تعديــل الشــاهدين مــن قبــل كال مــن ‪.....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪.....‬و‪.....‬ســعودي بالســجل املدنــي رقــم ‪.....‬حيــث‬\n‫شــهدا بعدالــة وثقــة الشــاهدين هــذا وجــرى االطــاع علــى محضــر‬\n‫القبــض والتفتيــش وصحيفــة الســوابق والتقارير الكيميائية والشــرعية‬\n‫وإقــرار املدعــى عليــه املصــدق شــرعا فوجــدت أنهــا جميعــا مطابقــة ملــا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n                                            ‫جــاء يف دعــوى املدعــي العــام فبنـ ً‬\n‫املتضمنــة مصادقــة املدعــى عليــه علــى مــا ورد يف دعــوى املدعــي العــام‬\n‫مــن قيامــه بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪ )9‬جــم تســعة‬\n‫ـاء علــى شــهادة‬\n                ‫جرامــات بقصــد التعاطــي وبتعاطيــه احلشــيش املخــدر وبنـ ً‬\n‫الشــاهدين وفــق األصــول الشــرعية ولكــون مــا صــدر مــن املدعــى عليــه‬\n‫يعــد مــن اإلفســاد يف األرض نظـ ًـرا النتشــار تعاطــي املخــدرات بــن‬\n‫أوســاط الشــباب ونظـ ًـرا ملــا يترتــب عليهــا مــن آثــار ســيئة صحيــة ونفســية‬\n‫واجتماعيــة ونظـ ًـرا لوجــود ســبع ســوابق علــى املدعــى عليــه مــن نفــس‬\n\n\n                                                                                      ‫‪464‬‬\n\f      ‫النــوع ولــم تردعــه عقوبتهــا ممــا يســتوجب تعزيــره تعزيـ ًـرا بال ًغــا يردعــه‬\n      ‫ويزجــر غيــره لذلــك كلــه فقــد قــررت مــا يلــي أوالً‪ /‬إقامة حد املســكر‬\n      ‫علــى املدعــى عليــه وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة لقــاء إقــراره‬\n      ‫ثانيــا‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بترويــج‬\n                                                         ‫بتعاطــي احلشــيش املخــدر ً‬\n      ‫(‪ )2‬حبتــن مــن مــادة االمفيتامــن املنبهــة واحملظــورة وحيــازة قطعــة‬\n      ‫حشــيش مخــدر بلــغ وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد التعاطــي‬\n      ‫وقــررت تعزيــر املدعــى عليــه بالســجن ملــدة خمــس ســنوات تبــدأ مــن‬\n      ‫تاريــخ توقيفــه وجلــده مائتــي وخمســن جلــدة مفرقــة علــى دفعــات كل‬\n      ‫دفعــة خمســن جلــدة بــن الدفعــة والتــي تليهــا مــدة ال تقــل عــن عشــرة‬\n      ‫أيــام علــى أن يكــون اجللــد يف مــكان عــام وتغرميــه ألــف ريــال وذلــك‬\n      ‫اســتنا ًدا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات مــع مالحظــة أن‬\n      ‫تكــون هــذه العقوبــة شــاملة ملــا صــدر مــن املدعــى عليــه مــن قيامــه‬\n      ‫بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪)9‬جــم تســعة جرامــات بقصــد‬\n      ‫التعاطــي وذلــك اســتنا ًدا للفقــرة األولــى مــن املــادة (‪ )62‬مــن النظــام‬\n      ‫املشــار إليــه والتــي تنــص علــى أنــه إذا ارتكــب شــخص عــدة جرائــم‬\n      ‫معاقــب عليهــا مبوجــب أحــكام هــذا النظــام قبــل صــدور حكــم نهائــي‬\n      ‫بحقــه عــن أي واحــدة منهــا وجــب محاكمتــه علــى اجلرميــة ذات العقوبــة‬\n      ‫األشــد واحلكــم بعقوبتهــا دون غيرهــا وبــه حكمــت ثال ًثــا‪ /‬قــررت منــع‬\n      ‫املدعــى عليــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة بحقــه مــدة‬\n      ‫مماثلــة ملــدة ســجنه وذلــك اســتنا ًدا للمــادة (‪ )56‬مــن النظــام املشــار إليــه‬\n      ‫رابعــا‪ /‬قــررت مصــادر جهــاز اجلــوال نــوع ‪ ........‬يحمــل‬  ‫وبــه حكمــت ً‬\n      ‫الرقــم التسلســلي (‪ ).....‬املســتخدم يف عمليــة الترويــج اســتنا ًدا للفقــرة‬\n      ‫األولــى مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه وإيــداع قيمتــه يف حســاب‬\n\n\n‫‪465‬‬\n\f‫اإلدارة العامــة ملكافحــة املخــدرات وفقــا لقــرار مجلــس الــوزراء رقــم‬\n‫(‪ )47‬يف ‪1431/2/18‬ه ـ وإلغــاء شــريحة االتصــال للرقــم (‪).....‬‬\n‫واملســتخدمة يف اجلرميــة وعــدم صرفهــا لــه مــرة أخــرى وبــه حكمــت‬\n‫خامســا‪ /‬إلزامــه بدفــع مبلــغ (‪ )100‬مائــة ريــال املبلــغ احلكومــي املرقــم‬\n                                                                           ‫ً‬\n‫وفقــا ملــا تضمنتــه برقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫‪ 65980/4/5/1‬يف ‪1428/10/22‬ه ـ وبــه حكمــت وبإعــان احلكــم‬\n‫علــى الطرفــن قــرر املدعــي العــام عــدم املعارضــة أمــا املدعــى عليــه‬\n‫فقــرر عــدم القناعــة وطلــب االســتئناف واســتعد بتقــدمي الئحــة اعتراضية‬\n‫وأجيــب لطلبــه وســلم نســخة مــن القــرار يف هــذا اليــوم وأفهــم بــأن مــدة‬\n‫االعتــراض ثالثــن يومــا تبــدأ مــن هــذا اليــوم ففهــم ذلــك وأقفلــت اجللســة‬\n‫يف متــام الســاعة احلاديــة عشــر والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/11/05‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القاضــي باحملكمــة العامــة بالنمــاص الشــيخ ‪..... /‬‬\n‫برقــم ‪ 341759169‬وتاريــخ ‪1434/12/29‬ه ـ املرفــق بها القرار الصادر‬\n‫مــن فضيلتــه برقــم ‪ 34351504‬وتاريــخ ‪1434/11/5‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ض ــد ‪..... /‬يف قضيــة (مخــدرات) علــى الصفــة املوضحة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‬\n         ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪466‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":456,"source_page_end":466,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13348a212f0ec82dd8dff04cd7e997bb7930e7a3ea5b0e00b7699cc26b37c587","normalized_text_hash":"14e5dad1cc7b98a6422376bbf893765d734e038ceb1617b4e97a6709fdd95e53","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p456-34351504"},{"id":"c1186a79-1ef2-59b8-a292-7699ccd638f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -التعزير باجللد والسجن والغرامة. -1قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } .","document_number":"34314670","case_number":"34393987","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/8","year":"1434","subject":"مخدرات -ترويج -قات -التعزير باجللد والسجن والغرامة. -1قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه ‪1434/9/8 :‬هـ‬  ‫رقم الصك ‪34314670:‬‬\n                          ‫رقم الدعوى‪34393987:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34342200‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n                 ‫مخدرات ‪ -‬ترويج ‪ -‬قات ‪ -‬التعزير باجللد والسجن والغرامة‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قول اهلل تعالى {وال تفسدوا يف األرض بعد إصالحها } ‪.‬‬\n               ‫‪ -2‬املادة الثالثة من قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374‬هـ ‪.‬‬\n        ‫‪ -3‬قــرار مجلــس الــوزراء رقــم (‪ )172‬يف ‪1400/9/23‬ه ـ املتضمــن أن‬\n                    ‫العقوبــات الــواردة يف القــرار رقــم ‪ 11‬هــي احلــد األعلــى‪.‬‬\n                      ‫‪ -4‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ ‪.‬‬\n        ‫‪ -5‬خطــاب وزيــر الداخليــة املوجــه إلــى أميــر جــازان رقــم (‪)13476‬‬\n        ‫يف ‪1433/2/22‬ه ـ املتضمــن أن تقريــر العقوبــة هــو مــن اختصــاص‬\n                                                                        ‫احلا كــم‪.‬‬\n\n\n\n\n        ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا باالشــتراك يف ترويــج قــات‬\n        ‫بقصــد االجتــار عــن طريــق النقــل وتســترهما علــى املــروج ‪،‬حيــث‬\n        ‫اعترفــا بعــد القبــض عليهمــا لالشــتباه بأنهمــا قامــا بتســليم القــات‬\n        ‫لشــخصني ســعوديني وأن املدعــى عليــه األول اســتلم القــات واملدعــى‬\n        ‫عليــه الثانــي يقــوم مبســح الطريــق ويتواصــل مــع املســتلمني ‪ ،‬وطلــب‬\n        ‫إثبــات مــا أســند إليهمــا وتعزيرهمــا لقــاء الترويــج والتســتر علــى املــروج‬\n\n‫‪467‬‬\n\f‫ومصــادرة الســيارة واجلــوال واملبلــغ املالــي املتحصــل مــن اجلرميــة ‪ ،‬صــادق‬\n‫املدعــى عليهمــا علــى الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمة‬\n‫بتعزيرهمــا بالســجن ســنة ونصــف وتغــرمي كل واحــد منهمــا ألــف ريــال‬\n‫وبتعزيرهمــا بجلــد كل واحــد منهمــا خمســن جلــدة دفعــة واحــدة لقــاء‬\n‫التســتر وصــرف النظــر عــن طلبــات املدعــي العــام وقنــع املدعــى عليهمــا‬\n‫‪،‬وصــدق احلكــم‬  ‫باحلكــم واعتــرض املدعــي العــام بالئحــة اعتراضيــة ُ‬\n                                                     ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/9/7‬ه ـ ويف متــام الســاعة‬\n‫الثانيــة والنصــف ظهــر ًا افتتحــت اجللســة لدي أنــا ‪.....‬القاضي باحملكمة‬\n‫ـاء علــى املعاملــة احملالــة لنــا من فضيلــة رئيس احملكمة‬‫اجلزائيــة بأبهــا بنـ ً‬\n‫اجلزائيــة بأبهــا املســاعد برقــم ‪ 34393987‬يف ‪1434/8/23‬ه ـ واملقيــدة‬\n‫لدينــا برقــم ‪ 342032948‬يف ‪1434/8/23‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام ‪...../‬املكلــف مــن قبــل االدعــاء العــام مبوجــب أمــر التكليــف‬\n‫رقــم ‪.....‬يف ‪1430/9/9‬ه ـ ضــد الســجني ‪..... /‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪.....‬والســجني ‪.....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــي ‪.....‬يف تهمــة حيــازة نبــات محظــور بقصــد االجتــار ‪ .‬وقــد‬\n‫تقــدم املدعــي العــام بدعــوى نــص احلاجــة منهــا باالطــاع علــى محضــر‬\n‫القبــض والتفتيــش املعــد مــن قبــل فرقــة مكافحــة املخــدرات مبنطقــة‬\n‫عســير تبــن أنــه بعــد ظهــر يــوم الســبت املوافــق ‪1434/8/6‬ه ـ توفــرت‬\n‫معلومــات لديهــم عــن قيــام شــخصني ســعوديني باســتالم وتســليم كميــة‬\n‫مــن املمنوعــات يف املــكان املســمى ‪.....‬علــى الطريق الرابط بــن ‪............‬‬\n\n                                                                                       ‫‪468‬‬\n\f      ‫و ‪ ...........‬فتمــت املتابعــة عــن طريــق التقنيــة املتاحــة واتضــح بــأن املســتلم‬\n      ‫لتلــك الكميــة ال يعــرف مــكان تواجــده وأمــا الــذي قــام بالتســليم‬\n      ‫اتضــح بأنــه عائــد ملدينــة ‪ ......‬وبعــد البحــث عنــه اتضــح بأنــه علــى طريــق‬\n      ‫‪ ...‬متجهــا إلــى طريــق ‪ ..............‬ومبســح الطريــق شــوهدت ســيارة مــن‬\n      ‫نــوع ‪ .......‬صنــع عــام (‪2013‬م) حتمــل اللوحــة رقــم (‪ ).....‬كانــت متوقفــة‬\n      ‫عنــد محطــة ‪.....‬للمحروقــات ب‪ .....‬وكان بهــا شــخصني فتــم اســتيقافها‬\n      ‫بعــد وصولهــا إلــى بوابــة مستشــفى الصحــة النفســية وقبــض علــى مــن‬\n      ‫بداخلهــا واتضــح بــأن قائــد الســيارة هــو املتهــم (‪ ).....‬ويرافقــه املتهــم‬\n      ‫(‪ ).....‬وبتفتيشــهما والســيارة املنــوه عنهــا لــم يعثــر علــى أي شــيء مــن‬\n      ‫املمنوعــات ‪ ،‬وبســماع أقوالهمــا اعترفــا بأنهمــا قامــا بتســليم كميــة‬\n      ‫مــن نبــات القــات احملظــور يقــدر عددهــا بســتمائة وســتة وســتني (‪)666‬‬\n      ‫حزمــة لشــخصني ســعوديني كان معهمــا ســيارة مــن نــوع (‪ ).......‬أبيــض‬\n      ‫قابالهمــا بعــد مثلــث ‪.....‬وأن (‪ ).....‬اســتلم كميــة القــات مــن عنــد‬\n      ‫كبــري ‪ .... ...‬مــن شــخص جيزانــي ال يعــرف عنــه شــيء وكانــت تلــك‬\n      ‫الكميــة محملــة يف ســيارة مــن نــوع ‪ ......‬بيضــاء اللــون ال يعــرف رقــم‬\n      ‫لوحتهــا والتــي كان يقــوم بقيادتهــا وأن (‪ ).....‬كان يقــود ‪ ......‬ويقــوم‬\n      ‫مبســح الطريــق ويتواصــل مــع املســتلمني للقــات بواســطة جوالــه رقــم‬\n      ‫(‪ . ).....‬وانتهــى التحقيــق الــى توجيــه االتهــام ل ـ ‪ ..... /‬و‪ ،.....‬باالشــتراك‬\n      ‫يف ترويــج كميــة تقــدر بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات‬\n      ‫القــات احملظــور لــم يتــم ضبطهــا عــن طريــق النقــل بقصــد االجتــار املادي‬\n      ‫‪ ،‬واحملــرم شــرع ًا واملجــرم نظام ـ ًا مبوجــب املــادة (الثالثــة) مــن قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ وتســترهما علــى مــروج القــات‬\n      ‫واحلائــز لــه بعــد اســتالمه املعاقــب عليــه شــرعا ‪ .‬وبالبحــث عن ســوابقهما‬\n\n\n‫‪469‬‬\n\f‫لــم يعثــر لهمــا علــى شــيء لــذا اطلب إثبــات إدانتهما باالشــتراك يف ترويج‬\n‫كميــة تقــدر بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات القــات‬\n‫احملظــور عــن طريــق النقــل واحلكــم عليهمــا بعقوبــة تعزيريــة تزجرهمــا‬\n‫وتــردع غيرهمــا وفقــا للمــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم ‪11‬‬\n‫لعــام ‪ 1374‬وتعزيرهمــا لقــاء تســترهما علــى مــروج القــات واحلائــز لــه‬\n‫بعــد االســتالم ومصــادرة الســيارة نــوع ‪ ......‬غمــارة صنــع عــام (‪2013‬م)‬\n‫حتمــل اللوحــة رقــم (‪ ).....‬واجلــوال ورقمــه املصنعــي (‪ ).....‬واملبلــغ املالــي‬\n‫املتحصــل مــن اجلرميــة وقــدره ألــف ريــال (‪ )1000‬وفــق املــادة (‪)1/53‬‬\n‫الثالثــة واخلمســون الفقــرة األولــى مــن نظــام املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليــه وإيــداع قيمتهــا بحســاب املديرية العامــة ملكافحة املخدرات‬\n‫لــدى مؤسســة النقــد وفقــا للفقــرة الثانيــة مــن قــرار مجلــس الــوزراء‬\n‫رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ ‪ .‬هكــذا ادعــى وبعــرض الدعــوى‬\n‫علــى املدعــى عليهمــا أجــاب كل واحــد بقولــه مــا جــاء يف الدعــوى مــن‬\n‫قيامنــا بنقــل كميــة القــات املوصوفــة يف الدعــوى مــن (‪ ).................‬إلــى‬\n‫مدينــة (‪ )..................‬بقصــد الترويــج مبقابــل مــادي صحيــح ومــا ذكــر‬\n‫املدعــي العــام مــن كوننــا قمنــا بالتســتر علــى املســلم واملســتلم لكميــة‬\n‫نبــات القــات فــا نعلــم عــن ذلــك شــيئ ًا علمـ ًا أننــا لــم نبلــغ عنهمــا اجلهــات‬\n‫األمنيــة وقــد أخذنــا مقابــل ذلــك مبلــغ مالــي قــدره الــف ريــال هكــذا‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرره الطرفــان‬      ‫أجابــا‪ .‬فبنـ ً‬\n‫وألن املدعــى عليهمــا أقــرا بقيامهمــا بنقــل كميــة القــات املوصوفــة يف‬\n‫الدعــوى مبقابــل بقصــد الترويــج ونظــر ًا ألنهمــا أقــرا بأنهمــا لــم يقومــا‬\n‫بتبليــغ اجلهــات األمنيــة عــن الشــخص املســلم واملســتلم لكميــة القــات‬\n‫وألن هــذا العمــل يف حقيقتــه هــو تســتر مــن قبلهمــا علــى أمثــال هــؤالء‬\n\n\n                                                                                              ‫‪470‬‬\n\f      ‫والواجــب بحقهمــا التبليــغ عنهمــا واســتناد ًا علــى قــرار مجلــس الــوزراء‬\n      ‫رقــم ‪ 11‬يف ‪13747‬ه املــادة الثالثــة منــه وعلــى قــرار مجلــس الــوزراء‬\n      ‫رقــم ‪ 172‬يف ‪1400/9/23‬ه املتضمــن أن العقوبــات الــواردة يف القــرار‬\n      ‫رقــم ‪ 11‬هــي احلــد األعلــى واســتناد ًا علــى األمــر الســامي الكــرمي رقــم‬\n      ‫‪ 59633‬يف ‪1432/12/9‬ه وعلــى خطــاب ســمو وزيــر الداخليــة املوجــه‬\n      ‫إلــى ســمو أميــر منطقــة جــازان رقــم ‪ 13476‬يف ‪1433/2/22‬ه املتضمــن‬\n      ‫أن تقريــر العقوبــة هــو مــن اختصــاص احلاكــم ونظــر ًا ألن هــذا العمــل‬\n          ‫محــرم شــرع ًا وهــو مــن اإلفســاد يف األرض واملنهــي عنــه بقولــه تعالــى‬\n      ‫( وال تفســدوا يف األرض بعــد إصالحهــا ) وملنافــاة هــذا العمــل ملــا أمــر‬\n      ‫اهلل بحفظــه مــن العقــل واملــال ولــكل مــا تقــدم حكمــت مبــا يلــي أو ًال‬\n      ‫‪ :‬ثبــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف ترويــج كميــة تقــدر‬\n      ‫بســتمائة وســتة وســتني (‪ )666‬حزمــة مــن نبــات القــات احملظــور لــم يتــم‬\n      ‫ضبطهــا عــن طريــق النقــل بقصــد االجتــار املادي ثانيـ ًا ‪ :‬حكمت بتعزير‬\n      ‫املدعــى عليهمــا بســجن كل واحــد منهمــا ملــدة ســنة ونصــف تبــدأ مــن‬\n      ‫تاريــخ إيقــاف كل واحــد يف هــذه القضيــة وبتغــرمي كل واحــد منهمــا‬\n      ‫ألــف ريــال تــودع يف خزينــة الدولــة كل ذلــك لقــاء نقلهمــا لكميــة القــات‬\n      ‫املوصوفــة يف الدعــوى ثالث ـ ًا حكمــت بتعزيــر كل واحــد منهمــا لقــاء‬\n      ‫التســتر باجللــد خمســن جلــدة دفعــة واحــدة رابع ـ ًا صرفــت النظــر عــن‬\n      ‫طلبــات املدعــي العــام تطبيــق املادة الثالثة واخلمســن مــن نظام املخدرات‬\n      ‫بحــق املدعــى عليهمــا ألنــه ال محــل لهــا حيــث اســتثنيت قضايــا القــات‬\n      ‫مــن هــذا النظــام باألمــر الســامي املشــار إليــه بعاليــه وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــى عليهمــا عــدم االعتــراض وقــرر املدعــي‬\n      ‫العــام عــدم القناعــة مســتعد ًا بتقــدمي الئحــة فجــرى تســليمه نســخة مــن‬\n\n\n‫‪471‬‬\n\f‫إعــام احلكــم وأفهمتــه أن لــه بعــد ذلــك ثالثــون يومـ ًا ليقــدم الئحتــه فــإن‬\n‫لــم يفعــل ســقط حقــه يف ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة‬\n‫االســتئناف بعســير لتدقيــق احلكــم كاملتبــع جــرى النطــق باحلكــم‬\n‫بتاريــخ ‪1434/9/7‬ه ـ ورفعــت اجللســة عنــد الســاعة الثالثــة وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد ‪.‬ويف يــوم اخلميــس ‪1434 / 11 /13‬ه ـ افتتحــت‬\n‫اجللســة يف متــام الســاعة احلاديــة عشــرة والربــع وفيهــا عــادت املعاملــة‬\n‫رفــق خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم‬\n‫‪ 342398152‬يف ‪1434/11/4‬ه ـ مرفقــا بهــا قــرار املالحظــة الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثالثــة رقــم ‪ 34342200‬يف ‪1434/ 10/27‬ه ـ‬\n‫املتضمــن نــص احلاجــة منــه مــا يلــي ( وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة أن فضيلتــه لــم ينــوه عــن الالئحــة االعتراضيــة املقدمــة مــن‬\n‫ا باملــادة ‪ 1/181‬مــن نظــام املرافعــات‬   ‫املدعــي العــام باالطــاع عليهــا عمـ ً‬\n‫الشــرعية فعلــى فضيلتــه إكمــال الــازم واهلل املوفــق )انتهــى بتوقيــع‬\n‫وختــم قاضــي اســتئناف الشــيخ ‪.....‬وبتوقيــع وختــم قاضــي اســتئناف‬\n‫الشــيخ ‪.....‬و بتوقيــع وختــم رئيــس الدائــرة الشــيخ ‪.....‬وأجيــب أصحــاب‬\n‫الفضيلــة وفقهــم اهلل بــأن ذلــك وقــع ســهوا وجــرى معاجلتــه يف مكانــه‬\n‫ولــذا جــرى مبوجبــه التهميــش وأمــرت برفــع املعاملــة الــى محكمــة‬\n‫اإلســتئناف للتدقيــق كاملتبــع ورفعــت اجللســة عنــد الســاعة احلاديــة‬\n                   ‫عشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بأبهــا برقــم ‪342398152‬‬\n\n\n                                                                                       ‫‪472‬‬\n\f      ‫وتاريخ ‪1434/11/23‬هـ املرفق بها القرار الصادر من فضيل ــة القاضي‬\n      ‫باحملكمــة الشــيخ‪..... /‬برقــم ‪ 34314670‬وتاريــخ ‪1434/9/8‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد كل مــن ‪...../‬و ‪.....‬يف قضيــة (‬\n      ‫قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلتــه واحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قــرار الدائــرة رقــم‬\n      ‫‪ 34342200‬وتاريــخ ‪1434/10/27‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪473‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":467,"source_page_end":473,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97075a67ca045ec9509bc52add710950967b70023cb475e9e3867115ae1c57e3","normalized_text_hash":"e0f0433b8ab17e0be8b5fa929dc5ee7bd756e1e169e8b100700f4c8b295d23df","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p467-34314670"},{"id":"19aaa460-1cec-5234-b9a8-2a0efeef43cf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج -قات -هروب املدعى عليه من رجال األمن - تستر على مصدر ما مت ضبطه -التعزير بالسجن واجللد والغرامة وإتاف الكمية املضبوطة -مصادرة السيارة.","document_number":"34325520","case_number":"34423794","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/24","year":"1434","subject":"مخدرات -ترويج -قات -هروب املدعى عليه من رجال األمن - تستر على مصدر ما مت ضبطه -التعزير بالسجن واجللد والغرامة وإتاف الكمية املضبوطة -مصادرة السيارة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34325520:‬تاريخه‪1434/9/24:‬هـ‬\n                   ‫رقم القضية‪34423794:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34344853‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج ‪ -‬قــات ‪ -‬هــروب املدعــى عليــه مــن رجــال األمــن ‪-‬‬\n‫تســتر علــى مصــدر مــا مت ضبطــه ‪ -‬التعزيــر بالســجن واجللــد والغرامة‬\n                         ‫وإتــاف الكميــة املضبوطــة ‪ -‬مصــادرة الســيارة‪.‬‬\n\n\n\n\n                ‫‪ -1‬األمر السامي الكرمي رقم(‪ )59633‬يف ‪1432/12/9‬هـ ‪.‬‬\n  ‫‪ -2‬املادة الثالثة من قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n                      ‫‪ -3‬قرار مجلس الوزراء رقم (‪ )47‬يف ‪1421/2/18‬هـ ‪.‬‬\n                   ‫‪ -4‬قرار وزير الداخلية رقم(‪ )2057‬يف ‪ 1404/5/26‬هـ ‪.‬‬\n‫‪ -5‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫والهــروب مــن رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة بعــد‬\n‫هروبــه وتســتره علــى مصــدر مــا مت ضبطــه وطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم بتعزيــره وفــق املــادة الثالثــة مــن القــرار رقــم (‪ )11‬لعــام‬\n‫‪1374‬ه وتعزيــره لقــاء تســتره علــى مصــدر مــا مت ضبطــه وهروبــه مــن‬\n‫رجــال األمــن ومصــادرة ســيارته املســتخدمة يف اجلرميــة وذلــك أثنــاء قيــام‬\n\n                                                                                     ‫‪474‬‬\n\f      ‫الدوريــة األمنيــة بواجبهــا مت مشــاهدة ســيارة يقودهــا املدعــى عليــه‬\n      ‫وعنــد اســتيقافه رفــض االمتثــال والذ بالفــرار بســرعة عاليــة وأثنــاء‬\n      ‫املطــاردة كان الغبــار كثيف ـ ًا ممــا أدى إلــى انحــراف ســيارة الدوريــة‬\n      ‫وانقالبهــا وبعدهــا قــام املدعــى عليــه بإيقــاف الســيارة لتعطلهــا والذ‬\n      ‫بالفــرار وبتفتيــش الســيارة عثــر علــى كميــة مــن نبــات أخضــر يشــتبه‬\n      ‫أن يكــون مــن القــات وبعــد ذلــك مت القبــض عليــه وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n      ‫‪،‬صــادق املدعــى عليــه علــى االدعــاء املوجــه إليــه ‪،‬وبنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بســجنه خمــس ســنوات وجلــده ســبعمائة جلــدة علنــا‬\n      ‫مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة وغرامــة ماليــة قدرهــا‬\n      ‫عشــرة آالف ريــال تــودع لصالــح بيــت مــال املســلمني ومصــادرة وإتــاف‬\n      ‫القــات املضبــوط ومصــادرة الســيارة املســتخدمة يف اجلرميــة وإيــداع ثمنهــا‬\n      ‫يف حســاب اإلدارة العامــة ملكافحــة املخــدرات واعتــرض املدعــى عليــه‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬       ‫واملدعــي العــام بــدون الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫ـاء علــى أوراق املعاملــة‬\n                             ‫حاليــا بنـ ً‬\n                                      ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة بجــازان ً‬\n      ‫الــواردة مــن محكمــة االســتئناف مبنطقة عســير برقــم (‪)341901650‬‬\n      ‫وتاريــخ ‪1434/8/30‬ه ـ واملقيــدة بقيــد احملكمــة طرفنــا برقــم‬\n      ‫‪ 342146007‬يف ‪1434/9/8‬ه ـ واإلحالــة رقــم (‪ )34423794‬وتاريــخ‬\n      ‫‪1434/9/14‬ه ـ عطفـ ـ ًـا علــى رقــم الــورود الـس ــابق مــن هيئــة التحقيــق‬\n      ‫واالدعــاء العــام بـمنـطـق ــة ج ــازان بـرق ــم (‪ )309‬يف ‪1434/3/1‬ه ـ‬\n‫‪475‬‬\n\f‫واملقيــدة بقيــد األســاس رقــم (‪ )34562987‬يف ‪1434/3/4‬ه ـ واحملالــة‬\n‫إلــى املكتــب القضائــي الرابــع باحملكمــة طرفنــا مبوجــب اإلحالــة‬\n‫الســابقة رقــم (‪ )34107415‬والصــادر بهــا القــرار الشــرعي رقــم‬\n‫(‪ )3456645‬وتاريــخ ‪ 1434/3/7‬ه ـ واملنقــوض أخيـ ًـرا مــن محكمــة‬\n‫االســتئناف مبنطقــة عســير مبوجــب قــرار النقــض الصــادر مــن الدائــرة‬\n‫اجلزائيــة الرابعــة برقــم (‪)34294301‬وتاريــخ ‪1434/8/10‬ه ـ اخلاصــة‬\n‫بالســجني ‪ ...../‬املتهــم يف قضيــة قــات ؛ عليــه ففــي هــذا اليــوم الثالثــاء‬\n‫املوافــق ‪1434/9/15‬ه ـ افتتحــت اجللســة الســاعة العاشــرة والنصــف‬\n‫صباحــا بحضــور املدعــي العــام واملدعــى عليــه ؛ وجــرى م ّنــا اإلطــاع‬   ‫ً‬\n‫علــى الئحــة الدعــوى العامــة اخلطيــة املرفقــة بــأوراق املعاملــة املقدمــة مــن‬\n‫املدعــي العــام بدائــرة اإلدعــاء العــام بجــازان ‪..... /‬املوجــه إلينــا مبوجــب‬\n‫خطــاب التعميــد الصــادر مــن فــرع هيئــة التحقيــق واإلدعــاء العــام بجازان‬\n‫حرفيــا‬\n   ‫ً‬     ‫رقــم (‪ ).....‬وتاريــخ ‪1434/8/29‬ه ـ ونــص الئحــة الدعــوى العامــة‬\n                            ‫احلمد هلل والصالة والسالم على رسول اهلل وبعد‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة أحــد‬\n‫املســارحة أدعــي علــى ‪:‬ـ‪ 25.....‬عامــا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدني رقم ‪(.....‬عزب‪ /‬متعلم‪ /‬متسبب ) أودع بشعبة سجن جازان العام‬\n‫( قســم ســجن أحــد املســارحة ) مبوجــب أمــر متديــد التوقيــف واإلحالــة‬\n‫رقــم(‪ ).....‬وتاريــخ ‪1433/12/28‬ه ـ لكــون جرميتــه مــن اجلرائــم املوجبــة‬\n‫للتوقيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ‬\n               ‫ويعتبــر إيقافــه مــن تاريــخ القبــض عليــه يف ‪1433/12/9‬ه ـ ‪.‬‬\n‫أنــه يف متــام الســاعة الثالثــة والنصــف مــن صبــاح يــوم اخلميــس املوافــق‬\n‫‪1433/12/9‬ه ـ وأثنــاء قيــام إحــدى دوريــات شــرطة محافظــة احلــرث‬\n\n\n                                                                                        ‫‪476‬‬\n\f      ‫بواجبهــا امليدانــي يف املوقــع املســمى قــرى ‪.....‬وبالتحديــد اخلــط الترابــي‬\n      ‫املــؤدي إلــى قريــة ‪.....‬مت مشــاهدة ســيارة مــن نــوع ‪......‬موديــل ‪ 2010‬م‬\n      ‫حتمــل اللوحــة رقــم (‪ ).....‬تعــود ملكيتهــا ( للمدعــى عليــه ) وبقيادتــه‪،‬‬\n      ‫وعنــد اســتيقافها رفــض االمتثــال بالوقــوف والذ بالفــرار متجه ـ ًا إلــى‬\n      ‫قريــة ‪.....‬بســرعة عاليــة علــى اخلــط الترابــي فتــم إطــاق ثــاث طلقــات‬\n      ‫حتذيريــة إال أنــه واصــل ســيره رافض ـ ًا الوقــوف وأثنــاء املطــاردة كان‬\n      ‫الغبــار كثيفـ ًا ممــا أدى إلــى انحــراف ســيارة الدوريــة وانقالبهــا وإصابــة‬\n      ‫أفرادهــا بجــروح ســطحية(فرزت لــه أوراق لــدى شــرطة احلــرث بشــأن‬\n      ‫احلــادث)وكان بالقــرب مــن املوقــع دوريــة أخــرى وعنــد ســماع البــاغ‬\n      ‫قامــت الدوريــة علــى الفــور مبتابعــة الســيارة حتــى وصلــت إلــى قريــة‬\n      ‫‪.....‬وبعدهــا قــام بإيقــاف الســيارة بعــد أن تعطلــت والذ بالفــرار داخــل‬\n      ‫املنــازل ومت ضبــط الســيارة وبتفتيشــها عثــر بداخلهــا كميــة مــن نبــات‬\n      ‫أخضــر يشــتبه أن يكــون مــن نبــات القــات احملظــور بلــغ وزنهــا (‪. 974‬‬\n      ‫‪10‬كجم)عشــرة كيلــو وتســعمائة وأربعــة وســبعني جــرام وعــن طريــق‬\n      ‫أحــد املصــادر أفــاد بأنــه قــام بركــوب ســيارة مــن نــوع ‪....‬موديــل ‪1985‬م‬\n      ‫اللــون (‪ ).......‬وأنهــا متجهــة إلــى محافظــة ‪ ،....‬ومت القبــض علــى مــن‬\n      ‫كان يف الســيارة مــن قبــل دوريــات ‪ ....‬وهــم كلٌ مــن ( املدعــى عليــه‬\n      ‫) واملدعو‪...../‬و‪.....‬و‪(.....‬فــرزت لهــم أوراق مســتقلة لعرضهــا علــى جلنــة‬\n      ‫العفو)اثبــت التقريــر الكيميائــي الشــرعي رقم(‪).....‬لعام‪1433‬ه ـ‬\n      ‫الصــادر مــن املستشــفى إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور باســتجواب ( املدعــى عليــه ) بعــد مواجهتــه‬\n      ‫بالتهمــة املنســوبة إليــه أقــر بــأن كميــة القــات املضبوطــة والبالــغ‬\n      ‫وزنهــا(‪10 . 974‬كجــم) عشــرة كيلــو وتســعمائة وأربعــة وســبعني‬\n\n\n‫‪477‬‬\n\f‫جرام ـ ًا تعــود لــه حصــل عليهــا بالشــراء مــن شــخص ال يعرفــه مببلــغ‬\n‫(‪)200‬مائتــي ريــال وأن غرضــه منهــا إيصالهــا إلــى قريــة ‪.....‬لصالــح‬\n‫كل مــن املدعــو‪..... /‬و‪.....‬و‪.....‬مقابــل مبلــغ مالــي قــدره (‪ )200‬مائتــي‬\n‫ريــال وأقــر بقيامــه بالهــروب مــن رجــال األمــن وأنــه قــام باالتصــال علــى‬\n‫املدعو‪...../‬بعــد هروبــه مــن الســيارة واخبــره بأنــه مت ضبــط الســيارة‬\n‫وطلــب منــه ‪.....‬مقابلتــه عنــد احملطــة يف الشــارع العــام بقريــة ‪.....‬وقــام‬\n‫مبقابلتــه والركــوب معــه وقــد أســفر التحقيــق مــع ( املدعــى عليــه )‬\n‫عــن توجيــه االتهــام إليــه بنقــل مــا وزنــه (‪10 . 974‬كجــم) عشــرة كيلــو‬\n‫وتســعمائة وأربعــة وســبعني جرام ـ ًا مــن نبــات القــات احملظــور بقصــد‬\n‫الترويــج وهروبــه مــن رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة‬\n                         ‫بعــد هروبــه ؛ وتســتره علــى مصــدر مــا مت ضبطــه ‪:‬‬\n                                                  ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ /1‬مــا جــاء يف إقــراره املــدون ص(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــة رقــم‬\n                                                                            ‫(‪. )16‬‬\n          ‫‪ /2‬محضر القبض والتفتيش املنوه عنه املرفق لفة رقم (‪. )2-1‬‬\n        ‫‪ / 3‬التقرير الكيميائي الشرعي املنوه عنه املرفق لفه رقم (‪.)26‬‬\n                                  ‫‪ /4‬مراوغته وتناقض أقواله أثناء التحقيق ‪.‬‬\n‫وبالبحــث عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى ‪:‬ترويــج‬\n                               ‫القــات‪ ،‬والثانيــة والثالثــة ‪ :‬ســرقة ســيارات ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه ( املدعــى عليــه ) فعــل محــرم شــرع ًا ومعاقــب‬\n‫عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا‬\n                                       ‫حلــق بــه مــن تعديــات لــذا أطلــب اآلتــي ‪:‬‬\n‫‪/1‬إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املادة(الثالثة)‬\n\n\n                                                                                         ‫‪478‬‬\n\f      ‫مــن القــرار الــوزاري املشــار إليــه إنفــاذ ًا لألمــر الســامي الكــرمي‬\n      ‫رقــم(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وتشــديد العقوبــة عليــه لقــاء تعدد‬\n                                                                              ‫ســوابقه‪.‬‬\n                ‫‪ /2‬احلكم بتعزيره شرع ًا لقاء تستره على مصدر ما مت ضبطه ‪.‬‬\n      ‫‪/3‬احلكــم بتعزيــره شــرع ًا لقــاء تســببه يف انقــاب ســيارة الدوريــة بعــد‬\n                                                                                ‫هروبــه ‪.‬‬\n      ‫‪ /4‬احلكــم مبصــادرة الســيارة نــوع( ‪) .....‬حتمــل اللوحــة رقــم(‪).....‬‬\n      ‫رقــم الهيــكل (‪).....‬العائــدة ملكيتهــا للمتهــم واملســتخدمة يف اجلرميــة‬\n      ‫وبســؤال املدعــى عليــه اجلــواب أجــاب معترفـ ـ ًـا بالقبــض عليــه بتاريــخ‬\n      ‫‪1433/12/9‬ه ـ مــن قبــل رجــال األمــن بعــد هروبــه مــن قبضتهم وتســببه‬\n      ‫يف انقــاب ســيارة الدوريــة أثنــاء هروبــه وبحوزتــه (‪10 . 974‬كجــم)‬\n      ‫عشــرة كيلــو وتســعمائة وأربعــة وســبعني جرام ـ ًا مــن نبــات القــات‬\n      ‫احملظــور ذكــر أن غرضــه مــن تلــك الكميــة هــو ن ــقلها مــن قريــة ‪.....‬‬\n      ‫إلــى قريــة ‪.....‬لصالــح كال مــن ‪..... /‬و ‪..... /‬و ‪..... /‬مقابــل أجــرة ماليــة‬\n      ‫قدرها(‪)200‬مائتــي ريــال ســعودي ؛ وصــادق علــى الســوابق املوضحــة‬\n      ‫يف بطاقــة بصمــات العشــرية ‪.‬وبالرج ــوع إلــى أوراق املعاملــة وجــدت أن‬\n      ‫الـت ــقرير الكيميائــي الـش ــرعي ومحضــر الــوزن يتطابقــان مع ما ورد يف‬\n      ‫الئحــة الدعــوى وأن للم ــدعى عليــه ثــاث ســوابق األولــى ‪ :‬ترويــج القــات‬\n                                              ‫؛ والثانيــة والثالثــة ‪ :‬ســرقة ســيارات ‪.‬‬\n      ‫ـاء علــى مــا ت ــقدم يف الدع ــوى والـج ــواب ومــا ورد يف الـت ــقرير‬    ‫وبـنـ ـ ً‬\n      ‫ـرعا‬\n         ‫ـدي ش ـ ً‬‫الك ــيميائي وم ــحضر الــوزن وكــرت الســوابق فقــد ثبــت لـ ّ‬\n      ‫إدان ــة املدعــى عليــه ‪..... /‬بالقبــض عليــه بتاريــخ ‪1433/12/9‬ه ـ مــن‬\n      ‫قبــل رجــال األمــن بعــد هروبــه مــن قبضتهــم وتســببه يف انقــاب ســيارة‬\n\n\n‫‪479‬‬\n\f‫الدوريــة أثنــاء هروبــه وبحوزتــه كميــة مــن نبــات القــات احملظــور تــزن‬\n‫(‪10 . 974‬كجــم) عشــرة كيلــو وتســعمائة وأربعــة وســبعني جرام ـ ًا‬\n‫لغــرض النقــل لصالــح الغيــر مقابــل األجــر املــادي ؛ وهــو يســتحق التعزيــر‬\n‫علــى مــا أديــن بــه إنفــا ًذا لألمــر الســامي الكــرمي رقــم (‪)59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وفــق املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫وتاريــخ ‪1374/2/1‬ه ـ واملعدلــة بقــرار وزيــر الداخليــة رقــم (‪)2057‬‬\n‫وتاريــخ ‪1404 /5/26‬ه ـ والتشــديد يف حقــه نظـ ًـرا لهروبــه مــن قبضــة‬\n‫رجــال األمــن وتســببه يف انقــاب ســيارة الدوريــة أثنــاء هروبــه ؛ إضافــة‬\n‫إلــى وجــود ســوا بــق لــه ؛ لــذا فقــد حكمــت بسج ــنه ملــدة خ ــمس ســنوات‬\n‫ـارا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة يف ‪1433/12/9‬ه ـ‬      ‫اعتبـ ً‬\n‫وجلــده ب ــسبعمائة جلــدة عل ًنــا مفرقــة علــى دفعــات بواقــع خ ــمسني جلــدة‬\n‫لــكل دفعــة بــن الدفعــة والتــي تليهــا خ ــمسة أيــام ؛ وغرامة ماليــة قدرها‬\n‫عشــرة آالف ريــال ســعودي تــودع لصالــح بيــت مــال املســلمني ؛ ومصــادرة‬\n‫ثانيــا ‪/‬‬\n       ‫وإتــاف كميــة نبــات القــات املضبوطــة بواســطة اجلهــة املختصــة ً‬\n‫قــررت مصــادرة الســيارة نــوع ( ‪ ) ....‬صنــع ســنة ‪ 2010‬م حتمــل اللوحــة‬\n‫رقــم (‪ ).....‬ورقــم الهيــكل (‪ ).....‬العائــدة ملكيتهــا للمدعــى عليــه‬\n‫واملســتخدمة يف اجلرميــة وذلــك ببيعهــا وإيــداع ثمنهــا يف حســاب اإلدارة‬\n‫العامــة ملكافحــة املخــدرات وفق ـ ًـا لقــرار مجلــس الــوزراء املوقــر رقــم‬\n‫(‪)47‬تاريــخ ‪ 1421/2/18‬ه ـ وذلــك يف ضــوء الفقــرة (‪ )1‬مــن املــادة(‪)53‬‬\n‫مــن ذات النظــام هــذا مــا ان ــتهت إليــه ال ــقضية وبــه حكمــت يف احلــق‬\n‫العــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه عــدم قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام اعتراضــه عليــه وطلبــا اســتئنافه دون تقــدمي الئحــة‬\n‫اعتراضيــة فأجبتهمــا لطلبهمــا ‪ .‬وصلــى اهلل علــى ســيدنا مح ــمد وآلــه‬\n\n\n                                                                                     ‫‪480‬‬\n\f                                                                        ‫وصحبــه وســلم‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342146007‬وتاريــخ ‪1434/10/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34325520‬وتاريــخ‬\n      ‫‪1434/9/24‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪..... /‬يف قضيــة‬\n      ‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                                  ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪481‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":474,"source_page_end":481,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b256aa3adc591d1b934642df477402674d1edb74ff77e19f2976eac3a44fcbb9","normalized_text_hash":"2d2724033f868c4c3c5f10b0e8ee4265ad65cc47043fb2bd2a2b9db83d2303eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p474-34325520"},{"id":"25b9ef86-8bd1-5238-bd9e-8c564b5b4ce4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -توسط يف بيع احلبوب احملظورة الكبتاجون -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال وإلغاء الشريحة املستخدمة يف اجلرمية.","document_number":"34205167","case_number":"34440251","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -توسط يف بيع احلبوب احملظورة الكبتاجون -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال وإلغاء الشريحة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪34205167 :‬تاريخه‪1434/5/4 :‬هـ‬\n                   ‫رقم الدعوى‪34440251:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34236440‬تاريخه‪1434/6/11 :‬هـ‬\n\n\n‫مخدرات ‪ -‬ترويج احلبوب احملظورة ‪ -‬توسط يف بيع احلبوب احملظورة‬\n‫الكبتاجــون ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬عــدم‬\n‫وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن‬\n ‫الســفر ومبصــادرة اجلــوال وإلغــاء الشــريحة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )56‬واملــادة (‪)60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات احلبــوب‬\n‫احملظــورة «الكبتاجــون» ‪ -‬مت القبــض علــى املدعــى عليــه وهــو يســلم‬\n‫املصــدر الســري حبــوب الكبتاجــون ‪ ،‬أقــر املدعــى عليــه بالترويــج‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫الكبتاجــون املخــدر‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه بتعزيــره شــرع ًا ومنعــه مــن الســفر خــارج البــاد بعــد انقضــاء‬\n‫محكوميتــه ومصــادرة جوالــه املســتخدم يف اجلرميــة‪ ،‬ومصادرة الســيارة‬\n‫وإلغــاء الشــريحة وعــدم صرفهــا مــرة أخــرى إلســاءة اســتخدامها ‪.‬‬\n\n                                                                                 ‫‪482‬‬\n\f      ‫حكمــت احملكمــة بثبــوت إدانــة املدعــى عليــه بقيامــه بالتوســط يف‬\n      ‫بيــع احلبــوب احملظــورة‪ ،‬قــررت احملكمــة احلكــم علــى املدعــى عليــه‬\n      ‫بتعزيــره للتهــم والقرائــن بالســجن ملــدة اثنــي عشــر شــهرا اعتبــارا مــن‬\n      ‫تاريــخ دخولــه الســجن‪ ،‬وجلــده مائتــي جلــدة علنــا علــى أربعــة دفعــات‬\n      ‫كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة عشــر يومــا‪،‬‬\n      ‫وتغرميــه مبلغـ ًا وقــدره ألــف ري ــال‪ ،‬مصــادرة اجلــوال املســتخدم يف ترويــج‬\n      ‫احلبــوب احملظــورة وإلغــاء الشــريحة املســجلة باســمه وعــدم صرفهــا لــه‬\n      ‫مــرة أخــرى‪ ،‬واملنــع مــن الســفر خلــارج البــاد بعــد تنفيــذ محكوميتــه‬\n      ‫ملــدة ســنتني‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق‬\n                                        ‫احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪1434/01/24..........‬ه ـ املقيــدة باحملكمة برقم‬\n      ‫‪..........‬وتاريخ ‪1434/01/24‬هـ ففي يوم األحد املوافق‪1434/04/21‬هـ‬\n      ‫افتتحــت اجللســة الســاعة ‪09 : 00‬وفيهــا حضــر املدعــي العــام ‪.......... /‬‬\n      ‫واملكلف بحضور اجللسات باخلطاب رقــم ( ‪ )..........‬يف ‪1433/3/22‬هـ‬\n      ‫وادعــى علــى احلاضــر معــه باملجلــس الشــرعي الســجني ‪.......... /‬ســعودي‬\n      ‫بالســجل املدني رقم (‪ )..........‬قائال يف دعواه ‪ :‬بتاريخ ‪1433/11/11‬هـ‬\n      ‫وردت معلومــات ملكافحــة املخــدرات مــن أحــد املصــادر بــان املدعــى‬\n      ‫ـاء عليهــا مت تكليــف احــد األفــراد بتمثيــل‬\n                                                   ‫عليــه مــن مروجــي احلبــوب و بنـ ً‬\n      ‫دور املشــتري وقــد ورد إتصــال مــن جــوال املصــدر علــى الفــرد ممثــل‬\n\n‫‪483‬‬\n\f‫دور الشــراء يفيــد بــأن املــروج لديــه خمــس وعشــرون حبــة مــن حبــوب‬\n‫الكبتاجــون ويرغــب يف بيعهــا ومتواجــد مبحافظــة صبيــا وقــام املصــدر‬\n‫بتزويــد الفــرد ممثــل دور الشــراء جــوال املــروج رقــم‪........../‬ويف احلاديــة‬\n‫عشــرة والنصــف مت االتصــال علــى املــروج مــن جــوال الفــرد وكان‬\n‫علــى مســمع مــن الفرقــة وطلــب الفــرد مــن املــروج كميــة مــن حبــوب‬\n‫الكبتاجــون فــرد عليــه أنــه توجــد خمــس وعشــرون حبــة فقــط وإذا‬\n‫يرغــب يف شــرائها عليــه احلضــور حملافظــة (‪ )........‬وأن قيمــة احلبــوب‬\n‫ســبعمائة وخمســون ريــال فوافــق الفــرد ممثــل دور الشــراء علــى ذلــك‬\n‫وطلــب املــروج مــن الفــرد عنــد وصولــه محافظــة (‪ )........‬عنــد البنــك ‪...‬‬\n‫االتصــال عليــه وانتهــت املكاملــة فتــم االنتقــال بالفرقــة إلــى محافظــة‬\n‫صبيــا ومت إعــداد خطــة للقبــض علــى املــروج ومت توزيــع الفرقــة حــول‬\n‫املوقــع املتفــق عليــه ومت تكليــف فــرد آخــر مــع الفــرد ممثــل دور الشــراء‬\n‫ومت تزويــده باملبلــغ احلكومــي املتفــق عليــه يف شــراء كمية احلبوب وعند‬\n‫وقوفهــم أمــام البنــك ‪ ...‬وكانــوا حتــت أنظــار الفرقــة حضــرت ســيارة‬\n‫مــن نــوع ‪ ....‬موديــل ‪ 2011‬رقــم اللوحــة (‪ )..........‬ونــزل منهــا شــخص وقــام‬\n‫بالركــوب مــع الفرديــن وطلــب الفــرد ممثــل دور الشــراء منــه الكميــة‬\n‫فــرد عليــه بــأن كميــة احلبــوب املتفــق عليهــا عنــد شــخص مينــي آخــر‬\n‫وأنــه ال يقــوم ببيعهــا بــل يقــوم بتوجيههــم لــه وهــو مــن ســيقوم بتســليمهم‬\n‫الكميــة فطلــب الفــرد منــه اإلتصــال علــى الشــخص اليمنــي التــي‬\n‫بحوزتــه كميــة احلبــوب وأبلغــه بــأن الفــرد معــه ومتجهــن إليــه الســتالم‬\n‫كميــة احلبــوب واســتالم املبلــغ ‪ ،‬عندهــا حتــرك الفرديــن ومعهمــا املــروج‬\n‫الــذي اتضــح أنــه وســيط إلــى صاحــب الكميــة الــذي يســكن حــارة‬\n‫‪..........‬بصبيــا ومتــت متابعتهــم مــن الفرقــة وعنــد وصولهــم بالقــرب مــن‬\n\n\n                                                                                      ‫‪484‬‬\n\f      ‫منــزل صاحــب الكميــة وطلــب منــه اخلــروج إلــى الشــارع وأعطــاه احلبــوب‬\n      ‫وأخــذ املبلــغ وعنــد توقــف ســيارة الفرديــن والوســيط خــرج شــخص مــن‬\n      ‫احــد املنــازل وبيــده كيــس وعنــد اقترابــه مــن الســيارة ونــزول الفــرد‬\n      ‫ممثــل دور املشــتري قــام برمــي الكيــس والذ بالفــرار داخــل أحــد املنــازل‬\n      ‫ا ولكــون املنــزل يوجــد بــه عائلــة ولظــام‬   ‫حوالــي الســاعة الواحــدة لي ـ ً‬\n      ‫الليــل داخــل احلــي مت التحفــظ علــى الكيــس الــذي قــام برميــه وبداخلــه‬\n      ‫(‪ )19‬تســعة عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪ 1433‬ه ـ الصــادر مــن‬\n      ‫مركــز الســموم والكيميــاء الشــرعية مبكــة املكرمــة ومت القبــض‬\n      ‫علــى املدعــى عليــه واتضــح أن اســم صاحــب الكميــة يدعــى‪............. /‬‬\n      ‫اجلنســية ومــن أكبــر املروجــن للحبــوب املخــدرة (‪ )........‬والزال البحــث‬\n      ‫جــاري عنــه القبــض عليــه ‪ ،‬وباســتجواب املدعــى عليــه والتحقيــق معــه‬\n      ‫أســفر التحقيــق عــن توجيــه االتهــام إليــه بالتوســط يف بيــع عــدد (‪)19‬‬\n      ‫تســع عشــرة حبــة يشــتبه أن تكــون مــن حبــوب الكبتاجــون احملظــورة‬\n      ‫عــن طريــق االتفــاق واملســاعدة وذلــك لألدلــة والقرائــن املرفقــة بــأوراق‬\n      ‫القضيــة وحيــث إمنــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا ومعاقــب‬\n      ‫عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب‬\n      ‫‪ -1‬إثبــات مــا أســند إليــه واحلكــم بتعزيــره شــرع ًا يف ضــوء املــادة (‪)38‬‬\n      ‫مــن ذات النظــام و التشــديد عليــه اســتنادا لتعميــم صاحــب الســمو‬\n      ‫امللكــى وزيرالداخليــه رقــم ‪ 8346‬يف ‪1427/2/8‬ه ـ خلطورتة احلبوب يف‬\n      ‫تدميــر مراكــز نهايــة االعصــاب املركزيــه باملــخ ‪-2‬احلكــم مبنعــه مــن‬\n      ‫الســفر خــارج البــاد بعــد انقضــاء محكومتيــه اســتنادا للفقــرة األولــى‬\n\n\n‫‪485‬‬\n\f‫مــن املــادة (‪ )56‬مــن ذات النظــام‪ -3‬مصــادرة الســيارة نــوع ‪ .....‬موديــل (‬\n‫‪ ) 2011‬ـرقم اللوحة (‪ )..........‬استنادا للفقرة ‪ 1‬من املادة ( ‪ ) 53‬من ذات‬\n‫النظــام وإيــداع قيمتهــا لــدى حســاب اإلدارة العامــة ملكافحــة املخــدرات‬\n‫اســتناد ًا للقــرار الــوزاري رقــم ‪ 47‬وتاريــخ ‪1421/2/18‬ه ـ ومصــادرة‬\n‫اجلــوال املســتخدم يف اجلرميــة نــوع ‪........‬الرقــم املصنعــي (‪ )..........‬اســتناد ًا‬\n‫للفقــرة ‪ 1‬مــن املــادة ‪ 53‬مــن ذات النظــام وإيــداع قيمتهــا لــدى حســاب‬\n‫اإلدارة العامــة ملكافحــة املخــدرات اســتناد ًا للقــرار الــوزاري رقــم ‪47‬‬\n‫وتاريــخ ‪1421/2/18‬ه ـ ‪ .‬وإلغــاء الشــريحة اخلاصــة باجلوال رقــم (‪)..........‬‬\n‫وعدم صرفها مرة أخرى ملن أســاء اســتخدامها اســتناد ًا لتعميم صاحب‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬وتاريــخ ‪1428/2/10_9‬ه ـ ‪.‬‬\n‫وبســؤال املدعــى عليــه أجــاب قائــا ‪ :‬أعتــرف بتوســطي يف بيــع مــا‬\n‫عــدده (‪ )19‬ـ تســع عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة عــن‬\n‫طريــق اإلتفــاق واملســاعدة يف ذلــك بهــذا أجــاب ‪ ،‬وبســؤاله عــن الســيارة‬\n‫قــال الســيارة عائــدة للشــركة للبيــع بالتقســيط ومؤجــرة علــي بعقــد‬\n‫إيجــار ينتهــي بالتمليــك ‪ .‬وباإلطــاع علــى أوراق القضيــة وجــد ضمنهــا‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪ 1433‬ه ــو املتضمــن‬\n‫ثبــوت إيجابيــة العينــة املرســلة مــن الكميــة حلبــوب اإلمفيتامــن املنبهــة‬\n‫احملظــورة ‪ ،‬كمــا وجــد كــرت بصمــات املدعــى عليــه واملتضمــن عــدم‬\n‫وجــود ســوابق عليــه ‪ ،‬وعليــه ف ــبناء علــى ســماع الدعــوى واإلجابــة فقــد‬\n‫ثبــت لــدي شــرعا إدانــة املدعــى عليــه ‪ 0000 /‬بقيامــه بالتوســط يف بيــع‬\n‫( ‪19‬حبــة ) ـ تســع عشــرة حبــة مــن حبــوب الكبتاجــون احملظــورة عــن‬\n‫طريــق اإلتفــاق واملســاعدة ويســتحق التعزيــر علــى ذلــك وفــق املــادة ( ‪38‬‬\n‫) مــن نظــام مكافحــة املخــدرات إال أنــه نظــرا لعــدم وجــود ســوابق عليــه‬\n\n\n                                                                                            ‫‪486‬‬\n\f      ‫ولكونــه يعــول أســرة وإلظهــاره ندمــه وتوبتــه واســتنادا للمــادة رقــم (‪) 60‬‬\n      ‫مــن ذات النظــام لــذا فقــد حكمــت بتعزيــره بالســجن ملــدة إثنــا عشــر‬\n      ‫شــهرا إعتبــارا مــن تاريــخ دخولــه الســجن وجلــده مائتــي جلــدة علنــا علــى‬\n      ‫أربــع دفعــات كل دفعــة خمســون جلــدة بينهــا وبــن التــي تليهــا خمســة‬\n      ‫عشــر يومــا وتغرميــه مبلــغ وقــدره ألــف ريــال ومصــادرة اجلــوال املســتخدم‬\n      ‫يف ترويــج احلبــوب احملظــورة وإلغــاء الشــريحة املســجلة باســمه وعــدم‬\n      ‫صرفهــا للمدعــى عليــه مــرة أخــرى وصرفــت النظــر عــن طلــب املدعــي‬\n      ‫العــام مصــادرة الســيارة لكونهــا ليســت ملــكا للمدعــى عليــه ومنعــه‬\n      ‫مــن الســفر خــارج البــاد بعــد تنفيــذ محكوميتــه ملــدة ســنتني بذلــك‬\n      ‫حكمــت وأفهمــت املدعــى عليــه باحلكــم فقــرر القناعــة وقــرر املدعــي‬\n      ‫العــام معارضتــه وطلــب رفــع احلكــم حملكمــة اإلســتئناف بالئحــة‬\n      ‫إعتراضيــة وبــه حــرر يف ‪1434/4/21‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم‪،،،‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/5/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪.......... /‬برقــم ‪..........‬وتاريــخ ‪1434/5/4‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ (.......... /‬ســعودي اجلنســية ) يف قضيــة (‬\n      ‫مخــدرات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n                              ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n‫‪487‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":482,"source_page_end":487,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"46cac2a1762f92462a2ebccc43223c201f5ba5df1180019840a84e0c130bf3a5","normalized_text_hash":"1e3a23036a8b0fbd8d1371daf749fb1e9da7eec21a760335b08f3707afbcfc34","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p482-34205167"},{"id":"6c36372e-78a6-5d10-9622-cfc4a51a68b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -الوساطة يف بيع بقصد الترويج -قات -التعزير بالسجن واجللد والغرامة واإلبعاد عن الباد بعد إنفاذ العقوبة ورد املبلغ","document_number":"34340849","case_number":"34446231","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/6","year":"1434","subject":"مخدرات -الوساطة يف بيع بقصد الترويج -قات -التعزير بالسجن واجللد والغرامة واإلبعاد عن الباد بعد إنفاذ العقوبة ورد املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34340849 :‬تاريخه ‪1434/10/6 :‬هـ‬\n                     ‫رقم الدعوى‪34446231:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34364069‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n ‫مخدرات ‪ -‬الوســاطة يف بيع بقصد الترويج ‪ -‬قات ‪ -‬التعزير بالســجن‬\n ‫واجللــد والغرامــة واإلبعــاد عــن البــاد بعــد إنفــاذ العقوبــة ورد املبلــغ‬\n                                                                         ‫املرقــم ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قرار مجلس الوزراء رقم‪ 11‬يف ‪1374/2/1‬هـ‬\n                ‫‪ -2‬األمر السامي الكرمي رقم ‪ 59633‬يف ‪1432/12/9‬هـ‪.‬‬\n      ‫‪ -3‬املادة الثالثة من قرار وزير الداخلية رقم ‪2057‬يف ‪1404/5/26‬هـ‬\n                      ‫‪ -4‬القرار الوزاري رقم ‪ 3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بالوســاطة يف بيــع قــات بقصــد‬\n ‫الترويــج و طلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره وتشــديد العقوبة‬\n ‫لتعــدد ســوابقه وإبعــاده عــن البــاد بعــد تنفيــذ احلكــم وإلزامه بــرد املبلغ‬\n ‫احلكومــي املرقــم وقــدره مائــة ريــال ‪،‬حيــث مت االشــتباه باملدعــى عليــه‬\n ‫أثنــاء وقوفــه عنــد أحــد املنــازل يقــوم بترويــج القــات وعنــد ســؤاله عــن‬\n ‫مــكان بيــع القــات مــن قبــل أحــد أفــراد فرقــة املكافحــة قــام بإدخالــه‬\n ‫للمنــزل والتوســط لشــراء القــات وعنــد خروجــه مــن املنــزل برفقــة الفــرد‬\n ‫مت القبــض عليــه وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n\n                                                                                      ‫‪488‬‬\n\f      ‫املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه الدعــوى ‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بســجنه مــدة ســنتني تعزيــر ًا وجلــده‬\n      ‫خمســمائة جلــدة علنـ ًا مفرقــة كل دفعــة خمســون جلــدة وغرامــة ماليــة‬\n      ‫قدرهــا خمســة آالف ريــال تــودع يف بيــت مــال املســلمني وإبعــاده عــن‬\n      ‫البــاد بعــد تنفيــذ العقوبــة املقــررة بحقــه ورد املبلــغ احلكومــي املرقــم‬\n      ‫وقــدره مائــة ريــال وقنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫مكتفيـ ًا بالئحــة الدعــوى ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34446231‬وتاريــخ ‪1434/10/12‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 342294560‬وتاريــخ ‪1434/10/12‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق ‪1434/10/19‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬يف ‪1431/8/13‬ه ـ‬\n      ‫واملدعــى عليــه ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪).....‬‬\n      ‫وقــدم املدعــي العــام دعــوى محــررة تتضمن ‪ :‬أنه بتاريــخ ‪1434/8/19‬هـ‬\n      ‫وأثنــاء قيــام إحــدى فــرق مكافحــة املخــدرات بواجبهــا يف قريــة ‪.....‬مت‬\n      ‫االشــتباه يف املدعــى عليــه عندمــا كان واقف ـ ًا بجانــب منــزل ‪(.....‬متــت‬\n      ‫املخاطبــة بشــأنه) يقــوم بترويــج نبــات القــات احملظــور وعنــد نــزول أحــد‬\n      ‫أفــراد الفرقــة القابضــة وســؤاله عــن مــكان القــات قــام بإدخــال الفــرد‬\n      ‫للمنــزل وإيصالــه إلــى مــكان ترويــج نبــات القــات والتوســط لشــراء‬\n      ‫كميــه مــن نبــات القــات مببلــغ (‪ )100‬مائــه ريــال وأثنــاء خروجــه مــن‬\n\n‫‪489‬‬\n\f‫املنــزل برفقــة الفــرد مت القبــض عليــه ولــم يتــم القبــض علــى املروجــن‬\n‫لكــون املنــزل بــه عوائــل وبــوزن الكميــه املباعــة مــن نبــات القــات‬\n‫احملظــور بلــغ وزنها(‪200‬جــم ـ مائتــن جرامـاً) أثبــت التقريــر الكيميائي‬\n‫الشــرعي رقم(‪.....‬لعــام ‪1434‬هــ) إيجابيــة العينــة املرســلة مــن الكميــة‬\n‫املضبوطــة لنبــات القــات احملظــور وباســتجواب املدعــى عليــه املذكــور‬\n‫أقــر بالتوســط يف بيــع مــا وزنــه(‪ 200‬جــم ـ مائتــان جراماً)مــن نبــات‬\n‫القــات احملظــور لغــرض احلصــول علــى املــال لصالــح صاحــب املنــزل‪...../‬‬\n‫(متــت املخاطبــة بشــأنه)كما أقــر بــأن الذيــن يبيعــون القــات بداخــل‬\n‫املنــزل شــخصان همــا ‪.....‬و‪(.....‬متــت املخاطبــة بشــأنهما) وقــد أســفر‬\n‫التحقيــق مــع املدعــى عليــه عــن توجيــه االتهــام إليــه بالتوســط يف بيــع‬\n‫مــا وزنــه (‪200‬جــم ـ مائتــن جراماً)مــن نبــات القــات احملظــور بقصــد‬\n‫االجتــار املجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪1 :‬ـ مــا جــاء يف إقــراره املرفــق ‪ 2‬ـ مــا جــاء يف محضــر القبــض والتفتيــش‬\n‫املرفــق ‪3‬ـ التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق وبالبحــث‬\n‫عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى مخالفــة نظــام أمــن‬\n‫احلــدود مقترنــة بتهريــب القــات والثانيــة حيــازة القــات والثالثــة مخالفــة‬\n‫نظــام أمــن احلــدود وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فإنــي أطلــب ‪ -1 :‬إثبــات مــا‬\n‫أســند إليــه واحلكــم بتعزيــره يف ضــوء املادة(الثالثة)مــن القــرار الــوزاري‬\n‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وتشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه ‪ -2‬احلكــم‬\n\n\n                                                                                     ‫‪490‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":488,"source_page_end":490,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4cb980323a933ff15ebdc39eb019a51b876b528a816cf82874eac39a0fa7a242","normalized_text_hash":"00d47f75ed87aa5061ce9d4551579476670672523bbbd3790d918236ab2491c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p488-34340849"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
